window.TXB=window.TXB||{};TXB["svd/Gen"]={"1:1":"في البدء خلق الله السماوات والارض.","1:2":"وكانت الارض خربة وخالية وعلى وجه الغمر ظلمة وروح الله يرف على وجه المياه.","1:3":"وقال الله: «ليكن نور» فكان نور.","1:4":"وراى الله النور انه حسن. وفصل الله بين النور والظلمة.","1:5":"ودعا الله النور نهارا والظلمة دعاها ليلا. وكان مساء وكان صباح يوما واحدا.","1:6":"وقال الله: «ليكن جلد في وسط المياه. وليكن فاصلا بين مياه ومياه».","1:7":"فعمل الله الجلد وفصل بين المياه التي تحت الجلد والمياه التي فوق الجلد. وكان كذلك.","1:8":"ودعا الله الجلد سماء. وكان مساء وكان صباح يوما ثانيا.","1:9":"وقال الله: «لتجتمع المياه تحت السماء الى مكان واحد ولتظهر اليابسة». وكان كذلك.","1:10":"ودعا الله اليابسة ارضا ومجتمع المياه دعاه بحارا. وراى الله ذلك انه حسن.","1:11":"وقال الله: «لتنبت الارض عشبا وبقلا يبزر بزرا وشجرا ذا ثمر يعمل ثمرا كجنسه بزره فيه على الارض». وكان كذلك.","1:12":"فاخرجت الارض عشبا وبقلا يبزر بزرا كجنسه وشجرا يعمل ثمرا بزره فيه كجنسه. وراى الله ذلك انه حسن.","1:13":"وكان مساء وكان صباح يوما ثالثا.","1:14":"وقال الله: «لتكن انوار في جلد السماء لتفصل بين النهار والليل وتكون لايات واوقات وايام وسنين.","1:15":"وتكون انوارا في جلد السماء لتنير على الارض». وكان كذلك.","1:16":"فعمل الله النورين العظيمين: النور الاكبر لحكم النهار والنور الاصغر لحكم الليل والنجوم.","1:17":"وجعلها الله في جلد السماء لتنير على الارض","1:18":"ولتحكم على النهار والليل ولتفصل بين النور والظلمة. وراى الله ذلك انه حسن.","1:19":"وكان مساء وكان صباح يوما رابعا.","1:20":"وقال الله: «لتفض المياه زحافات ذات نفس حية وليطر طير فوق الارض على وجه جلد السماء».","1:21":"فخلق الله التنانين العظام وكل نفس حية تدب التي فاضت بها المياه كاجناسها وكل طائر ذي جناح كجنسه. وراى الله ذلك انه حسن.","1:22":"وباركها الله قائلا: «اثمري واكثري واملاي المياه في البحار. وليكثر الطير على الارض».","1:23":"وكان مساء وكان صباح يوما خامسا.","1:24":"وقال الله: «لتخرج الارض ذوات انفس حية كجنسها: بهائم ودبابات ووحوش ارض كاجناسها». وكان كذلك.","1:25":"فعمل الله وحوش الارض كاجناسها والبهائم كاجناسها وجميع دبابات الارض كاجناسها. وراى الله ذلك انه حسن.","1:26":"وقال الله: «نعمل الانسان على صورتنا كشبهنا فيتسلطون على سمك البحر وعلى طير السماء وعلى البهائم وعلى كل الارض وعلى جميع الدبابات التي تدب على الارض».","1:27":"فخلق الله الانسان على صورته. على صورة الله خلقه. ذكرا وانثى خلقهم.","1:28":"وباركهم الله وقال لهم: «اثمروا واكثروا واملاوا الارض واخضعوها وتسلطوا على سمك البحر وعلى طير السماء وعلى كل حيوان يدب على الارض».","1:29":"وقال الله: «اني قد اعطيتكم كل بقل يبزر بزرا على وجه كل الارض وكل شجر فيه ثمر شجر يبزر بزرا لكم يكون طعاما.","1:30":"ولكل حيوان الارض وكل طير السماء وكل دبابة على الارض فيها نفس حية اعطيت كل عشب اخضر طعاما». وكان كذلك.","1:31":"وراى الله كل ما عمله فاذا هو حسن جدا. وكان مساء وكان صباح يوما سادسا.","2:1":"فاكملت السماوات والارض وكل جندها.","2:2":"وفرغ الله في اليوم السابع من عمله الذي عمل. فاستراح في اليوم السابع من جميع عمله الذي عمل.","2:3":"وبارك الله اليوم السابع وقدسه لانه فيه استراح من جميع عمله الذي عمل الله خالقا.","2:4":"هذه مبادئ السماوات والارض حين خلقت يوم عمل الرب الاله الارض والسماوات","2:5":"كل شجر البرية لم يكن بعد في الارض وكل عشب البرية لم ينبت بعد لان الرب الاله لم يكن قد امطر على الارض ولا كان انسان ليعمل الارض.","2:6":"ثم كان ضباب يطلع من الارض ويسقي كل وجه الارض.","2:7":"وجبل الرب الاله ادم ترابا من الارض ونفخ في انفه نسمة حياة. فصار ادم نفسا حية.","2:8":"وغرس الرب الاله جنة في عدن شرقا ووضع هناك ادم الذي جبله.","2:9":"وانبت الرب الاله من الارض كل شجرة شهية للنظر وجيدة للاكل وشجرة الحياة في وسط الجنة وشجرة معرفة الخير والشر.","2:10":"وكان نهر يخرج من عدن ليسقي الجنة ومن هناك ينقسم فيصير اربعة رؤوس:","2:11":"اسم الواحد فيشون وهو المحيط بجميع ارض الحويلة حيث الذهب.","2:12":"وذهب تلك الارض جيد. هناك المقل وحجر الجزع.","2:13":"واسم النهر الثاني جيحون. وهو المحيط بجميع ارض كوش.","2:14":"واسم النهر الثالث حداقل. وهو الجاري شرقي اشور. والنهر الرابع الفرات.","2:15":"واخذ الرب الاله ادم ووضعه في جنة عدن ليعملها ويحفظها.","2:16":"واوصى الرب الاله ادم قائلا: «من جميع شجر الجنة تاكل اكلا","2:17":"واما شجرة معرفة الخير والشر فلا تاكل منها لانك يوم تاكل منها موتا تموت».","2:18":"وقال الرب الاله: «ليس جيدا ان يكون ادم وحده فاصنع له معينا نظيره».","2:19":"وجبل الرب الاله من الارض كل حيوانات البرية وكل طيور السماء فاحضرها الى ادم ليرى ماذا يدعوها وكل ما دعا به ادم ذات نفس حية فهو اسمها.","2:20":"فدعا ادم باسماء جميع البهائم وطيور السماء وجميع حيوانات البرية. واما لنفسه فلم يجد معينا نظيره.","2:21":"فاوقع الرب الاله سباتا على ادم فنام فاخذ واحدة من اضلاعه وملا مكانها لحما.","2:22":"وبنى الرب الاله الضلع التي اخذها من ادم امراة واحضرها الى ادم.","2:23":"فقال ادم: «هذه الان عظم من عظامي ولحم من لحمي. هذه تدعى امراة لانها من امرء اخذت».","2:24":"لذلك يترك الرجل اباه وامه ويلتصق بامراته ويكونان جسدا واحدا.","2:25":"وكانا كلاهما عريانين ادم وامراته وهما لا يخجلان.","3:1":"وكانت الحية احيل جميع حيوانات البرية التي عملها الرب الاله فقالت للمراة: «احقا قال الله لا تاكلا من كل شجر الجنة؟»","3:2":"فقالت المراة للحية: «من ثمر شجر الجنة ناكل","3:3":"واما ثمر الشجرة التي في وسط الجنة فقال الله: لا تاكلا منه ولا تمساه لئلا تموتا».","3:4":"فقالت الحية للمراة: «لن تموتا!","3:5":"بل الله عالم انه يوم تاكلان منه تنفتح اعينكما وتكونان كالله عارفين الخير والشر».","3:6":"فرات المراة ان الشجرة جيدة للاكل وانها بهجة للعيون وان الشجرة شهية للنظر. فاخذت من ثمرها واكلت واعطت رجلها ايضا معها فاكل.","3:7":"فانفتحت اعينهما وعلما انهما عريانان. فخاطا اوراق تين وصنعا لانفسهما مازر.","3:8":"وسمعا صوت الرب الاله ماشيا في الجنة عند هبوب ريح النهار فاختبا ادم وامراته من وجه الرب الاله في وسط شجر الجنة.","3:9":"فنادى الرب الاله ادم: «اين انت؟».","3:10":"فقال: «سمعت صوتك في الجنة فخشيت لاني عريان فاختبات».","3:11":"فقال: «من اعلمك انك عريان؟ هل اكلت من الشجرة التي اوصيتك ان لا تاكل منها؟»","3:12":"فقال ادم: «المراة التي جعلتها معي هي اعطتني من الشجرة فاكلت».","3:13":"فقال الرب الاله للمراة: «ما هذا الذي فعلت؟» فقالت المراة: «الحية غرتني فاكلت».","3:14":"فقال الرب الاله للحية: «لانك فعلت هذا ملعونة انت من جميع البهائم ومن جميع وحوش البرية. على بطنك تسعين وترابا تاكلين كل ايام حياتك.","3:15":"واضع عداوة بينك وبين المراة وبين نسلك ونسلها. هو يسحق راسك وانت تسحقين عقبه».","3:16":"وقال للمراة: «تكثيرا اكثر اتعاب حبلك. بالوجع تلدين اولادا. والى رجلك يكون اشتياقك وهو يسود عليك».","3:17":"وقال لادم: «لانك سمعت لقول امراتك واكلت من الشجرة التي اوصيتك قائلا: لا تاكل منها ملعونة الارض بسببك. بالتعب تاكل منها كل ايام حياتك.","3:18":"وشوكا وحسكا تنبت لك وتاكل عشب الحقل.","3:19":"بعرق وجهك تاكل خبزا حتى تعود الى الارض التي اخذت منها. لانك تراب والى تراب تعود».","3:20":"ودعا ادم اسم امراته «حواء» لانها ام كل حي.","3:21":"وصنع الرب الاله لادم وامراته اقمصة من جلد والبسهما.","3:22":"وقال الرب الاله: «هوذا الانسان قد صار كواحد منا عارفا الخير والشر. والان لعله يمد يده وياخذ من شجرة الحياة ايضا وياكل ويحيا الى الابد».","3:23":"فاخرجه الرب الاله من جنة عدن ليعمل الارض التي اخذ منها.","3:24":"فطرد الانسان واقام شرقي جنة عدن الكروبيم ولهيب سيف متقلب لحراسة طريق شجرة الحياة.","4:1":"وعرف ادم حواء امراته فحبلت وولدت قايين. وقالت: «اقتنيت رجلا من عند الرب».","4:2":"ثم عادت فولدت اخاه هابيل. وكان هابيل راعيا للغنم وكان قايين عاملا في الارض.","4:3":"وحدث من بعد ايام ان قايين قدم من اثمار الارض قربانا للرب","4:4":"وقدم هابيل ايضا من ابكار غنمه ومن سمانها. فنظر الرب الى هابيل وقربانه","4:5":"ولكن الى قايين وقربانه لم ينظر. فاغتاظ قايين جدا وسقط وجهه.","4:6":"فقال الرب لقايين: «لماذا اغتظت ولماذا سقط وجهك؟","4:7":"ان احسنت افلا رفع. وان لم تحسن فعند الباب خطية رابضة واليك اشتياقها وانت تسود عليها».","4:8":"وكلم قايين هابيل اخاه. وحدث اذ كانا في الحقل ان قايين قام على هابيل اخيه وقتله.","4:9":"فقال الرب لقايين: «اين هابيل اخوك؟» فقال: «لا اعلم! احارس انا لاخي؟»","4:10":"فقال: «ماذا فعلت؟ صوت دم اخيك صارخ الي من الارض.","4:11":"فالان ملعون انت من الارض التي فتحت فاها لتقبل دم اخيك من يدك!","4:12":"متى عملت الارض لا تعود تعطيك قوتها. تائها وهاربا تكون في الارض».","4:13":"فقال قايين للرب: «ذنبي اعظم من ان يحتمل.","4:14":"انك قد طردتني اليوم عن وجه الارض ومن وجهك اختفي واكون تائها وهاربا في الارض فيكون كل من وجدني يقتلني».","4:15":"فقال له الرب: «لذلك كل من قتل قايين فسبعة اضعاف ينتقم منه». وجعل الرب لقايين علامة لكي لا يقتله كل من وجده.","4:16":"فخرج قايين من لدن الرب وسكن في ارض نود شرقي عدن.","4:17":"وعرف قايين امراته فحبلت وولدت حنوك. وكان يبني مدينة فدعا اسم المدينة كاسم ابنه حنوك.","4:18":"وولد لحنوك عيراد. وعيراد ولد محويائيل. ومحويائيل ولد متوشائيل. ومتوشائيل ولد لامك.","4:19":"واتخذ لامك لنفسه امراتين: اسم الواحدة عادة واسم الاخرى صلة.","4:20":"فولدت عادة يابال الذي كان ابا لساكني الخيام ورعاة المواشي.","4:21":"واسم اخيه يوبال الذي كان ابا لكل ضارب بالعود والمزمار.","4:22":"وصلة ايضا ولدت توبال قايين الضارب كل الة من نحاس وحديد. واخت توبال قايين نعمة.","4:23":"وقال لامك لامراتيه عادة وصلة: «اسمعا قولي يا امراتي لامك واصغيا لكلامي. فاني قتلت رجلا لجرحي وفتى لشدخي.","4:24":"انه ينتقم لقايين سبعة اضعاف واما للامك فسبعة وسبعين».","4:25":"وعرف ادم امراته ايضا فولدت ابنا ودعت اسمه شيثا قائلة: «لان الله قد وضع لي نسلا اخر عوضا عن هابيل». لان قايين كان قد قتله.","4:26":"ولشيث ايضا ولد ابن فدعا اسمه انوش. حينئذ ابتدئ ان يدعى باسم الرب.","5:1":"هذا كتاب مواليد ادم يوم خلق الله الانسان. على شبه الله عمله.","5:2":"ذكرا وانثى خلقه وباركه ودعا اسمه ادم يوم خلق.","5:3":"وعاش ادم مئة وثلاثين سنة وولد ولدا على شبهه كصورته ودعا اسمه شيثا.","5:4":"وكانت ايام ادم بعد ما ولد شيثا ثماني مئة سنة وولد بنين وبنات.","5:5":"فكانت كل ايام ادم التي عاشها تسع مئة وثلاثين سنة ومات.","5:6":"وعاش شيث مئة وخمس سنين وولد انوش.","5:7":"وعاش شيث بعد ما ولد انوش ثماني مئة وسبع سنين وولد بنين وبنات.","5:8":"فكانت كل ايام شيث تسع مئة واثنتي عشرة سنة ومات.","5:9":"وعاش انوش تسعين سنة وولد قينان.","5:10":"وعاش انوش بعد ما ولد قينان ثماني مئة وخمس عشرة سنة وولد بنين وبنات.","5:11":"فكانت كل ايام انوش تسع مئة وخمس سنين ومات.","5:12":"وعاش قينان سبعين سنة وولد مهللئيل.","5:13":"وعاش قينان بعد ما ولد مهللئيل ثماني مئة واربعين سنة وولد بنين وبنات.","5:14":"فكانت كل ايام قينان تسع مئة وعشر سنين ومات.","5:15":"وعاش مهللئيل خمسا وستين سنة وولد يارد.","5:16":"وعاش مهللئيل بعد ما ولد يارد ثماني مئة وثلاثين سنة وولد بنين وبنات.","5:17":"فكانت كل ايام مهللئيل ثماني مئة وخمسا وتسعين سنة ومات.","5:18":"وعاش يارد مئة واثنتين وستين سنة وولد اخنوخ.","5:19":"وعاش يارد بعد ما ولد اخنوخ ثماني مئة سنة وولد بنين وبنات.","5:20":"فكانت كل ايام يارد تسع مئة واثنتين وستين سنة ومات.","5:21":"وعاش اخنوخ خمسا وستين سنة وولد متوشالح.","5:22":"وسار اخنوخ مع الله بعد ما ولد متوشالح ثلاث مئة سنة وولد بنين وبنات.","5:23":"فكانت كل ايام اخنوخ ثلاث مئة وخمسا وستين سنة.","5:24":"وسار اخنوخ مع الله ولم يوجد لان الله اخذه.","5:25":"وعاش متوشالح مئة وسبعا وثمانين سنة وولد لامك.","5:26":"وعاش متوشالح بعد ما ولد لامك سبع مئة واثنتين وثمانين سنة وولد بنين وبنات.","5:27":"فكانت كل ايام متوشالح تسع مئة وتسعا وستين سنة ومات.","5:28":"وعاش لامك مئة واثنتين وثمانين سنة وولد ابنا.","5:29":"ودعا اسمه نوحا قائلا: «هذا يعزينا عن عملنا وتعب ايدينا بسبب الارض التي لعنها الرب».","5:30":"وعاش لامك بعد ما ولد نوحا خمس مئة وخمسا وتسعين سنة وولد بنين وبنات.","5:31":"فكانت كل ايام لامك سبع مئة وسبعا وسبعين سنة ومات.","5:32":"وكان نوح ابن خمس مئة سنة. وولد نوح: ساما وحاما ويافث.","6:1":"وحدث لما ابتدا الناس يكثرون على الارض وولد لهم بنات","6:2":"ان ابناء الله راوا بنات الناس انهن حسنات. فاتخذوا لانفسهم نساء من كل ما اختاروا.","6:3":"فقال الرب: «لا يدين روحي في الانسان الى الابد. لزيغانه هو بشر وتكون ايامه مئة وعشرين سنة».","6:4":"كان في الارض طغاة في تلك الايام. وبعد ذلك ايضا اذ دخل بنو الله على بنات الناس وولدن لهم اولادا - هؤلاء هم الجبابرة الذين منذ الدهر ذوو اسم.","6:5":"وراى الرب ان شر الانسان قد كثر في الارض وان كل تصور افكار قلبه انما هو شرير كل يوم.","6:6":"فحزن الرب انه عمل الانسان في الارض وتاسف في قلبه.","6:7":"فقال الرب: «امحو عن وجه الارض الانسان الذي خلقته: الانسان مع بهائم ودبابات وطيور السماء. لاني حزنت اني عملتهم».","6:8":"واما نوح فوجد نعمة في عيني الرب.","6:9":"هذه مواليد نوح: كان نوح رجلا بارا كاملا في اجياله. وسار نوح مع الله.","6:10":"وولد نوح ثلاثة بنين: ساما وحاما ويافث.","6:11":"وفسدت الارض امام الله وامتلات الارض ظلما.","6:12":"وراى الله الارض فاذا هي قد فسدت اذ كان كل بشر قد افسد طريقه على الارض.","6:13":"فقال الله لنوح: «نهاية كل بشر قد اتت امامي لان الارض امتلات ظلما منهم. فها انا مهلكهم مع الارض.","6:14":"اصنع لنفسك فلكا من خشب جفر. تجعل الفلك مساكن وتطليه من داخل ومن خارج بالقار.","6:15":"وهكذا تصنعه: ثلاث مئة ذراع يكون طول الفلك وخمسين ذراعا عرضه وثلاثين ذراعا ارتفاعه.","6:16":"وتصنع كوا للفلك وتكمله الى حد ذراع من فوق. وتضع باب الفلك في جانبه. مساكن سفلية ومتوسطة وعلوية تجعله.","6:17":"فها انا ات بطوفان الماء على الارض لاهلك كل جسد فيه روح حياة من تحت السماء. كل ما في الارض يموت.","6:18":"ولكن اقيم عهدي معك فتدخل الفلك انت وبنوك وامراتك ونساء بنيك معك.","6:19":"ومن كل حي من كل ذي جسد اثنين من كل تدخل الى الفلك لاستبقائها معك. تكون ذكرا وانثى.","6:20":"من الطيور كاجناسها ومن البهائم كاجناسها ومن كل دبابات الارض كاجناسه. اثنين من كل تدخل اليك لاستبقائها.","6:21":"وانت فخذ لنفسك من كل طعام يؤكل واجمعه عندك فيكون لك ولها طعاما».","6:22":"ففعل نوح حسب كل ما امره به الله. هكذا فعل.","7:1":"وقال الرب لنوح: «ادخل انت وجميع بيتك الى الفلك لاني اياك رايت بارا لدي في هذا الجيل.","7:2":"من جميع البهائم الطاهرة تاخذ معك سبعة سبعة ذكرا وانثى. ومن البهائم التي ليست بطاهرة اثنين: ذكرا وانثى.","7:3":"ومن طيور السماء ايضا سبعة سبعة: ذكرا وانثى. لاستبقاء نسل على وجه كل الارض.","7:4":"لاني بعد سبعة ايام ايضا امطر على الارض اربعين يوما واربعين ليلة. وامحو عن وجه الارض كل قائم عملته».","7:5":"ففعل نوح حسب كل ما امره به الرب.","7:6":"ولما كان نوح ابن ست مئة سنة صار طوفان الماء على الارض","7:7":"فدخل نوح وبنوه وامراته ونساء بنيه معه الى الفلك من وجه مياه الطوفان.","7:8":"ومن البهائم الطاهرة والبهائم التي ليست بطاهرة ومن الطيور وكل ما يدب على الارض:","7:9":"دخل اثنان اثنان الى نوح الى الفلك ذكرا وانثى. كما امر الله نوحا.","7:10":"وحدث بعد السبعة الايام ان مياه الطوفان صارت على الارض.","7:11":"في سنة ست مئة من حياة نوح في الشهر الثاني في اليوم السابع عشر من الشهر انفجرت كل ينابيع الغمر العظيم وانفتحت طاقات السماء.","7:12":"وكان المطر على الارض اربعين يوما واربعين ليلة.","7:13":"في ذلك اليوم عينه دخل نوح وسام وحام ويافث بنو نوح وامراة نوح وثلاث نساء بنيه معهم الى الفلك.","7:14":"هم وكل الوحوش كاجناسها وكل البهائم كاجناسها وكل الدبابات التي تدب على الارض كاجناسها وكل الطيور كاجناسها: كل عصفور كل ذي جناح.","7:15":"ودخلت الى نوح الى الفلك اثنين اثنين من كل جسد فيه روح حياة.","7:16":"والداخلات دخلت ذكرا وانثى من كل ذي جسد كما امره الله. واغلق الرب عليه.","7:17":"وكان الطوفان اربعين يوما على الارض. وتكاثرت المياه ورفعت الفلك فارتفع عن الارض.","7:18":"وتعاظمت المياه وتكاثرت جدا على الارض فكان الفلك يسير على وجه المياه.","7:19":"وتعاظمت المياه كثيرا جدا على الارض فتغطت جميع الجبال الشامخة التي تحت كل السماء.","7:20":"خمس عشرة ذراعا في الارتفاع تعاظمت المياه فتغطت الجبال.","7:21":"فمات كل ذي جسد كان يدب على الارض من الطيور والبهائم والوحوش وكل الزحافات التي كانت تزحف على الارض وجميع الناس.","7:22":"كل ما في انفه نسمة روح حياة من كل ما في اليابسة مات.","7:23":"فمحا الله كل قائم كان على وجه الارض: الناس والبهائم والدبابات وطيور السماء فانمحت من الارض. وتبقى نوح والذين معه في الفلك فقط.","7:24":"وتعاظمت المياه على الارض مئة وخمسين يوما.","8:1":"ثم ذكر الله نوحا وكل الوحوش وكل البهائم التي معه في الفلك. واجاز الله ريحا على الارض فهدات المياه.","8:2":"وانسدت ينابيع الغمر وطاقات السماء فامتنع المطر من السماء.","8:3":"ورجعت المياه عن الارض رجوعا متواليا. وبعد مئة وخمسين يوما نقصت المياه","8:4":"واستقر الفلك في الشهر السابع في اليوم السابع عشر من الشهر على جبال اراراط.","8:5":"وكانت المياه تنقص نقصا متواليا الى الشهر العاشر. وفي العاشر في اول الشهر ظهرت رؤوس الجبال.","8:6":"وحدث من بعد اربعين يوما ان نوحا فتح طاقة الفلك التي كان قد عملها","8:7":"وارسل الغراب فخرج مترددا حتى نشفت المياه عن الارض.","8:8":"ثم ارسل الحمامة من عنده ليرى هل قلت المياه عن وجه الارض","8:9":"فلم تجد الحمامة مقرا لرجلها فرجعت اليه الى الفلك لان مياها كانت على وجه كل الارض. فمد يده واخذها وادخلها عنده الى الفلك.","8:10":"فلبث ايضا سبعة ايام اخر وعاد فارسل الحمامة من الفلك","8:11":"فاتت اليه الحمامة عند المساء واذا ورقة زيتون خضراء في فمها. فعلم نوح ان المياه قد قلت عن الارض.","8:12":"فلبث ايضا سبعة ايام اخر وارسل الحمامة فلم تعد ترجع اليه ايضا.","8:13":"وكان في السنة الواحدة والست مئة في الشهر الاول في اول الشهر ان المياه نشفت عن الارض. فكشف نوح الغطاء عن الفلك ونظر فاذا وجه الارض قد نشف.","8:14":"وفي الشهر الثاني في اليوم السابع والعشرين من الشهر جفت الارض.","8:15":"وامر الله نوحا:","8:16":"«اخرج من الفلك انت وامراتك وبنوك ونساء بنيك معك.","8:17":"وكل الحيوانات التي معك من كل ذي جسد: الطيور والبهائم وكل الدبابات التي تدب على الارض اخرجها معك. ولتتوالد في الارض وتثمر وتكثر على الارض».","8:18":"فخرج نوح وبنوه وامراته ونساء بنيه معه.","8:19":"وكل الحيوانات وكل الطيور كل ما يدب على الارض كانواعها خرجت من الفلك.","8:20":"وبنى نوح مذبحا للرب. واخذ من كل البهائم الطاهرة ومن كل الطيور الطاهرة واصعد محرقات على المذبح","8:21":"فتنسم الرب رائحة الرضا. وقال الرب في قلبه: «لا اعود العن الارض ايضا من اجل الانسان لان تصور قلب الانسان شرير منذ حداثته. ولا اعود ايضا اميت كل حي كما فعلت.","8:22":"مدة كل ايام الارض زرع وحصاد وبرد وحر وصيف وشتاء ونهار وليل لا تزال».","9:1":"وبارك الله نوحا وبنيه وقال لهم: «اثمروا واكثروا واملاوا الارض.","9:2":"ولتكن خشيتكم ورهبتكم على كل حيوانات الارض وكل طيور السماء مع كل ما يدب على الارض وكل اسماك البحر. قد دفعت الى ايديكم.","9:3":"كل دابة حية تكون لكم طعاما. كالعشب الاخضر دفعت اليكم الجميع.","9:4":"غير ان لحما بحياته دمه لا تاكلوه.","9:5":"واطلب انا دمكم لانفسكم فقط. من يد كل حيوان اطلبه. ومن يد الانسان اطلب نفس الانسان من يد الانسان اخيه.","9:6":"سافك دم الانسان بالانسان يسفك دمه. لان الله على صورته عمل الانسان.","9:7":"فاثمروا انتم واكثروا وتوالدوا في الارض وتكاثروا فيها».","9:8":"وقال الله لنوح وبنيه:","9:9":"«وها انا مقيم ميثاقي معكم ومع نسلكم من بعدكم","9:10":"ومع كل ذوات الانفس الحية التي معكم: الطيور والبهائم وكل وحوش الارض التي معكم من جميع الخارجين من الفلك حتى كل حيوان الارض.","9:11":"اقيم ميثاقي معكم فلا ينقرض كل ذي جسد ايضا بمياه الطوفان. ولا يكون ايضا طوفان ليخرب الارض».","9:12":"وقال الله: «هذه علامة الميثاق الذي انا واضعه بيني وبينكم وبين كل ذوات الانفس الحية التي معكم الى اجيال الدهر:","9:13":"وضعت قوسي في السحاب فتكون علامة ميثاق بيني وبين الارض.","9:14":"فيكون متى انشر سحابا على الارض وتظهر القوس في السحاب","9:15":"اني اذكر ميثاقي الذي بيني وبينكم وبين كل نفس حية في كل جسد. فلا تكون ايضا المياه طوفانا لتهلك كل ذي جسد.","9:16":"فمتى كانت القوس في السحاب ابصرها لاذكر ميثاقا ابديا بين الله وبين كل نفس حية في كل جسد على الارض».","9:17":"وقال الله لنوح: «هذه علامة الميثاق الذي انا اقمته بيني وبين كل ذي جسد على الارض».","9:18":"وكان بنو نوح الذين خرجوا من الفلك ساما وحاما ويافث. وحام هو ابو كنعان.","9:19":"هؤلاء الثلاثة هم بنو نوح. ومن هؤلاء تشعبت كل الارض.","9:20":"وابتدا نوح يكون فلاحا وغرس كرما.","9:21":"وشرب من الخمر فسكر وتعرى داخل خبائه.","9:22":"فابصر حام ابو كنعان عورة ابيه واخبر اخويه خارجا.","9:23":"فاخذ سام ويافث الرداء ووضعاه على اكتافهما ومشيا الى الوراء وسترا عورة ابيهما ووجهاهما الى الوراء. فلم يبصرا عورة ابيهما.","9:24":"فلما استيقظ نوح من خمره علم ما فعل به ابنه الصغير","9:25":"فقال: «ملعون كنعان. عبد العبيد يكون لاخوته».","9:26":"وقال: «مبارك الرب اله سام. وليكن كنعان عبدا له.","9:27":"ليفتح الله ليافث فيسكن في مساكن سام. وليكن كنعان عبدا لهم».","9:28":"وعاش نوح بعد الطوفان ثلاث مئة وخمسين سنة.","9:29":"فكانت كل ايام نوح تسع مئة وخمسين سنة ومات.","10:1":"وهذه مواليد بني نوح: سام وحام ويافث. وولد لهم بنون بعد الطوفان.","10:2":"بنو يافث: جومر وماجوج وماداي وياوان وتوبال وماشك وتيراس.","10:3":"وبنو جومر: اشكناز وريفاث وتوجرمة.","10:4":"وبنو ياوان: اليشة وترشيش وكتيم ودودانيم.","10:5":"من هؤلاء تفرقت جزائر الامم باراضيهم كل انسان كلسانه حسب قبائلهم باممهم.","10:6":"وبنو حام: كوش ومصرايم وفوط وكنعان.","10:7":"وبنو كوش: سبا وحويلة وسبتة ورعمة وسبتكا. وبنو رعمة: شبا وددان.","10:8":"وكوش ولد نمرود الذي ابتدا يكون جبارا في الارض","10:9":"الذي كان جبار صيد امام الرب. لذلك يقال: «كنمرود جبار صيد امام الرب».","10:10":"وكان ابتداء مملكته بابل وارك واكد وكلنة في ارض شنعار.","10:11":"من تلك الارض خرج اشور وبنى نينوى ورحوبوت عير وكالح","10:12":"ورسن بين نينوى وكالح. (هي المدينة الكبيرة).","10:13":"ومصرايم ولد: لوديم وعناميم ولهابيم ونفتوحيم","10:14":"وفتروسيم وكسلوحيم. (الذين خرج منهم فلشتيم وكفتوريم).","10:15":"وكنعان ولد: صيدون بكره وحث","10:16":"واليبوسي والاموري والجرجاشي","10:17":"والحوي والعرقي والسيني","10:18":"والاروادي والصماري والحماتي. وبعد ذلك تفرقت قبائل الكنعاني.","10:19":"وكانت تخوم الكنعاني من صيدون حينما تجيء نحو جرار الى غزة وحينما تجيء نحو سدوم وعمورة وادمة وصبوييم الى لاشع.","10:20":"هؤلاء بنو حام حسب قبائلهم كالسنتهم باراضيهم واممهم.","10:21":"وسام ابو كل بني عابر اخو يافث الكبير ولد له ايضا بنون.","10:22":"بنو سام: عيلام واشور وارفكشاد ولود وارام.","10:23":"وبنو ارام: عوص وحول وجاثر وماش.","10:24":"وارفكشاد ولد شالح وشالح ولد عابر.","10:25":"ولعابر ولد ابنان: اسم الواحد فالج لان في ايامه قسمت الارض. واسم اخيه يقطان.","10:26":"ويقطان ولد الموداد وشالف وحضرموت ويارح","10:27":"وهدورام واوزال ودقلة","10:28":"وعوبال وابيمايل وشبا","10:29":"واوفير وحويلة ويوباب. جميع هؤلاء بنو يقطان.","10:30":"وكان مسكنهم من ميشا حينما تجيء نحو سفار جبل المشرق.","10:31":"هؤلاء بنو سام حسب قبائلهم كالسنتهم باراضيهم حسب اممهم.","10:32":"هؤلاء قبائل بني نوح حسب مواليدهم باممهم. ومن هؤلاء تفرقت الامم في الارض بعد الطوفان.","11:1":"وكانت الارض كلها لسانا واحدا ولغة واحدة.","11:2":"وحدث في ارتحالهم شرقا انهم وجدوا بقعة في ارض شنعار وسكنوا هناك.","11:3":"وقال بعضهم لبعض: «هلم نصنع لبنا ونشويه شيا». فكان لهم اللبن مكان الحجر وكان لهم الحمر مكان الطين.","11:4":"وقالوا: «هلم نبن لانفسنا مدينة وبرجا راسه بالسماء. ونصنع لانفسنا اسما لئلا نتبدد على وجه كل الارض».","11:5":"فنزل الرب لينظر المدينة والبرج اللذين كان بنو ادم يبنونهما.","11:6":"وقال الرب: «هوذا شعب واحد ولسان واحد لجميعهم وهذا ابتداؤهم بالعمل. والان لا يمتنع عليهم كل ما ينوون ان يعملوه.","11:7":"هلم ننزل ونبلبل هناك لسانهم حتى لا يسمع بعضهم لسان بعض».","11:8":"فبددهم الرب من هناك على وجه كل الارض فكفوا عن بنيان المدينة","11:9":"لذلك دعي اسمها «بابل» لان الرب هناك بلبل لسان كل الارض. ومن هناك بددهم الرب على وجه كل الارض.","11:10":"هذه مواليد سام: لما كان سام ابن مئة سنة ولد ارفكشاد بعد الطوفان بسنتين.","11:11":"وعاش سام بعد ما ولد ارفكشاد خمس مئة سنة وولد بنين وبنات.","11:12":"وعاش ارفكشاد خمسا وثلاثين سنة وولد شالح.","11:13":"وعاش ارفكشاد بعد ما ولد شالح اربع مئة وثلاث سنين وولد بنين وبنات.","11:14":"وعاش شالح ثلاثين سنة وولد عابر.","11:15":"وعاش شالح بعد ما ولد عابر اربع مئة وثلاث سنين وولد بنين وبنات.","11:16":"وعاش عابر اربعا وثلاثين سنة وولد فالج.","11:17":"وعاش عابر بعد ما ولد فالج اربع مئة وثلاثين سنة وولد بنين وبنات.","11:18":"وعاش فالج ثلاثين سنة وولد رعو.","11:19":"وعاش فالج بعد ما ولد رعو مئتين وتسع سنين وولد بنين وبنات.","11:20":"وعاش رعو اثنتين وثلاثين سنة وولد سروج.","11:21":"وعاش رعو بعد ما ولد سروج مئتين وسبع سنين وولد بنين وبنات.","11:22":"وعاش سروج ثلاثين سنة وولد ناحور.","11:23":"وعاش سروج بعد ما ولد ناحور مئتي سنة وولد بنين وبنات.","11:24":"وعاش ناحور تسعا وعشرين سنة وولد تارح.","11:25":"وعاش ناحور بعد ما ولد تارح مئة وتسع عشرة سنة وولد بنين وبنات.","11:26":"وعاش تارح سبعين سنة وولد ابرام وناحور وهاران.","11:27":"وهذه مواليد تارح: ولد تارح ابرام وناحور وهاران. وولد هاران لوطا.","11:28":"ومات هاران قبل تارح ابيه في ارض ميلاده في اور الكلدانيين.","11:29":"واتخذ ابرام وناحور لهما امراتين: اسم امراة ابرام ساراي واسم امراة ناحور ملكة بنت هاران ابي ملكة وابي يسكة.","11:30":"وكانت ساراي عاقرا ليس لها ولد.","11:31":"واخذ تارح ابرام ابنه ولوطا بن هاران ابن ابنه وساراي كنته امراة ابرام ابنه فخرجوا معا من اور الكلدانيين ليذهبوا الى ارض كنعان. فاتوا الى حاران واقاموا هناك.","11:32":"وكانت ايام تارح مئتين وخمس سنين. ومات تارح في حاران.","12:1":"وقال الرب لابرام: «اذهب من ارضك ومن عشيرتك ومن بيت ابيك الى الارض التي اريك.","12:2":"فاجعلك امة عظيمة واباركك واعظم اسمك وتكون بركة.","12:3":"وابارك مباركيك ولاعنك العنه. وتتبارك فيك جميع قبائل الارض».","12:4":"فذهب ابرام كما قال له الرب وذهب معه لوط. وكان ابرام ابن خمس وسبعين سنة لما خرج من حاران.","12:5":"فاخذ ابرام ساراي امراته ولوطا ابن اخيه وكل مقتنياتهما التي اقتنيا والنفوس التي امتلكا في حاران. وخرجوا ليذهبوا الى ارض كنعان. فاتوا الى ارض كنعان.","12:6":"واجتاز ابرام في الارض الى مكان شكيم الى بلوطة مورة. وكان الكنعانيون حينئذ في الارض.","12:7":"وظهر الرب لابرام وقال: «لنسلك اعطي هذه الارض». فبنى هناك مذبحا للرب الذي ظهر له.","12:8":"ثم نقل من هناك الى الجبل شرقي بيت ايل ونصب خيمته. وله بيت ايل من المغرب وعاي من المشرق. فبنى هناك مذبحا للرب ودعا باسم الرب.","12:9":"ثم ارتحل ابرام ارتحالا متواليا نحو الجنوب.","12:10":"وحدث جوع في الارض فانحدر ابرام الى مصر ليتغرب هناك لان الجوع في الارض كان شديدا.","12:11":"وحدث لما قرب ان يدخل مصر انه قال لساراي امراته: «اني قد علمت انك امراة حسنة المنظر.","12:12":"فيكون اذا راك المصريون انهم يقولون: هذه امراته. فيقتلونني ويستبقونك.","12:13":"قولي انك اختي ليكون لي خير بسببك وتحيا نفسي من اجلك».","12:14":"فحدث لما دخل ابرام الى مصر ان المصريين راوا المراة انها حسنة جدا.","12:15":"وراها رؤساء فرعون ومدحوها لدى فرعون فاخذت المراة الى بيت فرعون","12:16":"فصنع الى ابرام خيرا بسببها وصار له غنم وبقر وحمير وعبيد واماء واتن وجمال.","12:17":"فضرب الرب فرعون وبيته ضربات عظيمة بسبب ساراي امراة ابرام.","12:18":"فدعا فرعون ابرام وقال: «ما هذا الذي صنعت بي؟ لماذا لم تخبرني انها امراتك؟","12:19":"لماذا قلت هي اختي حتى اخذتها لي لتكون زوجتي؟ والان هوذا امراتك! خذها واذهب!».","12:20":"فاوصى عليه فرعون رجالا فشيعوه وامراته وكل ما كان له.","13:1":"فصعد ابرام من مصر هو وامراته وكل ما كان له ولوط معه الى الجنوب.","13:2":"وكان ابرام غنيا جدا في المواشي والفضة والذهب.","13:3":"وسار في رحلاته من الجنوب الى بيت ايل الى المكان الذي كانت خيمته فيه في البداءة بين بيت ايل وعاي","13:4":"الى مكان المذبح الذي عمله هناك اولا. ودعا هناك ابرام باسم الرب.","13:5":"ولوط السائر مع ابرام كان له ايضا غنم وبقر وخيام.","13:6":"ولم تحتملهما الارض ان يسكنا معا اذ كانت املاكهما كثيرة فلم يقدرا ان يسكنا معا.","13:7":"فحدثت مخاصمة بين رعاة مواشي ابرام ورعاة مواشي لوط. وكان الكنعانيون والفرزيون حينئذ ساكنين في الارض.","13:8":"فقال ابرام للوط: «لا تكن مخاصمة بيني وبينك وبين رعاتي ورعاتك لاننا نحن اخوان.","13:9":"اليست كل الارض امامك؟ اعتزل عني. ان ذهبت شمالا فانا يمينا وان يمينا فانا شمالا».","13:10":"فرفع لوط عينيه وراى كل دائرة الاردن ان جميعها سقي قبلما اخرب الرب سدوم وعمورة كجنة الرب كارض مصر. حينما تجيء الى صوغر.","13:11":"فاختار لوط لنفسه كل دائرة الاردن وارتحل لوط شرقا. فاعتزل الواحد عن الاخر.","13:12":"ابرام سكن في ارض كنعان ولوط سكن في مدن الدائرة ونقل خيامه الى سدوم.","13:13":"وكان اهل سدوم اشرارا وخطاة لدى الرب جدا.","13:14":"وقال الرب لابرام بعد اعتزال لوط عنه: «ارفع عينيك وانظر من الموضع الذي انت فيه شمالا وجنوبا وشرقا وغربا","13:15":"لان جميع الارض التي انت ترى لك اعطيها ولنسلك الى الابد.","13:16":"واجعل نسلك كتراب الارض حتى اذا استطاع احد ان يعد تراب الارض فنسلك ايضا يعد.","13:17":"قم امش في الارض طولها وعرضها لاني لك اعطيها».","13:18":"فنقل ابرام خيامه واتى واقام عند بلوطات ممرا التي في حبرون وبنى هناك مذبحا للرب.","14:1":"وحدث في ايام امرافل ملك شنعار واريوك ملك الاسار وكدرلعومر ملك عيلام وتدعال ملك جوييم","14:2":"ان هؤلاء صنعوا حربا مع بارع ملك سدوم وبرشاع ملك عمورة وشناب ملك ادمة وشمئيبر ملك صبوييم وملك بالع (التي هي صوغر).","14:3":"جميع هؤلاء اجتمعوا متعاهدين الى عمق السديم (الذي هو بحر الملح).","14:4":"اثنتي عشرة سنة استعبدوا لكدرلعومر والسنة الثالثة عشرة عصوا عليه.","14:5":"وفي السنة الرابعة عشرة اتى كدرلعومر والملوك الذين معه وضربوا الرفائيين في عشتاروث قرنايم والزوزيين في هام والايميين في شوى قريتايم","14:6":"والحوريين في جبلهم سعير الى بطمة فاران التي عند البرية.","14:7":"ثم رجعوا وجاءوا الى عين مشفاط (التي هي قادش). وضربوا كل بلاد العمالقة وايضا الاموريين الساكنين في حصون تامار.","14:8":"فخرج ملك سدوم وملك عمورة وملك ادمة وملك صبوييم وملك بالع (التي هي صوغر) ونظموا حربا معهم في عمق السديم.","14:9":"مع كدرلعومر ملك عيلام وتدعال ملك جوييم وامرافل ملك شنعار واريوك ملك الاسار. اربعة ملوك على خمسة.","14:10":"وعمق السديم كان فيه ابار حمر كثيرة. فهرب ملكا سدوم وعمورة وسقطا هناك والباقون هربوا الى الجبل.","14:11":"فاخذوا جميع املاك سدوم وعمورة وجميع اطعمتهم ومضوا.","14:12":"واخذوا لوطا ابن اخي ابرام واملاكه ومضوا اذ كان ساكنا في سدوم.","14:13":"فاتى من نجا واخبر ابرام العبراني. وكان ساكنا عند بلوطات ممرا الاموري اخي اشكول واخي عانر. وكانوا اصحاب عهد مع ابرام.","14:14":"فلما سمع ابرام ان اخاه سبي جر غلمانه المتمرنين ولدان بيته ثلاث مئة وثمانية عشر وتبعهم الى دان.","14:15":"وانقسم عليهم ليلا هو وعبيده فكسرهم وتبعهم الى حوبة التي عن شمال دمشق.","14:16":"واسترجع كل الاملاك واسترجع لوطا اخاه ايضا واملاكه والنساء ايضا والشعب.","14:17":"فخرج ملك سدوم لاستقباله بعد رجوعه من كسرة كدرلعومر والملوك الذين معه الى عمق شوى (الذي هو عمق الملك).","14:18":"وملكي صادق ملك شاليم اخرج خبزا وخمرا. وكان كاهنا لله العلي.","14:19":"وباركه وقال: «مبارك ابرام من الله العلي مالك السماوات والارض","14:20":"ومبارك الله العلي الذي اسلم اعداءك في يدك». فاعطاه عشرا من كل شيء.","14:21":"وقال ملك سدوم لابرام: «اعطني النفوس واما الاملاك فخذها لنفسك».","14:22":"فقال ابرام لملك سدوم: «رفعت يدي الى الرب الاله العلي مالك السماء والارض","14:23":"لا اخذن لا خيطا ولا شراك نعل ولا من كل ما هو لك فلا تقول: انا اغنيت ابرام.","14:24":"ليس لي غير الذي اكله الغلمان. واما نصيب الرجال الذين ذهبوا معي: عانر واشكول وممرا فهم ياخذون نصيبهم».","15:1":"بعد هذه الامور صار كلام الرب الى ابرام في الرؤيا: «لا تخف يا ابرام. انا ترس لك. اجرك كثير جدا».","15:2":"فقال ابرام: «ايها السيد الرب ماذا تعطيني وانا ماض عقيما ومالك بيتي هو اليعازر الدمشقي؟»","15:3":"وقال ابرام ايضا: «انك لم تعطني نسلا وهوذا ابن بيتي وارث لي».","15:4":"فاذا كلام الرب اليه: «لا يرثك هذا. بل الذي يخرج من احشائك هو يرثك».","15:5":"ثم اخرجه الى خارج وقال: «انظر الى السماء وعد النجوم ان استطعت ان تعدها». وقال له: «هكذا يكون نسلك».","15:6":"فامن بالرب فحسبه له برا.","15:7":"وقال له: «انا الرب الذي اخرجك من اور الكلدانيين ليعطيك هذه الارض لترثها».","15:8":"فقال: «ايها السيد الرب بماذا اعلم اني ارثها؟»","15:9":"فقال له: «خذ لي عجلة ثلاثية وعنزة ثلاثية وكبشا ثلاثيا ويمامة وحمامة».","15:10":"فاخذ هذه كلها وشقها من الوسط وجعل شق كل واحد مقابل صاحبه. واما الطير فلم يشقه.","15:11":"فنزلت الجوارح على الجثث وكان ابرام يزجرها.","15:12":"ولما صارت الشمس الى المغيب وقع على ابرام سبات واذا رعبة مظلمة عظيمة واقعة عليه.","15:13":"فقال لابرام: «اعلم يقينا ان نسلك سيكون غريبا في ارض ليست لهم ويستعبدون لهم فيذلونهم اربع مئة سنة.","15:14":"ثم الامة التي يستعبدون لها انا ادينها. وبعد ذلك يخرجون باملاك جزيلة.","15:15":"واما انت فتمضي الى ابائك بسلام وتدفن بشيبة صالحة.","15:16":"وفي الجيل الرابع يرجعون الى ههنا لان ذنب الاموريين ليس الى الان كاملا».","15:17":"ثم غابت الشمس فصارت العتمة واذا تنور دخان ومصباح نار يجوز بين تلك القطع.","15:18":"في ذلك اليوم قطع الرب مع ابرام ميثاقا قائلا: «لنسلك اعطي هذه الارض من نهر مصر الى النهر الكبير نهر الفرات.","15:19":"القينيين والقنزيين والقدمونيين","15:20":"والحثيين والفرزيين والرفائيين","15:21":"والاموريين والكنعانيين والجرجاشيين واليبوسيين».","16:1":"واما ساراي امراة ابرام فلم تلد له. وكانت لها جارية مصرية اسمها هاجر","16:2":"فقالت ساراي لابرام: «هوذا الرب قد امسكني عن الولادة. ادخل على جاريتي لعلي ارزق منها بنين». فسمع ابرام لقول ساراي.","16:3":"فاخذت ساراي امراة ابرام هاجر المصرية جاريتها من بعد عشر سنين لاقامة ابرام في ارض كنعان واعطتها لابرام رجلها زوجة له.","16:4":"فدخل على هاجر فحبلت. ولما رات انها حبلت صغرت مولاتها في عينيها.","16:5":"فقالت ساراي لابرام: «ظلمي عليك! انا دفعت جاريتي الى حضنك فلما رات انها حبلت صغرت في عينيها. يقضي الرب بيني وبينك».","16:6":"فقال ابرام لساراي: «هوذا جاريتك في يدك. افعلي بها ما يحسن في عينيك». فاذلتها ساراي فهربت من وجهها.","16:7":"فوجدها ملاك الرب على عين الماء في البرية على العين التي في طريق شور.","16:8":"وقال: «يا هاجر جارية ساراي من اين اتيت والى اين تذهبين؟». فقالت: «انا هاربة من وجه مولاتي ساراي».","16:9":"فقال لها ملاك الرب: «ارجعي الى مولاتك واخضعي تحت يديها».","16:10":"وقال لها ملاك الرب: «تكثيرا اكثر نسلك فلا يعد من الكثرة».","16:11":"وقال لها ملاك الرب: «ها انت حبلى فتلدين ابنا وتدعين اسمه اسماعيل لان الرب قد سمع لمذلتك.","16:12":"وانه يكون انسانا وحشيا يده على كل واحد ويد كل واحد عليه وامام جميع اخوته يسكن».","16:13":"فدعت اسم الرب الذي تكلم معها: «انت ايل رئي». لانها قالت: «اههنا ايضا رايت بعد رؤية؟»","16:14":"لذلك دعيت البئر «بئر لحي رئي». ها هي بين قادش وبارد.","16:15":"فولدت هاجر لابرام ابنا. ودعا ابرام اسم ابنه الذي ولدته هاجر «اسماعيل».","16:16":"كان ابرام ابن ست وثمانين سنة لما ولدت هاجر اسماعيل لابرام.","17:1":"ولما كان ابرام ابن تسع وتسعين سنة ظهر الرب لابرام وقال له: «انا الله القدير. سر امامي وكن كاملا","17:2":"فاجعل عهدي بيني وبينك واكثرك كثيرا جدا».","17:3":"فسقط ابرام على وجهه. وقال الله له:","17:4":"«اما انا فهوذا عهدي معك وتكون ابا لجمهور من الامم","17:5":"فلا يدعى اسمك بعد ابرام بل يكون اسمك ابراهيم لاني اجعلك ابا لجمهور من الامم.","17:6":"واثمرك كثيرا جدا واجعلك امما وملوك منك يخرجون.","17:7":"واقيم عهدي بيني وبينك وبين نسلك من بعدك في اجيالهم عهدا ابديا لاكون الها لك ولنسلك من بعدك.","17:8":"واعطي لك ولنسلك من بعدك ارض غربتك كل ارض كنعان ملكا ابديا. واكون الههم».","17:9":"وقال الله لابراهيم: «واما انت فتحفظ عهدي انت ونسلك من بعدك في اجيالهم.","17:10":"هذا هو عهدي الذي تحفظونه بيني وبينكم وبين نسلك من بعدك: يختن منكم كل ذكر","17:11":"فتختنون في لحم غرلتكم فيكون علامة عهد بيني وبينكم.","17:12":"ابن ثمانية ايام يختن منكم كل ذكر في اجيالكم: وليد البيت والمبتاع بفضة من كل ابن غريب ليس من نسلك.","17:13":"يختن ختانا وليد بيتك والمبتاع بفضتك فيكون عهدي في لحمكم عهدا ابديا.","17:14":"واما الذكر الاغلف الذي لا يختن في لحم غرلته فتقطع تلك النفس من شعبها. انه قد نكث عهدي».","17:15":"وقال الله لابراهيم: «ساراي امراتك لا تدعو اسمها ساراي بل اسمها سارة.","17:16":"واباركها واعطيك ايضا منها ابنا. اباركها فتكون امما وملوك شعوب منها يكونون».","17:17":"فسقط ابراهيم على وجهه وضحك وقال في قلبه: «هل يولد لابن مئة سنة؟ وهل تلد سارة وهي بنت تسعين سنة؟».","17:18":"وقال ابراهيم لله: «ليت اسماعيل يعيش امامك!»","17:19":"فقال الله بل سارة امراتك تلد لك ابنا وتدعو اسمه اسحاق. واقيم عهدي معه عهدا ابديا لنسله من بعده.","17:20":"واما اسماعيل فقد سمعت لك فيه. ها انا اباركه واثمره واكثره كثيرا جدا. اثني عشر رئيسا يلد واجعله امة كبيرة.","17:21":"ولكن عهدي اقيمه مع اسحاق الذي تلده لك سارة في هذا الوقت في السنة الاتية».","17:22":"فلما فرغ من الكلام معه صعد الله عن ابراهيم.","17:23":"فاخذ ابراهيم اسماعيل ابنه وجميع ولدان بيته وجميع المبتاعين بفضته كل ذكر من اهل بيت ابراهيم وختن لحم غرلتهم في ذلك اليوم عينه كما كلمه الله.","17:24":"وكان ابراهيم ابن تسع وتسعين سنة حين ختن في لحم غرلته","17:25":"وكان اسماعيل ابنه ابن ثلاث عشرة سنة حين ختن في لحم غرلته.","17:26":"في ذلك اليوم عينه ختن ابراهيم واسماعيل ابنه.","17:27":"وكل رجال بيته ولدان البيت والمبتاعين بالفضة من ابن الغريب ختنوا معه.","18:1":"وظهر له الرب عند بلوطات ممرا وهو جالس في باب الخيمة وقت حر النهار","18:2":"فرفع عينيه ونظر واذا ثلاثة رجال واقفون لديه. فلما نظر ركض لاستقبالهم من باب الخيمة وسجد الى الارض","18:3":"وقال: «يا سيد ان كنت قد وجدت نعمة في عينيك فلا تتجاوز عبدك.","18:4":"ليؤخذ قليل ماء واغسلوا ارجلكم واتكئوا تحت الشجرة","18:5":"فاخذ كسرة خبز فتسندون قلوبكم ثم تجتازون لانكم قد مررتم على عبدكم». فقالوا: «هكذا تفعل كما تكلمت».","18:6":"فاسرع ابراهيم الى الخيمة الى سارة وقال: «اسرعي بثلاث كيلات دقيقا سميذا. اعجني واصنعي خبز ملة».","18:7":"ثم ركض ابراهيم الى البقر واخذ عجلا رخصا وجيدا واعطاه للغلام فاسرع ليعمله.","18:8":"ثم اخذ زبدا ولبنا والعجل الذي عمله ووضعها قدامهم. واذ كان هو واقفا لديهم تحت الشجرة اكلوا.","18:9":"وقالوا له: «اين سارة امراتك؟» فقال: «ها هي في الخيمة».","18:10":"فقال: «اني ارجع اليك نحو زمان الحياة ويكون لسارة امراتك ابن». وكانت سارة سامعة في باب الخيمة وهو وراءه -","18:11":"وكان ابراهيم وسارة شيخين متقدمين في الايام وقد انقطع ان يكون لسارة عادة كالنساء.","18:12":"فضحكت سارة في باطنها قائلة: «ابعد فنائي يكون لي تنعم وسيدي قد شاخ!»","18:13":"فقال الرب لابراهيم: «لماذا ضحكت سارة قائلة: افبالحقيقة الد وانا قد شخت؟","18:14":"هل يستحيل على الرب شيء؟ في الميعاد ارجع اليك نحو زمان الحياة ويكون لسارة ابن».","18:15":"فانكرت سارة قائلة: «لم اضحك». (لانها خافت). فقال: «لا! بل ضحكت».","18:16":"ثم قام الرجال من هناك وتطلعوا نحو سدوم. وكان ابراهيم ماشيا معهم ليشيعهم.","18:17":"فقال الرب: «هل اخفي عن ابراهيم ما انا فاعله","18:18":"وابراهيم يكون امة كبيرة وقوية ويتبارك به جميع امم الارض؟","18:19":"لاني عرفته لكي يوصي بنيه وبيته من بعده ان يحفظوا طريق الرب ليعملوا برا وعدلا لكي ياتي الرب لابراهيم بما تكلم به».","18:20":"وقال الرب: «ان صراخ سدوم وعمورة قد كثر وخطيتهم قد عظمت جدا.","18:21":"انزل وارى هل فعلوا بالتمام حسب صراخها الاتي الي والا فاعلم».","18:22":"وانصرف الرجال من هناك وذهبوا نحو سدوم واما ابراهيم فكان لم يزل قائما امام الرب.","18:23":"فتقدم ابراهيم وقال: «افتهلك البار مع الاثيم؟","18:24":"عسى ان يكون خمسون بارا في المدينة. افتهلك المكان ولا تصفح عنه من اجل الخمسين بارا الذين فيه؟","18:25":"حاشا لك ان تفعل مثل هذا الامر ان تميت البار مع الاثيم فيكون البار كالاثيم. حاشا لك! اديان كل الارض لا يصنع عدلا؟»","18:26":"فقال الرب: «ان وجدت في سدوم خمسين بارا في المدينة فاني اصفح عن المكان كله من اجلهم».","18:27":"فقال ابراهيم: «اني قد شرعت اكلم المولى وانا تراب ورماد.","18:28":"ربما نقص الخمسون بارا خمسة. اتهلك كل المدينة بالخمسة؟» فقال: «لا اهلك ان وجدت هناك خمسة واربعين».","18:29":"فعاد يكلمه ايضا وقال: « عسى ان يوجد هناك اربعون». فقال: «لا افعل من اجل الاربعين».","18:30":"فقال: «لا يسخط المولى فاتكلم. عسى ان يوجد هناك ثلاثون». فقال: «لا افعل ان وجدت هناك ثلاثين».","18:31":"فقال: «اني قد شرعت اكلم المولى. عسى ان يوجد هناك عشرون». فقال: «لا اهلك من اجل العشرين».","18:32":"فقال: «لا يسخط المولى فاتكلم هذه المرة فقط. عسى ان يوجد هناك عشرة». فقال: «لا اهلك من اجل العشرة».","18:33":"وذهب الرب عندما فرغ من الكلام مع ابراهيم ورجع ابراهيم الى مكانه.","19:1":"فجاء الملاكان الى سدوم مساء وكان لوط جالسا في باب سدوم. فلما راهما لوط قام لاستقبالهما وسجد بوجهه الى الارض.","19:2":"وقال: «يا سيدي ميلا الى بيت عبدكما وبيتا واغسلا ارجلكما ثم تبكران وتذهبان في طريقكما». فقالا: «لا بل في الساحة نبيت».","19:3":"فالح عليهما جدا فمالا اليه ودخلا بيته فصنع لهما ضيافة وخبز فطيرا فاكلا.","19:4":"وقبلما اضطجعا احاط بالبيت رجال المدينة رجال سدوم من الحدث الى الشيخ كل الشعب من اقصاها.","19:5":"فنادوا لوطا وقالوا له: «اين الرجلان اللذان دخلا اليك الليلة؟ اخرجهما الينا لنعرفهما».","19:6":"فخرج اليهم لوط الى الباب واغلق الباب وراءه","19:7":"وقال: «لا تفعلوا شرا يا اخوتي.","19:8":"هوذا لي ابنتان لم تعرفا رجلا. اخرجهما اليكم فافعلوا بهما كما يحسن في عيونكم. واما هذان الرجلان فلا تفعلوا بهما شيئا لانهما قد دخلا تحت ظل سقفي».","19:9":"فقالوا: «ابعد الى هناك». ثم قالوا: «جاء هذا الانسان ليتغرب وهو يحكم حكما. الان نفعل بك شرا اكثر منهما». فالحوا على لوط جدا وتقدموا ليكسروا الباب","19:10":"فمد الرجلان ايديهما وادخلا لوطا اليهما الى البيت واغلقا الباب.","19:11":"واما الرجال الذين على باب البيت فضرباهم بالعمى من الصغير الى الكبير فعجزوا عن ان يجدوا الباب.","19:12":"وقال الرجلان للوط: «من لك ايضا ههنا؟ اصهارك وبنيك وبناتك وكل من لك في المدينة اخرج من المكان","19:13":"لاننا مهلكان هذا المكان اذ قد عظم صراخهم امام الرب فارسلنا الرب لنهلكه».","19:14":"فخرج لوط وكلم اصهاره الاخذين بناته وقال: «قوموا اخرجوا من هذا المكان لان الرب مهلك المدينة». فكان كمازح في اعين اصهاره.","19:15":"ولما طلع الفجر كان الملاكان يعجلان لوطا قائلين: «قم خذ امراتك وابنتيك الموجودتين لئلا تهلك باثم المدينة».","19:16":"ولما توانى امسك الرجلان بيده وبيد امراته وبيد ابنتيه - لشفقة الرب عليه - واخرجاه ووضعاه خارج المدينة.","19:17":"وكان لما اخرجاهم الى خارج انه قال: «اهرب لحياتك. لا تنظر الى ورائك ولا تقف في كل الدائرة. اهرب الى الجبل لئلا تهلك».","19:18":"فقال لهما لوط: «لا يا سيد.","19:19":"هوذا عبدك قد وجد نعمة في عينيك وعظمت لطفك الذي صنعت الي باستبقاء نفسي وانا لا اقدر ان اهرب الى الجبل لعل الشر يدركني فاموت.","19:20":"هوذا المدينة هذه قريبة للهرب اليها وهي صغيرة. اهرب الى هناك. (اليست هي صغيرة؟) فتحيا نفسي».","19:21":"فقال له: «اني قد رفعت وجهك في هذا الامر ايضا ان لا اقلب المدينة التي تكلمت عنها.","19:22":"اسرع اهرب الى هناك لاني لا استطيع ان افعل شيئا حتى تجيء الى هناك». لذلك دعي اسم المدينة «صوغر».","19:23":"واذ اشرقت الشمس على الارض دخل لوط الى صوغر","19:24":"فامطر الرب على سدوم وعمورة كبريتا ونارا من عند الرب من السماء.","19:25":"وقلب تلك المدن وكل الدائرة وجميع سكان المدن ونبات الارض.","19:26":"ونظرت امراته من ورائه فصارت عمود ملح!","19:27":"وبكر ابراهيم في الغد الى المكان الذي وقف فيه امام الرب","19:28":"وتطلع نحو سدوم وعمورة ونحو كل ارض الدائرة ونظر واذا دخان الارض يصعد كدخان الاتون.","19:29":"وحدث لما اخرب الله مدن الدائرة ان الله ذكر ابراهيم وارسل لوطا من وسط الانقلاب. حين قلب المدن التي سكن فيها لوط.","19:30":"وصعد لوط من صوغر وسكن في الجبل وابنتاه معه لانه خاف ان يسكن في صوغر. فسكن في المغارة هو وابنتاه.","19:31":"وقالت البكر للصغيرة: «ابونا قد شاخ وليس في الارض رجل ليدخل علينا كعادة كل الارض.","19:32":"هلم نسقي ابانا خمرا ونضطجع معه فنحيي من ابينا نسلا».","19:33":"فسقتا اباهما خمرا في تلك الليلة ودخلت البكر واضطجعت مع ابيها ولم يعلم باضطجاعها ولا بقيامها.","19:34":"وحدث في الغد ان البكر قالت للصغيرة: «اني قد اضطجعت البارحة مع ابي. نسقيه خمرا الليلة ايضا فادخلي اضطجعي معه فنحيي من ابينا نسلا».","19:35":"فسقتا اباهما خمرا في تلك الليلة ايضا وقامت الصغيرة واضطجعت معه ولم يعلم باضطجاعها ولا بقيامها","19:36":"فحبلت ابنتا لوط من ابيهما.","19:37":"فولدت البكر ابنا ودعت اسمه «مواب» - وهو ابو الموابيين الى اليوم.","19:38":"والصغيرة ايضا ولدت ابنا ودعت اسمه «بن عمي» - وهو ابو بني عمون الى اليوم.","20:1":"وانتقل ابراهيم من هناك الى ارض الجنوب وسكن بين قادش وشور وتغرب في جرار.","20:2":"وقال ابراهيم عن سارة امراته: «هي اختي». فارسل ابيمالك ملك جرار واخذ سارة.","20:3":"فجاء الله الى ابيمالك في حلم الليل وقال له: «ها انت ميت من اجل المراة التي اخذتها فانها متزوجة ببعل».","20:4":"ولكن لم يكن ابيمالك قد اقترب اليها. فقال: «يا سيد اامة بارة تقتل؟","20:5":"الم يقل هو لي انها اختي وهي ايضا نفسها قالت هو اخي؟ بسلامة قلبي ونقاوة يدي فعلت هذا».","20:6":"فقال له الله في الحلم: «انا ايضا علمت انك بسلامة قلبك فعلت هذا. وانا ايضا امسكتك عن ان تخطئ الي لذلك لم ادعك تمسها.","20:7":"فالان رد امراة الرجل فانه نبي فيصلي لاجلك فتحيا. وان كنت لست تردها فاعلم انك موتا تموت انت وكل من لك».","20:8":"فبكر ابيمالك في الغد ودعا جميع عبيده وتكلم بكل هذا الكلام في مسامعهم. فخاف الرجال جدا.","20:9":"ثم دعا ابيمالك ابراهيم وقال له: «ماذا فعلت بنا وبماذا اخطات اليك حتى جلبت علي وعلى مملكتي خطية عظيمة؟ اعمالا لا تعمل عملت بي!».","20:10":"وقال ابيمالك لابراهيم: «ماذا رايت حتى عملت هذا الشيء؟»","20:11":"فقال ابراهيم: «اني قلت: ليس في هذا الموضع خوف الله البتة فيقتلونني لاجل امراتي.","20:12":"وبالحقيقة ايضا هي اختي ابنة ابي غير انها ليست ابنة امي فصارت لي زوجة.","20:13":"وحدث لما اتاهني الله من بيت ابي اني قلت لها: هذا معروفك الذي تصنعين الي: في كل مكان ناتي اليه قولي عني هو اخي».","20:14":"فاخذ ابيمالك غنما وبقرا وعبيدا واماء واعطاها لابراهيم ورد اليه سارة امراته.","20:15":"وقال ابيمالك: «هوذا ارضي قدامك. اسكن في ما حسن في عينيك».","20:16":"وقال لسارة: «اني قد اعطيت اخاك الفا من الفضة. ها هو لك غطاء عين من جهة كل ما عندك وعند كل واحد فانصفت».","20:17":"فصلى ابراهيم الى الله فشفى الله ابيمالك وامراته وجواريه فولدن -","20:18":"لان الرب كان قد اغلق كل رحم لبيت ابيمالك بسبب سارة امراة ابراهيم.","21:1":"وافتقد الرب سارة كما قال وفعل الرب لسارة كما تكلم.","21:2":"فحبلت سارة وولدت لابراهيم ابنا في شيخوخته في الوقت الذي تكلم الله عنه.","21:3":"ودعا ابراهيم اسم ابنه المولود له الذي ولدته له سارة «اسحاق».","21:4":"وختن ابراهيم اسحاق ابنه وهو ابن ثمانية ايام كما امره الله.","21:5":"وكان ابراهيم ابن مئة سنة حين ولد له اسحاق ابنه.","21:6":"وقالت سارة: «قد صنع الي الله ضحكا. كل من يسمع يضحك لي».","21:7":"وقالت: «من قال لابراهيم: سارة ترضع بنين حتى ولدت ابنا في شيخوخته!»","21:8":"فكبر الولد وفطم. وصنع ابراهيم وليمة عظيمة يوم فطام اسحاق.","21:9":"ورات سارة ابن هاجر المصرية الذي ولدته لابراهيم يمزح","21:10":"فقالت لابراهيم: «اطرد هذه الجارية وابنها لان ابن هذه الجارية لا يرث مع ابني اسحاق».","21:11":"فقبح الكلام جدا في عيني ابراهيم لسبب ابنه.","21:12":"فقال الله لابراهيم: «لا يقبح في عينيك من اجل الغلام ومن اجل جاريتك. في كل ما تقول لك سارة اسمع لقولها لانه باسحاق يدعى لك نسل.","21:13":"وابن الجارية ايضا ساجعله امة لانه نسلك».","21:14":"فبكر ابراهيم صباحا واخذ خبزا وقربة ماء واعطاهما لهاجر واضعا اياهما على كتفها والولد وصرفها. فمضت وتاهت في برية بئر سبع.","21:15":"ولما فرغ الماء من القربة طرحت الولد تحت احدى الاشجار","21:16":"ومضت وجلست مقابله بعيدا نحو رمية قوس لانها قالت: «لا انظر موت الولد». فجلست مقابله ورفعت صوتها وبكت.","21:17":"فسمع الله صوت الغلام. ونادى ملاك الله هاجر من السماء وقال لها: «ما لك يا هاجر؟ لا تخافي لان الله قد سمع لصوت الغلام حيث هو.","21:18":"قومي احملي الغلام وشدي يدك به لاني ساجعله امة عظيمة».","21:19":"وفتح الله عينيها فابصرت بئر ماء فذهبت وملات القربة ماء وسقت الغلام.","21:20":"وكان الله مع الغلام فكبر وسكن في البرية وكان ينمو رامي قوس.","21:21":"وسكن في برية فاران. واخذت له امه زوجة من ارض مصر.","21:22":"وحدث في ذلك الزمان ان ابيمالك وفيكول رئيس جيشه قالا لابراهيم: «الله معك في كل ما انت صانع.","21:23":"فالان احلف لي بالله ههنا انك لا تغدر بي ولا بنسلي وذريتي. كالمعروف الذي صنعت اليك تصنع الي والى الارض التي تغربت فيها».","21:24":"فقال ابراهيم: «انا احلف».","21:25":"وعاتب ابراهيم ابيمالك لسبب بئر الماء التي اغتصبها عبيد ابيمالك.","21:26":"فقال ابيمالك: «لم اعلم من فعل هذا الامر. انت لم تخبرني ولا انا سمعت سوى اليوم».","21:27":"فاخذ ابراهيم غنما وبقرا واعطى ابيمالك فقطعا كلاهما ميثاقا.","21:28":"واقام ابراهيم سبع نعاج من الغنم وحدها.","21:29":"فقال ابيمالك لابراهيم: «ما هي هذه السبع النعاج التي اقمتها وحدها؟»","21:30":"فقال: «انك سبع نعاج تاخذ من يدي لكي تكون لي شهادة باني حفرت هذه البئر».","21:31":"لذلك دعا ذلك الموضع بئر سبع. لانهما هناك حلفا كلاهما.","21:32":"فقطعا ميثاقا في بئر سبع. ثم قام ابيمالك وفيكول رئيس جيشه ورجعا الى ارض الفلسطينيين.","21:33":"وغرس ابراهيم اثلا في بئر سبع ودعا هناك باسم الرب «الاله السرمدي».","21:34":"وتغرب ابراهيم في ارض الفلسطينيين اياما كثيرة.","22:1":"وحدث بعد هذه الامور ان الله امتحن ابراهيم فقال له: «يا ابراهيم». فقال: «هئنذا».","22:2":"فقال: «خذ ابنك وحيدك الذي تحبه اسحاق واذهب الى ارض المريا واصعده هناك محرقة على احد الجبال الذي اقول لك».","22:3":"فبكر ابراهيم صباحا وشد على حماره واخذ اثنين من غلمانه معه واسحاق ابنه وشقق حطبا لمحرقة وقام وذهب الى الموضع الذي قال له الله.","22:4":"وفي اليوم الثالث رفع ابراهيم عينيه وابصر الموضع من بعيد","22:5":"فقال ابراهيم لغلاميه: «اجلسا انتما ههنا مع الحمار واما انا والغلام فنذهب الى هناك ونسجد ثم نرجع اليكما».","22:6":"فاخذ ابراهيم حطب المحرقة ووضعه على اسحاق ابنه واخذ بيده النار والسكين. فذهبا كلاهما معا.","22:7":"وقال اسحاق لابراهيم ابيه: «يا ابي». فقال: «هئنذا يا ابني». فقال: «هوذا النار والحطب ولكن اين الخروف للمحرقة؟»","22:8":"فقال ابراهيم: «الله يرى له الخروف للمحرقة يا ابني». فذهبا كلاهما معا.","22:9":"فلما اتيا الى الموضع الذي قال له الله بنى هناك ابراهيم المذبح ورتب الحطب وربط اسحاق ابنه ووضعه على المذبح فوق الحطب.","22:10":"ثم مد ابراهيم يده واخذ السكين ليذبح ابنه.","22:11":"فناداه ملاك الرب من السماء وقال: «ابراهيم ابراهيم». فقال: «هئنذا»","22:12":"فقال: «لا تمد يدك الى الغلام ولا تفعل به شيئا لاني الان علمت انك خائف الله فلم تمسك ابنك وحيدك عني».","22:13":"فرفع ابراهيم عينيه ونظر واذا كبش وراءه ممسكا في الغابة بقرنيه فذهب ابراهيم واخذ الكبش واصعده محرقة عوضا عن ابنه.","22:14":"فدعا ابراهيم اسم ذلك الموضع «يهوه يراه». حتى انه يقال اليوم: «في جبل الرب يرى».","22:15":"ونادى ملاك الرب ابراهيم ثانية من السماء","22:16":"وقال: «بذاتي اقسمت يقول الرب اني من اجل انك فعلت هذا الامر ولم تمسك ابنك وحيدك","22:17":"اباركك مباركة واكثر نسلك تكثيرا كنجوم السماء وكالرمل الذي على شاطئ البحر ويرث نسلك باب اعدائه","22:18":"ويتبارك في نسلك جميع امم الارض من اجل انك سمعت لقولي».","22:19":"ثم رجع ابراهيم الى غلاميه فقاموا وذهبوا معا الى بئر سبع. وسكن ابراهيم في بئر سبع.","22:20":"وحدث بعد هذه الامور انه قيل لابراهيم: «هوذا ملكة قد ولدت هي ايضا بنين لناحور اخيك:","22:21":"عوصا بكره وبوزا اخاه وقموئيل ابا ارام","22:22":"وكاسد وحزوا وفلداش ويدلاف وبتوئيل».","22:23":"وولد بتوئيل رفقة. هؤلاء الثمانية ولدتهم ملكة لناحور اخي ابراهيم.","22:24":"واما سريته واسمها رؤومة فولدت هي ايضا طابح وجاحم وتاحش ومعكة.","23:1":"وكانت حياة سارة مئة وسبعا وعشرين سنة سني حياة سارة.","23:2":"وماتت سارة في قرية اربع (التي هي حبرون) في ارض كنعان. فاتى ابراهيم ليندب سارة ويبكي عليها.","23:3":"وقام ابراهيم من امام ميته وقال لبني حث:","23:4":"«انا غريب ونزيل عندكم. اعطوني ملك قبر معكم لادفن ميتي من امامي».","23:5":"فاجاب بنو حث ابراهيم:","23:6":"«اسمعنا يا سيدي انت رئيس من الله بيننا. في افضل قبورنا ادفن ميتك. لا يمنع احد منا قبره عنك حتى لا تدفن ميتك».","23:7":"فقام ابراهيم وسجد لشعب الارض لبني حث","23:8":"وقال: «ان كان في نفوسكم ان ادفن ميتي من امامي فاسمعوني والتمسوا لي من عفرون بن صوحر","23:9":"ان يعطيني مغارة المكفيلة التي له التي في طرف حقله. بثمن كامل يعطيني اياها في وسطكم ملك قبر».","23:10":"وكان عفرون جالسا بين بني حث. فاجاب عفرون الحثي ابراهيم في مسامع بني حث لدى جميع الداخلين باب مدينته:","23:11":"«لا يا سيدي اسمعني. الحقل وهبتك اياه والمغارة التي فيه لك وهبتها. لدى عيون بني شعبي وهبتك اياها. ادفن ميتك».","23:12":"فسجد ابراهيم امام شعب الارض","23:13":"وقال لعفرون في مسامع شعب الارض: «بل ان كنت انت اياه فليتك تسمعني. اعطيك ثمن الحقل. خذ مني فادفن ميتي هناك».","23:14":"فاجاب عفرون ابراهيم:","23:15":"«يا سيدي اسمعني. ارض باربع مئة شاقل فضة ما هي بيني وبينك؟ فادفن ميتك».","23:16":"فسمع ابراهيم لعفرون ووزن ابراهيم لعفرون الفضة التي ذكرها في مسامع بني حث. اربع مئة شاقل فضة جائزة عند التجار.","23:17":"فوجب حقل عفرون الذي في المكفيلة التي امام ممرا الحقل والمغارة التي فيه وجميع الشجر الذي في الحقل الذي في جميع حدوده حواليه","23:18":"لابراهيم ملكا لدى عيون بني حث بين جميع الداخلين باب مدينته.","23:19":"وبعد ذلك دفن ابراهيم سارة امراته في مغارة حقل المكفيلة امام ممرا (التي هي حبرون) في ارض كنعان","23:20":"فوجب الحقل والمغارة التي فيه لابراهيم ملك قبر من عند بني حث.","24:1":"وشاخ ابراهيم وتقدم في الايام. وبارك الرب ابراهيم في كل شيء.","24:2":"وقال ابراهيم لعبده كبير بيته المستولي على كل ما كان له: «ضع يدك تحت فخذي","24:3":"فاستحلفك بالرب اله السماء واله الارض ان لا تاخذ زوجة لابني من بنات الكنعانيين الذين انا ساكن بينهم","24:4":"بل الى ارضي والى عشيرتي تذهب وتاخذ زوجة لابني اسحاق».","24:5":"فقال له العبد: «ربما لا تشاء المراة ان تتبعني الى هذه الارض. هل ارجع بابنك الى الارض التي خرجت منها؟»","24:6":"فقال له ابراهيم: «احترز من ان ترجع بابني الى هناك.","24:7":"الرب اله السماء الذي اخذني من بيت ابي ومن ارض ميلادي والذي كلمني والذي اقسم لي قائلا: لنسلك اعطي هذه الارض هو يرسل ملاكه امامك فتاخذ زوجة لابني من هناك.","24:8":"وان لم تشا المراة ان تتبعك تبرات من حلفي هذا. اما ابني فلا ترجع به الى هناك».","24:9":"فوضع العبد يده تحت فخذ ابراهيم مولاه وحلف له على هذا الامر.","24:10":"ثم اخذ العبد عشرة جمال من جمال مولاه ومضى وجميع خيرات مولاه في يده. فقام وذهب الى ارام النهرين الى مدينة ناحور.","24:11":"واناخ الجمال خارج المدينة عند بئر الماء وقت المساء وقت خروج المستقيات.","24:12":"وقال: «ايها الرب اله سيدي ابراهيم يسر لي اليوم واصنع لطفا الى سيدي ابراهيم.","24:13":"ها انا واقف على عين الماء وبنات اهل المدينة خارجات ليستقين ماء.","24:14":"فليكن ان الفتاة التي اقول لها: اميلي جرتك لاشرب فتقول: اشرب وانا اسقي جمالك ايضا هي التي عينتها لعبدك اسحاق. وبها اعلم انك صنعت لطفا الى سيدي».","24:15":"واذ كان لم يفرغ بعد من الكلام اذا رفقة التي ولدت لبتوئيل ابن ملكة امراة ناحور اخي ابراهيم خارجة وجرتها على كتفها.","24:16":"وكانت الفتاة حسنة المنظر جدا وعذراء لم يعرفها رجل. فنزلت الى العين وملات جرتها وطلعت.","24:17":"فركض العبد للقائها وقال: «اسقيني قليل ماء من جرتك».","24:18":"فقالت: «اشرب يا سيدي». واسرعت وانزلت جرتها على يدها وسقته.","24:19":"ولما فرغت من سقيه قالت: «استقي لجمالك ايضا حتى تفرغ من الشرب».","24:20":"فاسرعت وافرغت جرتها في المسقاة وركضت ايضا الى البئر لتستقي. فاستقت لكل جماله.","24:21":"والرجل يتفرس فيها صامتا ليعلم: هل انجح الرب طريقه ام لا؟","24:22":"وحدث عندما فرغت الجمال من الشرب ان الرجل اخذ خزامة ذهب وزنها نصف شاقل وسوارين على يديها وزنهما عشرة شواقل ذهب.","24:23":"وقال: «بنت من انت؟ اخبريني. هل في بيت ابيك مكان لنا لنبيت؟»","24:24":"فقالت له: «انا بنت بتوئيل ابن ملكة الذي ولدته لناحور».","24:25":"وقالت له: «عندنا تبن وعلف كثير ومكان لتبيتوا ايضا».","24:26":"فخر الرجل وسجد للرب","24:27":"وقال: «مبارك الرب اله سيدي ابراهيم الذي لم يمنع لطفه وحقه عن سيدي. اذ كنت انا في الطريق هداني الرب الى بيت اخوة سيدي».","24:28":"فركضت الفتاة واخبرت بيت امها بحسب هذه الامور.","24:29":"وكان لرفقة اخ اسمه لابان. فركض لابان الى الرجل خارجا الى العين.","24:30":"وحدث انه اذ راى الخزامة والسوارين على يدي اخته واذ سمع كلام رفقة اخته قائلة: «هكذا كلمني الرجل» جاء الى الرجل واذا هو واقف عند الجمال على العين.","24:31":"فقال: «ادخل يا مبارك الرب. لماذا تقف خارجا وانا قد هيات البيت ومكانا للجمال؟»","24:32":"فدخل الرجل الى البيت وحل عن الجمال. فاعطى تبنا وعلفا للجمال وماء لغسل رجليه وارجل الرجال الذين معه.","24:33":"ووضع قدامه لياكل. فقال: «لا اكل حتى اتكلم كلامي». فقال: «تكلم».","24:34":"فقال: «انا عبد ابراهيم.","24:35":"والرب قد بارك مولاي جدا فصار عظيما واعطاه غنما وبقرا وفضة وذهبا وعبيدا واماء وجمالا وحميرا.","24:36":"وولدت سارة امراة سيدي ابنا لسيدي بعد ما شاخت فقد اعطاه كل ما له.","24:37":"واستحلفني سيدي قائلا:لا تاخذ زوجة لابني من بنات الكنعانيين الذين انا ساكن في ارضهم","24:38":"بل الى بيت ابي تذهب والى عشيرتي وتاخذ زوجة لابني.","24:39":"فقلت لسيدي: ربما لا تتبعني المراة.","24:40":"فقال لي: ان الرب الذي سرت امامه يرسل ملاكه معك وينجح طريقك فتاخذ زوجة لابني من عشيرتي ومن بيت ابي.","24:41":"حينئذ تتبرا من حلفي حينما تجيء الى عشيرتي. وان لم يعطوك فتكون بريئا من حلفي.","24:42":"فجئت اليوم الى العين وقلت: ايها الرب اله سيدي ابراهيم ان كنت تنجح طريقي الذي انا سالك فيه","24:43":"فها انا واقف على عين الماء وليكن ان الفتاة التي تخرج لتستقي واقول لها: اسقيني قليل ماء من جرتك","24:44":"فتقول لي: اشرب انت وانا استقي لجمالك ايضا هي المراة التي عينها الرب لابن سيدي.","24:45":"واذ كنت انا لم افرغ بعد من الكلام في قلبي اذا رفقة خارجة وجرتها على كتفها فنزلت الى العين واستقت. فقلت لها: اسقيني.","24:46":"فاسرعت وانزلت جرتها عنها وقالت: اشرب وانا اسقي جمالك ايضا. فشربت وسقت الجمال ايضا.","24:47":"فسالتها: بنت من انت؟ فقالت: بنت بتوئيل بن ناحور الذي ولدته له ملكة. فوضعت الخزامة في انفها والسوارين على يديها.","24:48":"وخررت وسجدت للرب وباركت الرب اله سيدي ابراهيم الذي هداني في طريق امين لاخذ ابنة اخي سيدي لابنه.","24:49":"والان ان كنتم تصنعون معروفا وامانة الى سيدي فاخبروني والا فاخبروني لانصرف يمينا او شمالا».","24:50":"فاجاب لابان وبتوئيل: «من عند الرب خرج الامر. لا نقدر ان نكلمك بشر او خير.","24:51":"هوذا رفقة قدامك. خذها واذهب. فلتكن زوجة لابن سيدك كما تكلم الرب».","24:52":"وكان عندما سمع عبد ابراهيم كلامهم انه سجد للرب الى الارض.","24:53":"واخرج العبد انية فضة وانية ذهب وثيابا واعطاها لرفقة واعطى تحفا لاخيها ولامها.","24:54":"فاكل وشرب هو والرجال الذين معه وباتوا. ثم قاموا صباحا فقال: «اصرفوني الى سيدي».","24:55":"فقال اخوها وامها: «لتمكث الفتاة عندنا اياما او عشرة بعد ذلك تمضي».","24:56":"فقال لهم: «لا تعوقوني والرب قد انجح طريقي. اصرفوني لاذهب الى سيدي».","24:57":"فقالوا: «ندعو الفتاة ونسالها شفاها».","24:58":"فدعوا رفقة وقالوا لها: «هل تذهبين مع هذا الرجل؟» فقالت: «اذهب».","24:59":"فصرفوا رفقة اختهم ومرضعتها وعبد ابراهيم ورجاله.","24:60":"وباركوا رفقة وقالوا لها: «انت اختنا. صيري الوف ربوات وليرث نسلك باب مبغضيه».","24:61":"فقامت رفقة وفتياتها وركبن على الجمال وتبعن الرجل. فاخذ العبد رفقة ومضى.","24:62":"وكان اسحاق قد اتى من ورود بئر لحي رئي - اذ كان ساكنا في ارض الجنوب.","24:63":"وخرج اسحاق ليتامل في الحقل عند اقبال المساء فرفع عينيه ونظر واذا جمال مقبلة.","24:64":"ورفعت رفقة عينيها فرات اسحاق فنزلت عن الجمل.","24:65":"وقالت للعبد: «من هذا الرجل الماشي في الحقل للقائنا؟» فقال العبد: «هو سيدي». فاخذت البرقع وتغطت.","24:66":"ثم حدث العبد اسحاق بكل الامور التي صنع","24:67":"فادخلها اسحاق الى خباء سارة امه واخذ رفقة فصارت له زوجة واحبها. فتعزى اسحاق بعد موت امه.","25:1":"وعاد ابراهيم فاخذ زوجة اسمها قطورة","25:2":"فولدت له زمران ويقشان ومدان ومديان ويشباق وشوحا.","25:3":"وولد يقشان: شبا وددان. وكان بنو ددان: اشوريم ولطوشيم ولاميم.","25:4":"وبنو مديان: عيفة وعفر وحنوك وابيداع والدعة. جميع هؤلاء بنو قطورة.","25:5":"واعطى ابراهيم اسحاق كل ما كان له.","25:6":"واما بنو السراري اللواتي كانت لابراهيم فاعطاهم ابراهيم عطايا وصرفهم عن اسحاق ابنه شرقا الى ارض المشرق وهو بعد حي.","25:7":"وهذه ايام سني حياة ابراهيم التي عاشها: مئة وخمس وسبعون سنة.","25:8":"واسلم ابراهيم روحه ومات بشيبة صالحة شيخا وشبعان اياما وانضم الى قومه.","25:9":"ودفنه اسحاق واسماعيل ابناه في مغارة المكفيلة في حقل عفرون بن صوحر الحثي الذي امام ممرا -","25:10":"الحقل الذي اشتراه ابراهيم من بني حث. هناك دفن ابراهيم وسارة امراته.","25:11":"وكان بعد موت ابراهيم ان الله بارك اسحاق ابنه. وسكن اسحاق عند بئر لحي رئي.","25:12":"وهذه مواليد اسماعيل بن ابراهيم الذي ولدته هاجر المصرية جارية سارة لابراهيم.","25:13":"وهذه اسماء بني اسماعيل باسمائهم حسب مواليدهم: نبايوت بكر اسماعيل وقيدار وادبئيل ومبسام","25:14":"ومشماع ودومة ومسا","25:15":"وحدار وتيما ويطور ونافيش وقدمة.","25:16":"هؤلاء هم بنو اسماعيل وهذه اسماؤهم بديارهم وحصونهم. اثنا عشر رئيسا حسب قبائلهم.","25:17":"وهذه سنو حياة اسماعيل: مئة وسبع وثلاثون سنة. واسلم روحه ومات وانضم الى قومه.","25:18":"(وسكنوا من حويلة الى شور التي امام مصر حينما تجيء نحو اشور). امام جميع اخوته نزل.","25:19":"وهذه مواليد اسحاق بن ابراهيم: ولد ابراهيم اسحاق.","25:20":"وكان اسحاق ابن اربعين سنة لما اتخذ لنفسه زوجة رفقة بنت بتوئيل الارامي اخت لابان الارامي من فدان ارام.","25:21":"وصلى اسحاق الى الرب لاجل امراته لانها كانت عاقرا فاستجاب له الرب فحبلت رفقة امراته.","25:22":"وتزاحم الولدان في بطنها فقالت: «ان كان هكذا فلماذا انا؟» فمضت لتسال الرب.","25:23":"فقال لها الرب: «في بطنك امتان ومن احشائك يفترق شعبان: شعب يقوى على شعب وكبير يستعبد لصغير»","25:24":"فلما كملت ايامها لتلد اذا في بطنها توامان.","25:25":"فخرج الاول احمر كله كفروة شعر فدعوا اسمه عيسو.","25:26":"وبعد ذلك خرج اخوه ويده قابضة بعقب عيسو فدعي اسمه يعقوب. وكان اسحاق ابن ستين سنة لما ولدتهما.","25:27":"فكبر الغلامان. وكان عيسو انسانا يعرف الصيد انسان البرية. ويعقوب انسانا كاملا يسكن الخيام.","25:28":"فاحب اسحاق عيسو لان في فمه صيدا واما رفقة فكانت تحب يعقوب.","25:29":"وطبخ يعقوب طبيخا فاتى عيسو من الحقل وهو قد اعيا.","25:30":"فقال عيسو ليعقوب: «اطعمني من هذا الاحمر لاني قد اعييت. (لذلك دعي اسمه ادوم).","25:31":"فقال يعقوب: «بعني اليوم بكوريتك».","25:32":"فقال عيسو: «ها انا ماض الى الموت فلماذا لي بكورية؟»","25:33":"فقال يعقوب: «احلف لي اليوم». فحلف له. فباع بكوريته ليعقوب.","25:34":"فاعطى يعقوب عيسو خبزا وطبيخ عدس فاكل وشرب وقام ومضى. فاحتقر عيسو البكورية.","26:1":"وكان في الارض جوع غير الجوع الاول الذي كان في ايام ابراهيم فذهب اسحاق الى ابيمالك ملك الفلسطينيين الى جرار.","26:2":"وظهر له الرب وقال: «لا تنزل الى مصر. اسكن في الارض التي اقول لك.","26:3":"تغرب في هذه الارض فاكون معك واباركك لاني لك ولنسلك اعطي جميع هذه البلاد وافي بالقسم الذي اقسمت لابراهيم ابيك.","26:4":"واكثر نسلك كنجوم السماء واعطي نسلك جميع هذه البلاد وتتبارك في نسلك جميع امم الارض","26:5":"من اجل ان ابراهيم سمع لقولي وحفظ ما يحفظ لي: اوامري وفرائضي وشرائعي».","26:6":"فاقام اسحاق في جرار.","26:7":"وساله اهل المكان عن امراته فقال: «هي اختي». لانه خاف ان يقول «امراتي» لعل اهل المكان «يقتلونني من اجل رفقة» لانها كانت حسنة المنظر.","26:8":"وحدث اذ طالت له الايام هناك ان ابيمالك ملك الفلسطينيين اشرف من الكوة ونظر واذا اسحاق يلاعب رفقة امراته.","26:9":"فدعا ابيمالك اسحاق وقال: «انما هي امراتك! فكيف قلت: هي اختي؟» فقال له اسحاق: «لاني قلت: لعلي اموت بسببها».","26:10":"فقال ابيمالك: «ما هذا الذي صنعت بنا؟ لولا قليل لاضطجع احد الشعب مع امراتك فجلبت علينا ذنبا».","26:11":"فاوصى ابيمالك جميع الشعب: «الذي يمس هذا الرجل او امراته موتا يموت».","26:12":"وزرع اسحاق في تلك الارض فاصاب في تلك السنة مئة ضعف وباركه الرب.","26:13":"فتعاظم الرجل وكان يتزايد في التعاظم حتى صار عظيما جدا.","26:14":"فكان له مواش من الغنم ومواش من البقر وعبيد كثيرون. فحسده الفلسطينيون.","26:15":"وجميع الابار التي حفرها عبيد ابيه في ايام ابراهيم ابيه طمها الفلسطينيون وملاوها ترابا.","26:16":"وقال ابيمالك لاسحاق: «اذهب من عندنا لانك صرت اقوى منا جدا».","26:17":"فمضى اسحاق من هناك. ونزل في وادي جرار واقام هناك.","26:18":"فعاد اسحاق ونبش ابار الماء التي حفروها في ايام ابراهيم ابيه وطمها الفلسطينيون بعد موت ابيه ودعاها باسماء كالاسماء التي دعاها بها ابوه.","26:19":"وحفر عبيد اسحاق في الوادي فوجدوا هناك بئر ماء حي.","26:20":"فخاصم رعاة جرار رعاة اسحاق قائلين: «لنا الماء». فدعا اسم البئر «عسق» لانهم نازعوه.","26:21":"ثم حفروا بئرا اخرى وتخاصموا عليها ايضا فدعا اسمها «سطنة».","26:22":"ثم نقل من هناك وحفر بئرا اخرى ولم يتخاصموا عليها فدعا اسمها «رحوبوت» وقال: «انه الان قد ارحب لنا الرب واثمرنا في الارض».","26:23":"ثم صعد من هناك الى بئر سبع.","26:24":"فظهر له الرب في تلك الليلة وقال: «انا اله ابراهيم ابيك. لا تخف لاني معك واباركك واكثر نسلك من اجل ابراهيم عبدي».","26:25":"فبنى هناك مذبحا ودعا باسم الرب. ونصب هناك خيمته. وحفر هناك عبيد اسحاق بئرا.","26:26":"وذهب اليه من جرار ابيمالك واحزات من اصحابه وفيكول رئيس جيشه.","26:27":"فقال لهم اسحاق: «ما بالكم اتيتم الي وانتم قد ابغضتموني وصرفتموني من عندكم؟»","26:28":"فقالوا: «اننا قد راينا ان الرب كان معك فقلنا: ليكن بيننا حلف بيننا وبينك ونقطع معك عهدا:","26:29":"ان لا تصنع بنا شرا كما لم نمسك وكما لم نصنع بك الا خيرا وصرفناك بسلام. انت الان مبارك الرب!»","26:30":"فصنع لهم ضيافة. فاكلوا وشربوا","26:31":"ثم بكروا في الغد وحلفوا بعضهم لبعض وصرفهم اسحاق. فمضوا من عنده بسلام.","26:32":"وحدث في ذلك اليوم ان عبيد اسحاق جاءوا واخبروه عن البئر التي حفروا وقالوا له: «قد وجدنا ماء».","26:33":"فدعاها «شبعة». لذلك اسم المدينة بئر سبع الى هذا اليوم.","26:34":"ولما كان عيسو ابن اربعين سنة اتخذ زوجة: يهوديت ابنة بيري الحثي وبسمة ابنة ايلون الحثي.","26:35":"فكانتا مرارة نفس لاسحاق ورفقة.","27:1":"وحدث لما شاخ اسحاق وكلت عيناه عن النظر انه دعا عيسو ابنه الاكبر وقال له: «يا ابني». فقال له: «هئنذا».","27:2":"فقال: «انني قد شخت ولست اعرف يوم وفاتي.","27:3":"فالان خذ عدتك: جعبتك وقوسك واخرج الى البرية وتصيد لي صيدا","27:4":"واصنع لي اطعمة كما احب واتني بها لاكل حتى تباركك نفسي قبل ان اموت».","27:5":"وكانت رفقة سامعة اذ تكلم اسحاق مع عيسو ابنه. فذهب عيسو الى البرية ليصطاد صيدا لياتي به.","27:6":"واما رفقة فقالت ليعقوب ابنها: «اني قد سمعت اباك يكلم عيسو اخاك قائلا:","27:7":"ائتني بصيد واصنع لي اطعمة لاكل واباركك امام الرب قبل وفاتي.","27:8":"فالان يا ابني اسمع لقولي في ما انا امرك به:","27:9":"اذهب الى الغنم وخذ لي من هناك جديين جيدين من المعزى فاصنعهما اطعمة لابيك كما يحب","27:10":"فتحضرها الى ابيك لياكل حتى يباركك قبل وفاته».","27:11":"فقال يعقوب لرفقة امه: «هوذا عيسو اخي رجل اشعر وانا رجل املس.","27:12":"ربما يجسني ابي فاكون في عينيه كمتهاون واجلب على نفسي لعنة لا بركة».","27:13":"فقالت له امه: «لعنتك علي يا ابني. اسمع لقولي فقط واذهب خذ لي».","27:14":"فذهب واخذ واحضر لامه فصنعت امه اطعمة كما كان ابوه يحب.","27:15":"واخذت رفقة ثياب عيسو ابنها الاكبر الفاخرة التي كانت عندها في البيت والبست يعقوب ابنها الاصغر","27:16":"والبست يديه وملاسة عنقه جلود جديي المعزى.","27:17":"واعطت الاطعمة والخبز التي صنعت في يد يعقوب ابنها.","27:18":"فدخل الى ابيه وقال: «يا ابي». فقال: «هئنذا. من انت يا ابني؟»","27:19":"فقال يعقوب لابيه: «انا عيسو بكرك. قد فعلت كما كلمتني. قم اجلس وكل من صيدي لتباركني نفسك».","27:20":"فقال اسحاق لابنه: «ما هذا الذي اسرعت لتجد يا ابني؟» فقال: «ان الرب الهك قد يسر لي».","27:21":"فقال اسحاق ليعقوب: «تقدم لاجسك يا ابني. اانت هو ابني عيسو ام لا؟»","27:22":"فتقدم يعقوب الى اسحاق ابيه فجسه وقال: «الصوت صوت يعقوب ولكن اليدين يدا عيسو».","27:23":"ولم يعرفه لان يديه كانتا مشعرتين كيدي عيسو اخيه. فباركه.","27:24":"وقال: «هل انت هو ابني عيسو؟» فقال: «انا هو».","27:25":"فقال: «قدم لي لاكل من صيد ابني حتى تباركك نفسي». فقدم له فاكل واحضر له خمرا فشرب.","27:26":"فقال له اسحاق ابوه: «تقدم وقبلني يا ابني».","27:27":"فتقدم وقبله. فشم رائحة ثيابه وباركه. وقال: «انظر! رائحة ابني كرائحة حقل قد باركه الرب.","27:28":"فليعطك الله من ندى السماء ومن دسم الارض وكثرة حنطة وخمر.","27:29":"ليستعبد لك شعوب وتسجد لك قبائل. كن سيدا لاخوتك وليسجد لك بنو امك. ليكن لاعنوك ملعونين ومباركوك مباركين».","27:30":"وحدث عندما فرغ اسحاق من بركة يعقوب ويعقوب قد خرج من لدن اسحاق ابيه ان عيسو اخاه اتى من صيده","27:31":"فصنع هو ايضا اطعمة ودخل بها الى ابيه وقال لابيه: «ليقم ابي وياكل من صيد ابنه حتى تباركني نفسك».","27:32":"فقال له اسحاق ابوه: «من انت؟» فقال: «انا ابنك بكرك عيسو».","27:33":"فارتعد اسحاق ارتعادا عظيما جدا. وقال: «فمن هو الذي اصطاد صيدا واتى به الي فاكلت من الكل قبل ان تجيء وباركته؟ نعم ويكون مباركا!»","27:34":"فعندما سمع عيسو كلام ابيه صرخ صرخة عظيمة ومرة جدا وقال لابيه: «باركني انا ايضا يا ابي!»","27:35":"فقال: «قد جاء اخوك بمكر واخذ بركتك».","27:36":"فقال: «الا ان اسمه دعي يعقوب فقد تعقبني الان مرتين! اخذ بكوريتي وهوذا الان قد اخذ بركتي». ثم قال: «اما ابقيت لي بركة؟»","27:37":"فقال اسحاق لعيسو: «اني قد جعلته سيدا لك ودفعت اليه جميع اخوته عبيدا وعضدته بحنطة وخمر. فماذا اصنع اليك يا ابني؟»","27:38":"فقال عيسو لابيه: «الك بركة واحدة فقط يا ابي؟ باركني انا ايضا يا ابي!» ورفع عيسو صوته وبكى.","27:39":"فاجاب اسحاق ابوه: «هوذا بلا دسم الارض يكون مسكنك وبلا ندى السماء من فوق.","27:40":"وبسيفك تعيش ولاخيك تستعبد. ولكن يكون حينما تجمح انك تكسر نيره عن عنقك».","27:41":"فحقد عيسو على يعقوب من اجل البركة التي باركه بها ابوه. وقال عيسو في قلبه: «قربت ايام مناحة ابي فاقتل يعقوب اخي».","27:42":"فاخبرت رفقة بكلام عيسو ابنها الاكبر فارسلت ودعت يعقوب ابنها الاصغر وقالت له: «هوذا عيسو اخوك متسل من جهتك بانه يقتلك.","27:43":"فالان يا ابني اسمع لقولي وقم اهرب الى اخي لابان الى حاران","27:44":"واقم عنده اياما قليلة حتى يرتد غضب اخيك عنك","27:45":"وينسى ما صنعت به. ثم ارسل فاخذك من هناك. لماذا اعدم اثنيكما في يوم واحد؟».","27:46":"وقالت رفقة لاسحاق: «مللت حياتي من اجل بنات حث. ان كان يعقوب ياخذ زوجة من بنات حث مثل هؤلاء من بنات الارض فلماذا لي حياة؟»","28:1":"فدعا اسحاق يعقوب وباركه واوصاه وقال له: «لا تاخذ زوجة من بنات كنعان.","28:2":"قم اذهب الى فدان ارام الى بيت بتوئيل ابي امك وخذ لنفسك زوجة من هناك من بنات لابان اخي امك.","28:3":"والله القدير يباركك ويجعلك مثمرا ويكثرك فتكون جمهورا من الشعوب.","28:4":"ويعطيك بركة ابراهيم لك ولنسلك معك لترث ارض غربتك التي اعطاها الله لابراهيم».","28:5":"فصرف اسحاق يعقوب فذهب الى فدان ارام الى لابان بن بتوئيل الارامي اخي رفقة ام يعقوب وعيسو.","28:6":"فلما راى عيسو ان اسحاق بارك يعقوب وارسله الى فدان ارام لياخذ لنفسه من هناك زوجة اذ باركه واوصاه قائلا: «لا تاخذ زوجة من بنات كنعان».","28:7":"وان يعقوب سمع لابيه وامه وذهب الى فدان ارام","28:8":"راى عيسو ان بنات كنعان شريرات في عيني اسحاق ابيه","28:9":"فذهب عيسو الى اسماعيل واخذ محلة بنت اسماعيل بن ابراهيم اخت نبايوت زوجة له على نسائه.","28:10":"فخرج يعقوب من بئر سبع وذهب نحو حاران.","28:11":"وصادف مكانا وبات هناك لان الشمس كانت قد غابت. واخذ من حجارة المكان ووضعه تحت راسه فاضطجع في ذلك المكان.","28:12":"وراى حلما واذا سلم منصوبة على الارض وراسها يمس السماء وهوذا ملائكة الله صاعدة ونازلة عليها","28:13":"وهوذا الرب واقف عليها فقال: «انا الرب اله ابراهيم ابيك واله اسحاق. الارض التي انت مضطجع عليها اعطيها لك ولنسلك.","28:14":"ويكون نسلك كتراب الارض وتمتد غربا وشرقا وشمالا وجنوبا. ويتبارك فيك وفي نسلك جميع قبائل الارض.","28:15":"وها انا معك واحفظك حيثما تذهب واردك الى هذه الارض لاني لا اتركك حتى افعل ما كلمتك به».","28:16":"فاستيقظ يعقوب من نومه وقال: «حقا ان الرب في هذا المكان وانا لم اعلم!»","28:17":"وخاف وقال: «ما ارهب هذا المكان! ما هذا الا بيت الله وهذا باب السماء!»","28:18":"وبكر يعقوب في الصباح واخذ الحجر الذي وضعه تحت راسه واقامه عمودا وصب زيتا على راسه","28:19":"ودعا اسم ذلك المكان «بيت ايل». ولكن اسم المدينة اولا كان لوز.","28:20":"ونذر يعقوب نذرا قائلا: «ان كان الله معي وحفظني في هذا الطريق الذي انا سائر فيه واعطاني خبزا لاكل وثيابا لالبس","28:21":"ورجعت بسلام الى بيت ابي يكون الرب لي الها","28:22":"وهذا الحجر الذي اقمته عمودا يكون بيت الله وكل ما تعطيني فاني اعشره لك».","29:1":"ثم قام يعقوب وذهب الى ارض بني المشرق.","29:2":"ونظر واذا في الحقل بئر وهناك ثلاثة قطعان غنم رابضة عندها لانهم كانوا من تلك البئر يسقون القطعان والحجر على فم البئر كان كبيرا.","29:3":"فكان يجتمع الى هناك جميع القطعان فيدحرجون الحجر عن فم البئر ويسقون الغنم ثم يردون الحجر على فم البئر الى مكانه.","29:4":"فقال لهم يعقوب: «يا اخوتي من اين انتم؟» فقالوا: «نحن من حاران».","29:5":"فقال لهم: «هل تعرفون لابان ابن ناحور؟» فقالوا: «نعرفه».","29:6":"فقال لهم: «هل له سلامة؟» فقالوا: «له سلامة. وهوذا راحيل ابنته اتية مع الغنم».","29:7":"فقال: «هوذا النهار بعد طويل. ليس وقت اجتماع المواشي. اسقوا الغنم واذهبوا ارعوا».","29:8":"فقالوا: «لا نقدر حتى تجتمع جميع القطعان ويدحرجوا الحجر عن فم البئر ثم نسقي الغنم».","29:9":"واذ هو بعد يتكلم معهم اتت راحيل مع غنم ابيها لانها كانت ترعى.","29:10":"فكان لما ابصر يعقوب راحيل بنت لابان خاله وغنم لابان خاله ان يعقوب تقدم ودحرج الحجر عن فم البئر وسقى غنم لابان خاله.","29:11":"وقبل يعقوب راحيل ورفع صوته وبكى.","29:12":"واخبر يعقوب راحيل انه اخو ابيها وانه ابن رفقة. فركضت واخبرت اباها.","29:13":"فكان حين سمع لابان خبر يعقوب ابن اخته انه ركض للقائه وعانقه وقبله واتى به الى بيته. فحدث لابان بجميع هذه الامور.","29:14":"فقال له لابان: «انما انت عظمي ولحمي». فاقام عنده شهرا من الزمان.","29:15":"ثم قال لابان ليعقوب: «الانك اخي تخدمني مجانا؟ اخبرني ما اجرتك».","29:16":"وكان للابان ابنتان اسم الكبرى ليئة واسم الصغرى راحيل.","29:17":"وكانت عينا ليئة ضعيفتين واما راحيل فكانت حسنة الصورة وحسنة المنظر.","29:18":"واحب يعقوب راحيل فقال: «اخدمك سبع سنين براحيل ابنتك الصغرى».","29:19":"فقال لابان: «ان اعطيك اياها احسن من ان اعطيها لرجل اخر. اقم عندي».","29:20":"فخدم يعقوب براحيل سبع سنين وكانت في عينيه كايام قليلة بسبب محبته لها.","29:21":"ثم قال يعقوب للابان: «اعطني امراتي لان ايامي قد كملت فادخل عليها».","29:22":"فجمع لابان جميع اهل المكان وصنع وليمة.","29:23":"وكان في المساء انه اخذ ليئة ابنته واتى بها اليه فدخل عليها.","29:24":"واعطى لابان زلفة جاريته لليئة ابنته جارية.","29:25":"وفي الصباح اذا هي ليئة. فقال للابان: «ما هذا الذي صنعت بي! اليس براحيل خدمت عندك؟ فلماذا خدعتني؟»","29:26":"فقال لابان: «لا يفعل هكذا في مكاننا ان تعطى الصغيرة قبل البكر.","29:27":"اكمل اسبوع هذه فنعطيك تلك ايضا بالخدمة التي تخدمني ايضا سبع سنين اخر».","29:28":"ففعل يعقوب هكذا. فاكمل اسبوع هذه فاعطاه راحيل ابنته زوجة له.","29:29":"واعطى لابان راحيل ابنته بلهة جاريته جارية لها.","29:30":"فدخل على راحيل ايضا. واحب ايضا راحيل اكثر من ليئة. وعاد فخدم عنده سبع سنين اخر.","29:31":"وراى الرب ان ليئة مكروهة ففتح رحمها. واما راحيل فكانت عاقرا.","29:32":"فحبلت ليئة وولدت ابنا ودعت اسمه راوبين لانها قالت: «ان الرب قد نظر الى مذلتي. انه الان يحبني رجلي».","29:33":"وحبلت ايضا وولدت ابنا وقالت: «ان الرب قد سمع اني مكروهة فاعطاني هذا ايضا». فدعت اسمه «شمعون».","29:34":"وحبلت ايضا وولدت ابنا وقالت: «الان هذه المرة يقترن بي رجلي لاني ولدت له ثلاثة بنين». لذلك دعي اسمه «لاوي».","29:35":"وحبلت ايضا وولدت ابنا وقالت: «هذه المرة احمد الرب». لذلك دعت اسمه «يهوذا». ثم توقفت عن الولادة.","30:1":"فلما رات راحيل انها لم تلد ليعقوب غارت راحيل من اختها وقالت ليعقوب: «هب لي بنين والا فانا اموت».","30:2":"فحمي غضب يعقوب على راحيل وقال: «العلي مكان الله الذي منع عنك ثمرة البطن؟»","30:3":"فقالت: «هوذا جاريتي بلهة. ادخل عليها فتلد على ركبتي وارزق انا ايضا منها بنين».","30:4":"فاعطته بلهة جاريتها زوجة فدخل عليها يعقوب","30:5":"فحبلت بلهة وولدت ليعقوب ابنا","30:6":"فقالت راحيل: «قد قضى لي الله وسمع ايضا لصوتي واعطاني ابنا». لذلك دعت اسمه «دانا».","30:7":"وحبلت ايضا بلهة جارية راحيل وولدت ابنا ثانيا ليعقوب","30:8":"فقالت راحيل: «قد صارعت اختي مصارعات الله وغلبت». فدعت اسمه «نفتالي».","30:9":"ولما رات ليئة انها توقفت عن الولادة اخذت زلفة جاريتها واعطتها ليعقوب زوجة","30:10":"فولدت زلفة جارية ليئة ليعقوب ابنا.","30:11":"فقالت ليئة: «بسعد». فدعت اسمه «جادا».","30:12":"وولدت زلفة جارية ليئة ابنا ثانيا ليعقوب","30:13":"فقالت ليئة: «بغبطتي لانه تغبطني بنات». فدعت اسمه «اشير».","30:14":"ومضى راوبين في ايام حصاد الحنطة فوجد لفاحا في الحقل وجاء به الى ليئة امه. فقالت راحيل لليئة: «اعطيني من لفاح ابنك».","30:15":"فقالت لها: «اقليل انك اخذت رجلي فتاخذين لفاح ابني ايضا؟» فقالت راحيل: «اذا يضطجع معك الليلة عوضا عن لفاح ابنك».","30:16":"فلما اتى يعقوب من الحقل في المساء خرجت ليئة لملاقاته وقالت: «الي تجيء لاني قد استاجرتك بلفاح ابني». فاضطجع معها تلك الليلة.","30:17":"وسمع الله لليئة فحبلت وولدت ليعقوب ابنا خامسا.","30:18":"فقالت ليئة: «قد اعطاني الله اجرتي لاني اعطيت جاريتي لرجلي». فدعت اسمه «يساكر».","30:19":"وحبلت ايضا ليئة وولدت ابنا سادسا ليعقوب","30:20":"فقالت ليئة: «قد وهبني الله هبة حسنة. الان يساكنني رجلي لاني ولدت له ستة بنين». فدعت اسمه «زبولون».","30:21":"ثم ولدت ابنة ودعت اسمها «دينة».","30:22":"وذكر الله راحيل وسمع لها الله وفتح رحمها","30:23":"فحبلت وولدت ابنا فقالت: «قد نزع الله عاري».","30:24":"ودعت اسمه «يوسف» قائلة: «يزيدني الرب ابنا اخر».","30:25":"وحدث لما ولدت راحيل يوسف ان يعقوب قال للابان: «اصرفني لاذهب الى مكاني والى ارضي.","30:26":"اعطني نسائي واولادي الذين خدمتك بهم فاذهب لانك انت تعلم خدمتي التي خدمتك».","30:27":"فقال له لابان: «ليتني اجد نعمة في عينيك. قد تفاءلت فباركني الرب بسببك».","30:28":"وقال: «عين لي اجرتك فاعطيك».","30:29":"فقال له: «انت تعلم ماذا خدمتك وماذا صارت مواشيك معي","30:30":"لان ما كان لك قبلي قليل فقد اتسع الى كثير وباركك الرب في اثري. والان متى اعمل انا ايضا لبيتي؟»","30:31":"فقال: «ماذا اعطيك؟» فقال يعقوب: «لا تعطيني شيئا. ان صنعت لي هذا الامر اعود ارعى غنمك واحفظها:","30:32":"اجتاز بين غنمك كلها اليوم واعزل انت منها كل شاة رقطاء وبلقاء وكل شاة سوداء بين الخرفان وبلقاء ورقطاء بين المعزى. فيكون مثل ذلك اجرتي","30:33":"ويشهد في بري يوم غد اذا جئت من اجل اجرتي قدامك. كل ما ليس ارقط او ابلق بين المعزى واسود بين الخرفان فهو مسروق عندي».","30:34":"فقال لابان: «هوذا ليكن بحسب كلامك».","30:35":"فعزل في ذلك اليوم التيوس المخططة والبلقاء وكل العناز الرقطاء والبلقاء كل ما فيه بياض وكل اسود بين الخرفان ودفعها الى ايدي بنيه.","30:36":"وجعل مسيرة ثلاثة ايام بينه وبين يعقوب. وكان يعقوب يرعى غنم لابان الباقية.","30:37":"فاخذ يعقوب لنفسه قضبانا خضرا من لبنى ولوز ودلب وقشر فيها خطوطا بيضا كاشطا عن البياض الذي على القضبان.","30:38":"واوقف القضبان التي قشرها في الاجران في مساقي الماء حيث كانت الغنم تجيء لتشرب تجاه الغنم لتتوحم عند مجيئها لتشرب.","30:39":"فتوحمت الغنم عند القضبان وولدت الغنم مخططات ورقطا وبلقا.","30:40":"وافرز يعقوب الخرفان وجعل وجوه الغنم الى المخطط وكل اسود بين غنم لابان. وجعل له قطعانا وحده ولم يجعلها مع غنم لابان.","30:41":"وحدث كلما توحمت الغنم القوية ان يعقوب وضع القضبان امام عيون الغنم في الاجران لتتوحم بين القضبان.","30:42":"وحين استضعفت الغنم لم يضعها. فصارت الضعيفة للابان والقوية ليعقوب.","30:43":"فاتسع الرجل كثيرا جدا وكان له غنم كثير وجوار وعبيد وجمال وحمير.","31:1":"فسمع يعقوب بني لابان يقولون: «اخذ يعقوب كل ما كان لابينا ومما لابينا صنع كل هذا المجد».","31:2":"ونظر يعقوب وجه لابان واذا هو ليس معه كامس واول من امس.","31:3":"وقال الرب ليعقوب: «ارجع الى ارض ابائك والى عشيرتك فاكون معك».","31:4":"فارسل يعقوب ودعا راحيل وليئة الى الحقل الى غنمه","31:5":"وقال لهما: «انا ارى وجه ابيكما انه ليس نحوي كامس واول من امس. ولكن اله ابي كان معي.","31:6":"وانتما تعلمان اني بكل قوتي خدمت اباكما","31:7":"واما ابوكما فغدر بي وغير اجرتي عشر مرات. لكن الله لم يسمح له ان يصنع بي شرا.","31:8":"ان قال: الرقط تكون اجرتك ولدت كل الغنم رقطا. وان قال: المخططة تكون اجرتك ولدت كل الغنم مخططة.","31:9":"فقد سلب الله مواشي ابيكما واعطاني.","31:10":"وحدث في وقت توحم الغنم اني رفعت عيني ونظرت في حلم واذا الفحول الصاعدة على الغنم مخططة ورقطاء ومنمرة.","31:11":"وقال لي ملاك الله في الحلم: يا يعقوب. فقلت: هئنذا.","31:12":"فقال: ارفع عينيك وانظر! جميع الفحول الصاعدة على الغنم مخططة ورقطاء ومنمرة لاني قد رايت كل ما يصنع بك لابان.","31:13":"انا اله بيت ايل حيث مسحت عمودا. حيث نذرت لي نذرا. الان قم اخرج من هذه الارض وارجع الى ارض ميلادك».","31:14":"فاجابت راحيل وليئة: «النا ايضا نصيب وميراث في بيت ابينا؟","31:15":"الم نحسب منه اجنبيتين لانه باعنا وقد اكل ايضا ثمننا؟","31:16":"ان كل الغنى الذي سلبه الله من ابينا هو لنا ولاولادنا. فالان كل ما قال لك الله افعل».","31:17":"فقام يعقوب وحمل اولاده ونساءه على الجمال","31:18":"وساق كل مواشيه وجميع مقتناه الذي كان قد اقتنى: مواشي اقتنائه التي اقتنى في فدان ارام ليجيء الى اسحاق ابيه الى ارض كنعان.","31:19":"واما لابان فكان قد مضى ليجز غنمه فسرقت راحيل اصنام ابيها.","31:20":"وخدع يعقوب قلب لابان الارامي اذ لم يخبره بانه هارب.","31:21":"فهرب هو وكل ما كان له وقام وعبر النهر وجعل وجهه نحو جبل جلعاد.","31:22":"فاخبر لابان في اليوم الثالث بان يعقوب قد هرب","31:23":"فاخذ اخوته معه وسعى وراءه مسيرة سبعة ايام فادركه في جبل جلعاد.","31:24":"واتى الله الى لابان الارامي في حلم الليل وقال له: «احترز من ان تكلم يعقوب بخير او شر».","31:25":"فلحق لابان يعقوب ويعقوب قد ضرب خيمته في الجبل. فضرب لابان مع اخوته في جبل جلعاد.","31:26":"وقال لابان ليعقوب: «ماذا فعلت وقد خدعت قلبي وسقت بناتي كسبايا السيف؟","31:27":"لماذا هربت خفية وخدعتني ولم تخبرني حتى اشيعك بالفرح والاغاني بالدف والعود","31:28":"ولم تدعني اقبل بني وبناتي؟ الان بغباوة فعلت!","31:29":"في قدرة يدي ان اصنع بكم شرا ولكن اله ابيكم كلمني البارحة قائلا: احترز من ان تكلم يعقوب بخير او شر.","31:30":"والان انت ذهبت لانك قد اشتقت الى بيت ابيك ولكن لماذا سرقت الهتي؟»","31:31":"فاجاب يعقوب: «اني خفت لاني قلت لعلك تغتصب ابنتيك مني.","31:32":"الذي تجد الهتك معه لا يعيش. قدام اخوتنا انظر ماذا معي وخذه لنفسك». (ولم يكن يعقوب يعلم ان راحيل سرقتها).","31:33":"فدخل لابان خباء يعقوب وخباء ليئة وخباء الجاريتين ولم يجد. وخرج من خباء ليئة ودخل خباء راحيل.","31:34":"وكانت راحيل قد اخذت الاصنام ووضعتها في حداجة الجمل وجلست عليها. فجس لابان كل الخباء ولم يجد.","31:35":"وقالت لابيها: «لا يغتظ سيدي اني لا استطيع ان اقوم امامك لان علي عادة النساء». ففتش ولم يجد الاصنام.","31:36":"فاغتاظ يعقوب وخاصم لابان. وقال يعقوب للابان: «ما جرمي؟ ما خطيتي حتى حميت ورائي؟","31:37":"انك جسست جميع اثاثي. ماذا وجدت من جميع اثاث بيتك؟ ضعه ههنا قدام اخوتي واخوتك! فلينصفوا بيننا الاثنين.","31:38":"الان عشرين سنة انا معك. نعاجك وعنازك لم تسقط. وكباش غنمك لم اكل.","31:39":"فريسة لم احضر اليك. انا كنت اخسرها. من يدي كنت تطلبها. مسروقة النهار او مسروقة الليل.","31:40":"كنت في النهار ياكلني الحر وفي الليل الجليد وطار نومي من عيني.","31:41":"الان لي عشرون سنة في بيتك. خدمتك اربع عشرة سنة بابنتيك وست سنين بغنمك. وقد غيرت اجرتي عشر مرات!","31:42":"لولا ان اله ابي اله ابراهيم وهيبة اسحاق كان معي لكنت الان قد صرفتني فارغا. قد نظر الله مشقتي وتعب يدي فوبخك البارحة».","31:43":"فاجاب لابان: «البنات بناتي والبنون بني والغنم غنمي وكل ما انت ترى فهو لي. فبناتي ماذا اصنع بهن اليوم او باولادهن الذين ولدن؟","31:44":"فالان هلم نقطع عهدا انا وانت فيكون شاهدا بيني وبينك».","31:45":"فاخذ يعقوب حجرا واوقفه عمودا","31:46":"وقال يعقوب لاخوته: «التقطوا حجارة». فاخذوا حجارة وعملوا رجمة واكلوا هناك على الرجمة.","31:47":"ودعاها لابان «يجر سهدوثا» واما يعقوب فدعاها «جلعيد»","31:48":"وقال لابان: «هذه الرجمة هي شاهدة بيني وبينك اليوم». لذلك دعي اسمها «جلعيد»","31:49":"و «المصفاة» لانه قال: «ليراقب الرب بيني وبينك حينما نتوارى بعضنا عن بعض.","31:50":"انك لا تذل بناتي ولا تاخذ نساء على بناتي. ليس انسان معنا. انظر. الله شاهد بيني وبينك».","31:51":"وقال لابان ليعقوب: «هوذا هذه الرجمة وهوذا العمود الذي وضعت بيني وبينك.","31:52":"شاهدة هذه الرجمة وشاهد العمود اني لا اتجاوز هذه الرجمة اليك وانك لا تتجاوز هذه الرجمة وهذا العمود الي للشر.","31:53":"اله ابراهيم والهة ناحور الهة ابيهما يقضون بيننا». وحلف يعقوب بهيبة ابيه اسحاق.","31:54":"وذبح يعقوب ذبيحة في الجبل ودعا اخوته لياكلوا طعاما. فاكلوا طعاما وباتوا في الجبل.","31:55":"ثم بكر لابان صباحا وقبل بنيه وبناته وباركهم ومضى. ورجع لابان الى مكانه.","32:1":"واما يعقوب فمضى في طريقه ولاقاه ملائكة الله.","32:2":"وقال يعقوب اذ راهم: «هذا جيش الله!» فدعا اسم ذلك المكان «محنايم».","32:3":"وارسل يعقوب رسلا قدامه الى عيسو اخيه الى ارض سعير بلاد ادوم","32:4":"وامرهم: «هكذا تقولون لسيدي عيسو: هكذا قال عبدك يعقوب: تغربت عند لابان ولبثت الى الان.","32:5":"وقد صار لي بقر وحمير وغنم وعبيد واماء. وارسلت لاخبر سيدي لكي اجد نعمة في عينيك».","32:6":"فرجع الرسل الى يعقوب قائلين: «اتينا الى اخيك الى عيسو وهو ايضا قادم للقائك واربع مئة رجل معه».","32:7":"فخاف يعقوب جدا وضاق به الامر. فقسم القوم الذين معه والغنم والبقر والجمال الى جيشين.","32:8":"وقال: «ان جاء عيسو الى الجيش الواحد وضربه يكون الجيش الباقي ناجيا».","32:9":"وقال يعقوب: «يا اله ابي ابراهيم واله ابي اسحاق الرب الذي قال لي: ارجع الى ارضك والى عشيرتك فاحسن اليك.","32:10":"صغير انا عن جميع الطافك وجميع الامانة التي صنعت الى عبدك. فاني بعصاي عبرت هذا الاردن والان قد صرت جيشين.","32:11":"نجني من يد اخي من يد عيسو لاني خائف منه ان ياتي ويضربني الام مع البنين.","32:12":"وانت قد قلت: اني احسن اليك واجعل نسلك كرمل البحر الذي لا يعد للكثرة».","32:13":"وبات هناك تلك الليلة واخذ مما اتى بيده هدية لعيسو اخيه:","32:14":"مئتي عنز وعشرين تيسا مئتي نعجة وعشرين كبشا","32:15":"ثلاثين ناقة مرضعة واولادها اربعين بقرة وعشرة ثيران عشرين اتانا وعشرة حمير","32:16":"ودفعها الى يد عبيده قطيعا قطيعا على حدة. وقال لعبيده: «اجتازوا قدامي واجعلوا فسحة بين قطيع وقطيع».","32:17":"وامر الاول: «اذا صادفك عيسو اخي وسالك: لمن انت والى اين تذهب ولمن هذا الذي قدامك؟","32:18":"تقول: لعبدك يعقوب. هو هدية مرسلة لسيدي عيسو وها هو ايضا وراءنا».","32:19":"وامر ايضا الثاني والثالث وجميع السائرين وراء القطعان: «بمثل هذا الكلام تكلمون عيسو حينما تجدونه","32:20":"وتقولون: هوذا عبدك يعقوب ايضا وراءنا». لانه قال: «استعطف وجهه بالهدية السائرة امامي وبعد ذلك انظر وجهه عسى ان يرفع وجهي».","32:21":"فاجتازت الهدية قدامه واما هو فبات تلك الليلة في المحلة.","32:22":"ثم قام في تلك الليلة واخذ امراتيه وجاريتيه واولاده الاحد عشر وعبر مخاضة يبوق.","32:23":"اخذهم واجازهم الوادي واجاز ما كان له.","32:24":"فبقي يعقوب وحده. وصارعه انسان حتى طلوع الفجر.","32:25":"ولما راى انه لا يقدر عليه ضرب حق فخذه فانخلع حق فخذ يعقوب في مصارعته معه.","32:26":"وقال: «اطلقني لانه قد طلع الفجر». فقال: «لا اطلقك ان لم تباركني».","32:27":"فساله: «ما اسمك؟» فقال: «يعقوب».","32:28":"فقال: «لا يدعى اسمك في ما بعد يعقوب بل اسرائيل لانك جاهدت مع الله والناس وقدرت».","32:29":"وساله يعقوب: «اخبرني باسمك». فقال: «لماذا تسال عن اسمي؟» وباركه هناك.","32:30":"فدعا يعقوب اسم المكان «فنيئيل» قائلا: «لاني نظرت الله وجها لوجه ونجيت نفسي».","32:31":"واشرقت له الشمس اذ عبر فنوئيل وهو يخمع على فخذه -","32:32":"لذلك لا ياكل بنو اسرائيل عرق النسا الذي على حق الفخذ الى هذا اليوم لانه ضرب حق فخذ يعقوب على عرق النسا.","33:1":"ورفع يعقوب عينيه ونظر واذا عيسو مقبل ومعه اربع مئة رجل فقسم الاولاد على ليئة وعلى راحيل وعلى الجاريتين","33:2":"ووضع الجاريتين واولادهما اولا وليئة واولادها وراءهم وراحيل ويوسف اخيرا.","33:3":"واما هو فاجتاز قدامهم وسجد الى الارض سبع مرات حتى اقترب الى اخيه.","33:4":"فركض عيسو للقائه وعانقه ووقع على عنقه وقبله. وبكيا.","33:5":"ثم رفع عينيه وابصر النساء والاولاد وقال: «ما هؤلاء منك؟» فقال: «الاولاد الذين انعم الله بهم على عبدك».","33:6":"فاقتربت الجاريتان هما واولادهما وسجدتا","33:7":"ثم اقتربت ليئة ايضا واولادها وسجدوا وبعد ذلك اقترب يوسف وراحيل وسجدا.","33:8":"فقال: «ماذا منك كل هذا الجيش الذي صادفته؟» فقال: «لاجد نعمة في عيني سيدي».","33:9":"فقال عيسو: «لي كثير. يا اخي ليكن لك الذي لك».","33:10":"فقال يعقوب: «لا. ان وجدت نعمة في عينيك تاخذ هديتي من يدي لاني رايت وجهك كما يرى وجه الله فرضيت علي.","33:11":"خذ بركتي التي اتي بها اليك لان الله قد انعم علي ولي كل شيء». والح عليه فاخذ.","33:12":"ثم قال: «لنرحل ونذهب واذهب انا قدامك».","33:13":"فقال له: «سيدي عالم ان الاولاد رخصة والغنم والبقر التي عندي مرضعة. فان استكدوها يوما واحدا ماتت كل الغنم.","33:14":"ليجتز سيدي قدام عبده وانا استاق على مهلي في اثر الاملاك التي قدامي وفي اثر الاولاد حتى اجيء الى سيدي الى سعير».","33:15":"فقال عيسو: «اترك عندك من القوم الذين معي». فقال: «لماذا؟ دعني اجد نعمة في عيني سيدي».","33:16":"فرجع عيسو ذلك اليوم في طريقه الى سعير.","33:17":"واما يعقوب فارتحل الى سكوت وبنى لنفسه بيتا وصنع لمواشيه مظلات. لذلك دعا اسم المكان «سكوت».","33:18":"ثم اتى يعقوب سالما الى مدينة شكيم التي في ارض كنعان حين جاء من فدان ارام. ونزل امام المدينة.","33:19":"وابتاع قطعة الحقل التي نصب فيها خيمته من يد بني حمور ابي شكيم بمئة قسيطة.","33:20":"واقام هناك مذبحا ودعاه «ايل اله اسرائيل».","34:1":"وخرجت دينة ابنة ليئة التي ولدتها ليعقوب لتنظر بنات الارض","34:2":"فراها شكيم ابن حمور الحوي رئيس الارض واخذها واضطجع معها واذلها.","34:3":"وتعلقت نفسه بدينة ابنة يعقوب واحب الفتاة ولاطفها.","34:4":"فقال شكيم لحمور ابيه: «خذ لي هذه الصبية زوجة».","34:5":"وسمع يعقوب انه نجس دينة ابنته. واما بنوه فكانوا مع مواشيه في الحقل فسكت يعقوب حتى جاءوا.","34:6":"فخرج حمور ابو شكيم الى يعقوب ليتكلم معه.","34:7":"واتى بنو يعقوب من الحقل حين سمعوا. وغضب الرجال واغتاظوا جدا لانه صنع قباحة في اسرائيل بمضاجعة ابنة يعقوب. و«هكذا لا يصنع».","34:8":"وقال لهم حمور: «شكيم ابني قد تعلقت نفسه بابنتكم. اعطوه اياها زوجة","34:9":"وصاهرونا. تعطوننا بناتكم وتاخذون لكم بناتنا","34:10":"وتسكنون معنا وتكون الارض قدامكم. اسكنوا واتجروا فيها وتملكوا بها».","34:11":"ثم قال شكيم لابيها ولاخوتها: «دعوني اجد نعمة في اعينكم. فالذي تقولون لي اعطي.","34:12":"كثروا علي جدا مهرا وعطية فاعطي كما تقولون لي. واعطوني الفتاة زوجة».","34:13":"فاجاب بنو يعقوب شكيم وحمور اباه بمكر لانه كان قد نجس دينة اختهم:","34:14":"«لا نستطيع ان نفعل هذا الامر ان نعطي اختنا لرجل اغلف لانه عار لنا.","34:15":"غير اننا بهذا نواتيكم: ان صرتم مثلنا بختنكم كل ذكر.","34:16":"نعطيكم بناتنا وناخذ لنا بناتكم ونسكن معكم ونصير شعبا واحدا.","34:17":"وان لم تسمعوا لنا ان تختتنوا ناخذ ابنتنا ونمضي».","34:18":"فحسن كلامهم في عيني حمور وفي عيني شكيم بن حمور.","34:19":"ولم يتاخر الغلام ان يفعل الامر لانه كان مسرورا بابنة يعقوب. وكان اكرم جميع بيت ابيه.","34:20":"فاتى حمور وشكيم ابنه الى باب مدينتهما وقالا لاهل مدينتهما:","34:21":"«هؤلاء القوم مسالمون لنا. فليسكنوا في الارض ويتجروا فيها. وهوذا الارض واسعة الطرفين امامهم. ناخذ لنا بناتهم زوجات ونعطيهم بناتنا.","34:22":"غير انه بهذا فقط يواتينا القوم على السكن معنا لنصير شعبا واحدا: بختننا كل ذكر كما هم مختونون.","34:23":"الا تكون مواشيهم ومقتناهم وكل بهائمهم لنا؟ نواتيهم فقط فيسكنون معنا».","34:24":"فسمع لحمور وشكيم ابنه جميع الخارجين من باب المدينة. واختتن كل ذكر - كل الخارجين من باب المدينة.","34:25":"فحدث في اليوم الثالث اذ كانوا متوجعين ان ابني يعقوب شمعون ولاوي اخوي دينة اخذا كل واحد سيفه واتيا على المدينة بامن وقتلا كل ذكر.","34:26":"وقتلا حمور وشكيم ابنه بحد السيف واخذا دينة من بيت شكيم وخرجا.","34:27":"ثم اتى بنو يعقوب على القتلى ونهبوا المدينة لانهم نجسوا اختهم.","34:28":"غنمهم وبقرهم وحميرهم وكل ما في المدينة وما في الحقل اخذوه.","34:29":"وسبوا ونهبوا كل ثروتهم وكل اطفالهم ونساءهم وكل ما في البيوت.","34:30":"فقال يعقوب لشمعون ولاوي: «كدرتماني بتكريهكما اياي عند سكان الارض الكنعانيين والفرزيين وانا نفر قليل. فيجتمعون علي ويضربونني فابيد انا وبيتي».","34:31":"فقالا: «انظير زانية يفعل باختنا؟».","35:1":"ثم قال الله ليعقوب: «قم اصعد الى بيت ايل واقم هناك واصنع هناك مذبحا لله الذي ظهر لك حين هربت من وجه عيسو اخيك».","35:2":"فقال يعقوب لبيته ولكل من كان معه: «اعزلوا الالهة الغريبة التي بينكم وتطهروا وابدلوا ثيابكم.","35:3":"ولنقم ونصعد الى بيت ايل فاصنع هناك مذبحا لله الذي استجاب لي في يوم ضيقتي وكان معي في الطريق الذي ذهبت فيه».","35:4":"فاعطوا يعقوب كل الالهة الغريبة التي في ايديهم والاقراط التي في اذانهم فطمرها يعقوب تحت البطمة التي عند شكيم.","35:5":"ثم رحلوا. وكان خوف الله على المدن التي حولهم فلم يسعوا وراء بني يعقوب.","35:6":"فاتى يعقوب الى لوز التي في ارض كنعان (وهي بيت ايل) هو وجميع القوم الذين معه.","35:7":"وبنى هناك مذبحا ودعا المكان «ايل بيت ايل» لانه هناك ظهر له الله حين هرب من وجه اخيه.","35:8":"وماتت دبورة مرضعة رفقة ودفنت تحت بيت ايل تحت البلوطة فدعا اسمها «الون باكوت».","35:9":"وظهر الله ليعقوب ايضا حين جاء من فدان ارام وباركه.","35:10":"وقال له الله: «اسمك يعقوب. لا يدعى اسمك فيما بعد يعقوب بل يكون اسمك اسرائيل». فدعا اسمه اسرائيل.","35:11":"وقال له الله: «انا الله القدير. اثمر واكثر. امة وجماعة امم تكون منك. وملوك سيخرجون من صلبك.","35:12":"والارض التي اعطيت ابراهيم واسحاق لك اعطيها. ولنسلك من بعدك اعطي الارض».","35:13":"ثم صعد الله عنه في المكان الذي فيه تكلم معه","35:14":"فنصب يعقوب عمودا في المكان الذي فيه تكلم معه عمودا من حجر وسكب عليه سكيبا وصب عليه زيتا","35:15":"ودعا يعقوب اسم المكان الذي فيه تكلم الله معه «بيت ايل».","35:16":"ثم رحلوا من بيت ايل. ولما كان مسافة من الارض بعد حتى ياتوا الى افراتة ولدت راحيل وتعسرت ولادتها.","35:17":"فقالت القابلة لها: «لا تخافي لان هذا ايضا ابن لك».","35:18":"وكان عند خروج نفسها (لانها ماتت) انها دعت اسمه «بن اوني». واما ابوه فدعاه بنيامين.","35:19":"فماتت راحيل ودفنت في طريق افراتة (التي هي بيت لحم).","35:20":"فنصب يعقوب عمودا على قبرها. وهو «عمود قبر راحيل» الى اليوم.","35:21":"ثم رحل اسرائيل ونصب خيمته وراء مجدل عدر.","35:22":"وحدث اذ كان اسرائيل ساكنا في تلك الارض ان راوبين ذهب واضطجع مع بلهة سرية ابيه. وسمع اسرائيل. وكان بنو يعقوب اثني عشر:","35:23":"بنو ليئة: راوبين بكر يعقوب وشمعون ولاوي ويهوذا ويساكر وزبولون.","35:24":"وابنا راحيل؛ يوسف وبنيامين.","35:25":"وابنا بلهة جارية راحيل: دان ونفتالي.","35:26":"وابنا زلفة جارية ليئة: جاد واشير. هؤلاء بنو يعقوب الذين ولدوا له في فدان ارام.","35:27":"وجاء يعقوب الى اسحاق ابيه الى ممرا قرية اربع (التي هي حبرون) حيث تغرب ابراهيم واسحاق.","35:28":"وكانت ايام اسحاق مئة وثمانين سنة.","35:29":"فاسلم اسحاق روحه ومات وانضم الى قومه شيخا وشبعان اياما ودفنه عيسو ويعقوب ابناه.","36:1":"وهذه مواليد عيسو الذي هو ادوم:","36:2":"اخذ عيسو نساءه من بنات كنعان: عدا بنت ايلون الحثي واهوليبامة بنت عنى بنت صبعون الحوي","36:3":"وبسمة بنت اسماعيل اخت نبايوت.","36:4":"فولدت عدا لعيسو اليفاز وولدت بسمة رعوئيل","36:5":"وولدت اهوليبامة: يعوش ويعلام وقورح. هؤلاء بنو عيسو الذين ولدوا له في ارض كنعان.","36:6":"ثم اخذ عيسو نساءه وبنيه وبناته وجميع نفوس بيته ومواشيه وكل بهائمه وكل مقتناه الذي اقتنى في ارض كنعان ومضى الى ارض اخرى من وجه يعقوب اخيه","36:7":"لان املاكهما كانت كثيرة على السكنى معا ولم تستطع ارض غربتهما ان تحملهما من اجل مواشيهما","36:8":"فسكن عيسو في جبل سعير. (وعيسو هو ادوم).","36:9":"وهذه مواليد عيسو ابي ادوم في جبل سعير.","36:10":"هذه اسماء بني عيسو: اليفاز ابن عدا امراة عيسو ورعوئيل ابن بسمة امراة عيسو.","36:11":"وكان بنو اليفاز: تيمان واومار وصفوا وجعثام وقناز.","36:12":"وكانت تمناع سرية لاليفاز بن عيسو فولدت لاليفاز عماليق. هؤلاء بنو عدا امراة عيسو.","36:13":"وهؤلاء بنو رعوئيل: نحث وزارح وشمة ومزة. هؤلاء كانوا بني بسمة امراة عيسو.","36:14":"وهؤلاء كانوا بني اهوليبامة بنت عنى بنت صبعون امراة عيسو: ولدت لعيسو يعوش ويعلام وقورح.","36:15":"هؤلاء امراء بني عيسو: بنو اليفاز بكر عيسو امير تيمان وامير اومار وامير صفو وامير قناز","36:16":"وامير قورح وامير جعثام وامير عماليق. هؤلاء امراء اليفاز في ارض ادوم. هؤلاء بنو عدا.","36:17":"وهؤلاء بنو رعوئيل بن عيسو: امير نحث وامير زارح وامير شمة وامير مزة. هؤلاء امراء رعوئيل في ارض ادوم. هؤلاء بنو بسمة امراة عيسو.","36:18":"وهؤلاء بنو اهوليبامة امراة عيسو: امير يعوش وامير يعلام وامير قورح. هؤلاء امراء اهوليبامة بنت عنى امراة عيسو.","36:19":"هؤلاء بنو عيسو الذي هو ادوم وهؤلاء امراؤهم.","36:20":"هؤلاء بنو سعير الحوري سكان الارض: لوطان وشوبال وصبعون وعنى","36:21":"وديشون وايصر وديشان. هؤلاء امراء الحوريين بنو سعير في ارض ادوم.","36:22":"وكان ابنا لوطان: حوري وهيمام. وكانت تمناع اخت لوطان.","36:23":"وهؤلاء بنو شوبال: علوان ومناحة وعيبال وشفو واونام.","36:24":"وهذان ابنا صبعون: اية وعنى. هذا هو عنى الذي وجد الحمائم في البرية اذ كان يرعى حمير صبعون ابيه.","36:25":"وهذا ابن عنى: ديشون. واهوليبامة هي بنت عنى.","36:26":"وهؤلاء بنو ديشان: حمدان واشبان ويثران وكران.","36:27":"هؤلاء بنو ايصر: بلهان وزعوان وعقان.","36:28":"هذان ابنا ديشان: عوص واران.","36:29":"هؤلاء امراء الحوريين: امير لوطان وامير شوبال وامير سبعون وامير عنى","36:30":"وامير ديشون وامير ايصر وامير ديشان. هؤلاء امراء الحوريين بامرائهم في ارض سعير.","36:31":"وهؤلاء هم الملوك الذين ملكوا في ارض ادوم قبلما ملك ملك لبني اسرائيل.","36:32":"ملك في ادوم بالع بن بعور. وكان اسم مدينته دنهابة.","36:33":"ومات بالع فملك مكانه يوباب بن زارح من بصرة.","36:34":"ومات يوباب فملك مكانه حوشام من ارض التيماني.","36:35":"ومات حوشام فملك مكانه هداد بن بداد الذي كسر مديان في بلاد مواب وكان اسم مدينته عويت.","36:36":"ومات هداد فملك مكانه سملة من مسريقة.","36:37":"ومات سملة فملك مكانه شاول من رحوبوت النهر.","36:38":"ومات شاول فملك مكانه بعل حانان بن عكبور.","36:39":"ومات بعل حانان بن عكبور فملك مكانه هدار. وكان اسم مدينته فاعو. واسم امراته مهيطبئيل بنت مطرد بنت ماء ذهب.","36:40":"وهذه اسماء امراء عيسو حسب قبائلهم واماكنهم باسمائهم: امير تمناع وامير علوة وامير يتيت","36:41":"وامير اهوليبامة وامير ايلة وامير فينون","36:42":"وامير قناز وامير تيمان وامير مبصار","36:43":"وامير مجديئيل وامير عيرام. هؤلاء امراء ادوم حسب مساكنهم في ارض ملكهم. هذا هو عيسو ابو ادوم.","37:1":"وسكن يعقوب في ارض غربة ابيه في ارض كنعان.","37:2":"هذه مواليد يعقوب: يوسف اذ كان ابن سبع عشرة سنة كان يرعى مع اخوته الغنم وهو غلام عند بني بلهة وبني زلفة امراتي ابيه. واتى يوسف بنميمتهم الرديئة الى ابيهم.","37:3":"واما اسرائيل فاحب يوسف اكثر من سائر بنيه لانه ابن شيخوخته فصنع له قميصا ملونا.","37:4":"فلما راى اخوته ان اباهم احبه اكثر من جميع اخوته ابغضوه ولم يستطيعوا ان يكلموه بسلام.","37:5":"وحلم يوسف حلما واخبر اخوته فازدادوا ايضا بغضا له.","37:6":"فقال لهم: «اسمعوا هذا الحلم الذي حلمت.","37:7":"فها نحن حازمون حزما في الحقل واذا حزمتي قامت وانتصبت فاحتاطت حزمكم وسجدت لحزمتي».","37:8":"فقال له اخوته: «العلك تملك علينا ملكا ام تتسلط علينا تسلطا؟» وازدادوا ايضا بغضا له من اجل احلامه ومن اجل كلامه.","37:9":"ثم حلم ايضا حلما اخر وقصه على اخوته. فقال: «اني قد حلمت حلما ايضا واذا الشمس والقمر واحد عشر كوكبا ساجدة لي».","37:10":"وقصه على ابيه وعلى اخوته فانتهره ابوه وقال له: «ما هذا الحلم الذي حلمت! هل ناتي انا وامك واخوتك لنسجد لك الى الارض؟»","37:11":"فحسده اخوته واما ابوه فحفظ الامر.","37:12":"ومضى اخوته ليرعوا غنم ابيهم عند شكيم.","37:13":"فقال اسرائيل ليوسف: «اليس اخوتك يرعون عند شكيم؟ تعال فارسلك اليهم». فقال له: «هئنذا».","37:14":"فقال له: «اذهب انظر سلامة اخوتك وسلامة الغنم ورد لي خبرا». فارسله من وطاء حبرون فاتى الى شكيم.","37:15":"فوجده رجل واذا هو ضال في الحقل. فساله الرجل: «ماذا تطلب؟»","37:16":"فقال: «انا طالب اخوتي. اخبرني اين يرعون».","37:17":"فقال الرجل: «قد ارتحلوا من هنا لاني سمعتهم يقولون: لنذهب الى دوثان». فذهب يوسف وراء اخوته فوجدهم في دوثان.","37:18":"فلما ابصروه من بعيد قبلما اقترب اليهم احتالوا له ليميتوه.","37:19":"فقال بعضهم لبعض: «هوذا هذا صاحب الاحلام قادم.","37:20":"فالان هلم نقتله ونطرحه في احدى الابار ونقول: وحش رديء اكله. فنرى ماذا تكون احلامه».","37:21":"فسمع راوبين وانقذه من ايديهم وقال: «لا نقتله».","37:22":"وقال لهم راوبين: «لا تسفكوا دما. اطرحوه في هذه البئر التي في البرية ولا تمدوا اليه يدا» - لكي ينقذه من ايديهم ليرده الى ابيه.","37:23":"فكان لما جاء يوسف الى اخوته انهم خلعوا عنه قميصه الملون الذي عليه","37:24":"واخذوه وطرحوه في البئر. واما البئر فكانت فارغة ليس فيها ماء.","37:25":"ثم جلسوا لياكلوا طعاما. فرفعوا عيونهم ونظروا واذا قافلة اسماعيليين مقبلة من جلعاد وجمالهم حاملة كثيراء وبلسانا ولاذنا ذاهبين لينزلوا بها الى مصر.","37:26":"فقال يهوذا لاخوته: «ما الفائدة ان نقتل اخانا ونخفي دمه؟","37:27":"تعالوا فنبيعه للاسماعيليين ولا تكن ايدينا عليه لانه اخونا ولحمنا». فسمع له اخوته.","37:28":"واجتاز رجال مديانيون تجار فسحبوا يوسف واصعدوه من البئر وباعوا يوسف للاسماعيليين بعشرين من الفضة. فاتوا بيوسف الى مصر.","37:29":"ورجع راوبين الى البئر واذا يوسف ليس في البئر فمزق ثيابه.","37:30":"ثم رجع الى اخوته وقال: «الولد ليس موجودا وانا الى اين اذهب؟»","37:31":"فاخذوا قميص يوسف وذبحوا تيسا من المعزى وغمسوا القميص في الدم","37:32":"وارسلوا القميص الملون واحضروه الى ابيهم وقالوا: «وجدنا هذا. حقق اقميص ابنك هو ام لا؟»","37:33":"فتحققه وقال: «قميص ابني. وحش رديء اكله! افترس يوسف افتراسا!»","37:34":"فمزق يعقوب ثيابه ووضع مسحا على حقويه وناح على ابنه اياما كثيرة.","37:35":"فقام جميع بنيه وجميع بناته ليعزوه. فابى ان يتعزى وقال: «اني انزل الى ابني نائحا الى الهاوية». وبكى عليه ابوه.","37:36":"واما المديانيون فباعوه في مصر لفوطيفار خصي فرعون رئيس الشرط.","38:1":"وحدث في ذلك الزمان ان يهوذا نزل من عند اخوته ومال الى رجل عدلامي اسمه حيرة.","38:2":"ونظر يهوذا هناك ابنة رجل كنعاني اسمه شوع فاخذها ودخل عليها","38:3":"فحبلت وولدت ابنا ودعا اسمه عيرا.","38:4":"ثم حبلت ايضا وولدت ابنا ودعت اسمه اونان.","38:5":"ثم عادت فولدت ايضا ابنا ودعت اسمه شيلة. وكان في كزيب حين ولدته.","38:6":"واخذ يهوذا زوجة لعير بكره اسمها ثامار.","38:7":"وكان عير بكر يهوذا شريرا في عيني الرب فاماته الرب.","38:8":"فقال يهوذا لاونان: «ادخل على امراة اخيك وتزوج بها واقم نسلا لاخيك».","38:9":"فعلم اونان ان النسل لا يكون له. فكان اذ دخل على امراة اخيه انه افسد على الارض لكي لا يعطي نسلا لاخيه.","38:10":"فقبح في عيني الرب ما فعله فاماته ايضا.","38:11":"فقال يهوذا لثامار كنته: «اقعدي ارملة في بيت ابيك حتى يكبر شيلة ابني». لانه قال: «لعله يموت هو ايضا كاخويه». فمضت ثامار وقعدت في بيت ابيها.","38:12":"ولما طال الزمان ماتت ابنة شوع امراة يهوذا. ثم تعزى يهوذا فصعد الى جزاز غنمه الى تمنة هو وحيرة صاحبه العدلامي.","38:13":"فاخبرت ثامار: «هوذا حموك صاعد الى تمنة ليجز غنمه».","38:14":"فخلعت عنها ثياب ترملها وتغطت ببرقع وتلففت وجلست في مدخل عينايم التي على طريق تمنة - لانها رات ان شيلة قد كبر وهي لم تعط له زوجة.","38:15":"فنظرها يهوذا وحسبها زانية لانها كانت قد غطت وجهها.","38:16":"فمال اليها على الطريق وقال: «هاتي ادخل عليك». لانه لم يعلم انها كنته. فقالت: «ماذا تعطيني لكي تدخل علي؟»","38:17":"فقال: «اني ارسل جدي معزى من الغنم». فقالت: «هل تعطيني رهنا حتى ترسله؟»","38:18":"فقال: «ما الرهن الذي اعطيك؟» فقالت: «خاتمك وعصابتك وعصاك التي في يدك». فاعطاها ودخل عليها. فحبلت منه.","38:19":"ثم قامت ومضت وخلعت عنها برقعها ولبست ثياب ترملها.","38:20":"فارسل يهوذا جدي المعزى بيد صاحبه العدلامي لياخذ الرهن من يد المراة فلم يجدها.","38:21":"فسال اهل مكانها: «اين الزانية التي كانت في عينايم على الطريق؟» فقالوا: «لم تكن ههنا زانية».","38:22":"فرجع الى يهوذا وقال: «لم اجدها. واهل المكان ايضا قالوا: لم تكن ههنا زانية».","38:23":"فقال يهوذا: «لتاخذ لنفسها لئلا نصير اهانة. اني قد ارسلت هذا الجدي وانت لم تجدها».","38:24":"ولما كان نحو ثلاثة اشهر اخبر يهوذا وقيل له: «قد زنت ثامار كنتك. وها هي حبلى ايضا من الزنا». فقال يهوذا: «اخرجوها فتحرق».","38:25":"اما هي فلما اخرجت ارسلت الى حميها قائلة: «من الرجل الذي هذه له انا حبلى!» وقالت: «حقق لمن الخاتم والعصابة والعصا هذه».","38:26":"فتحققها يهوذا وقال: «هي ابر مني لاني لم اعطها لشيلة ابني». فلم يعد يعرفها ايضا.","38:27":"وفي وقت ولادتها اذا في بطنها توامان.","38:28":"وكان في ولادتها ان احدهما اخرج يدا فاخذت القابلة وربطت على يده قرمزا قائلة: «هذا خرج اولا».","38:29":"ولكن حين رد يده اذا اخوه قد خرج. فقالت: «لماذا اقتحمت؟ عليك اقتحام». فدعي اسمه «فارص».","38:30":"وبعد ذلك خرج اخوه الذي على يده القرمز. فدعي اسمه «زارح».","39:1":"واما يوسف فانزل الى مصر واشتراه فوطيفار خصي فرعون رئيس الشرط رجل مصري من يد الاسماعيليين الذين انزلوه الى هناك.","39:2":"وكان الرب مع يوسف فكان رجلا ناجحا. وكان في بيت سيده المصري.","39:3":"وراى سيده ان الرب معه وان كل ما يصنع كان الرب ينجحه بيده.","39:4":"فوجد يوسف نعمة في عينيه وخدمه فوكله على بيته ودفع الى يده كل ما كان له.","39:5":"وكان من حين وكله على بيته وعلى كل ما كان له ان الرب بارك بيت المصري بسبب يوسف. وكانت بركة الرب على كل ما كان له في البيت وفي الحقل","39:6":"فترك كل ما كان له في يد يوسف. ولم يكن معه يعرف شيئا الا الخبز الذي ياكل. وكان يوسف حسن الصورة وحسن المنظر.","39:7":"وحدث بعد هذه الامور ان امراة سيده رفعت عينيها الى يوسف وقالت: «اضطجع معي».","39:8":"فابى وقال لامراة سيده: «هوذا سيدي لا يعرف معي ما في البيت وكل ما له قد دفعه الى يدي.","39:9":"ليس هو في هذا البيت اعظم مني. ولم يمسك عني شيئا غيرك لانك امراته. فكيف اصنع هذا الشر العظيم واخطئ الى الله؟»","39:10":"وكان اذ كلمت يوسف يوما فيوما انه لم يسمع لها ان يضطجع بجانبها ليكون معها.","39:11":"ثم حدث نحو هذا الوقت انه دخل البيت ليعمل عمله ولم يكن انسان من اهل البيت هناك في البيت.","39:12":"فامسكته بثوبه قائلة: «اضطجع معي». فترك ثوبه في يدها وهرب وخرج الى خارج.","39:13":"وكان لما رات انه ترك ثوبه في يدها وهرب الى خارج","39:14":"انها نادت اهل بيتها وقالت: «انظروا! قد جاء الينا برجل عبراني ليداعبنا. دخل الي ليضطجع معي فصرخت بصوت عظيم.","39:15":"وكان لما سمع اني رفعت صوتي وصرخت انه ترك ثوبه بجانبي وهرب وخرج الى خارج».","39:16":"فوضعت ثوبه بجانبها حتى جاء سيده الى بيته.","39:17":"فكلمته بمثل هذا الكلام قائلة: «دخل الي العبد العبراني الذي جئت به الينا ليداعبني.","39:18":"وكان لما رفعت صوتي وصرخت انه ترك ثوبه بجانبي وهرب الى خارج».","39:19":"فكان لما سمع سيده كلام امراته الذي كلمته به قائلة: «بحسب هذا الكلام صنع بي عبدك» ان غضبه حمي.","39:20":"فاخذ يوسف ووضعه في بيت السجن المكان الذي كان اسرى الملك محبوسين فيه. وكان هناك في بيت السجن.","39:21":"ولكن الرب كان مع يوسف وبسط اليه لطفا وجعل نعمة له في عيني رئيس بيت السجن.","39:22":"فدفع رئيس بيت السجن الى يد يوسف جميع الاسرى الذين في بيت السجن. وكل ما كانوا يعملون هناك كان هو العامل.","39:23":"ولم يكن رئيس بيت السجن ينظر شيئا البتة مما في يده لان الرب كان معه ومهما صنع كان الرب ينجحه.","40:1":"وحدث بعد هذه الامور ان ساقي ملك مصر والخباز اذنبا الى سيدهما ملك مصر","40:2":"فسخط فرعون على خصييه: رئيس السقاة ورئيس الخبازين","40:3":"فوضعهما في حبس بيت رئيس الشرط في بيت السجن المكان الذي كان يوسف محبوسا فيه.","40:4":"فاقام رئيس الشرط يوسف عندهما فخدمهما. وكانا اياما في الحبس.","40:5":"وحلما كلاهما حلما في ليلة واحدة كل واحد حلمه كل واحد بحسب تعبير حلمه: ساقي ملك مصر وخبازه المحبوسان في بيت السجن.","40:6":"فدخل يوسف اليهما في الصباح ونظرهما واذا هما مغتمان.","40:7":"فسال خصيي فرعون اللذين معه في حبس بيت سيده: «لماذا وجهاكما مكمدان اليوم؟»","40:8":"فقالا له: «حلمنا حلما وليس من يعبره». فقال لهما يوسف: «اليست لله التعابير؟ قصا علي».","40:9":"فقص رئيس السقاة حلمه على يوسف وقال له: «كنت في حلمي واذا كرمة امامي.","40:10":"وفي الكرمة ثلاثة قضبان. وهي اذ افرخت طلع زهرها وانضجت عناقيدها عنبا.","40:11":"وكانت كاس فرعون في يدي. فاخذت العنب وعصرته في كاس فرعون واعطيت الكاس في يد فرعون».","40:12":"فقال له يوسف: «هذا تعبيره: الثلاثة القضبان هي ثلاثة ايام.","40:13":"في ثلاثة ايام ايضا يرفع فرعون راسك ويردك الى مقامك فتعطي كاس فرعون في يده كالعادة الاولى حين كنت ساقيه.","40:14":"وانما اذا ذكرتني عندك حينما يصير لك خير تصنع الي احسانا وتذكرني لفرعون وتخرجني من هذا البيت.","40:15":"لاني قد سرقت من ارض العبرانيين. وهنا ايضا لم افعل شيئا حتى وضعوني في السجن».","40:16":"فلما راى رئيس الخبازين انه عبر جيدا قال ليوسف: «كنت انا ايضا في حلمي واذا ثلاثة سلال بيضاء على راسي.","40:17":"وفي السل الاعلى من جميع طعام فرعون من صنعة الخباز. والطيور تاكله من السل عن راسي».","40:18":"فاجاب يوسف وقال: «هذا تعبيره: الثلاثة السلال هي ثلاثة ايام.","40:19":"في ثلاثة ايام ايضا يرفع فرعون راسك عنك ويعلقك على خشبة وتاكل الطيور لحمك عنك».","40:20":"فحدث في اليوم الثالث يوم ميلاد فرعون انه صنع وليمة لجميع عبيده ورفع راس رئيس السقاة وراس رئيس الخبازين بين عبيده.","40:21":"ورد رئيس السقاة الى سقيه. فاعطى الكاس في يد فرعون.","40:22":"واما رئيس الخبازين فعلقه كما عبر لهما يوسف.","40:23":"ولكن لم يذكر رئيس السقاة يوسف بل نسيه.","41:1":"وحدث من بعد سنتين من الزمان ان فرعون راى حلما واذا هو واقف عند النهر.","41:2":"وهوذا سبع بقرات طالعة من النهر حسنة المنظر وسمينة اللحم فارتعت في روضة.","41:3":"ثم هوذا سبع بقرات اخرى طالعة وراءها من النهر قبيحة المنظر ورقيقة اللحم. فوقفت بجانب البقرات الاولى على شاطئ النهر.","41:4":"فاكلت البقرات القبيحة المنظر والرقيقة اللحم البقرات السبع الحسنة المنظر والسمينة. واستيقظ فرعون.","41:5":"ثم نام فحلم ثانية. وهوذا سبع سنابل طالعة في ساق واحد سمينة وحسنة.","41:6":"ثم هوذا سبع سنابل رقيقة وملفوحة بالريح الشرقية نابتة وراءها.","41:7":"فابتلعت السنابل الرقيقة السنابل السبع السمينة الممتلئة. واستيقظ فرعون واذا هو حلم.","41:8":"وكان في الصباح ان نفسه انزعجت فارسل ودعا جميع سحرة مصر وجميع حكمائها وقص عليهم فرعون حلمه. فلم يكن من يعبره لفرعون.","41:9":"ثم قال رئيس السقاة لفرعون: «انا اتذكر اليوم خطاياي.","41:10":"فرعون سخط على عبديه فجعلني في حبس بيت رئيس الشرط انا ورئيس الخبازين.","41:11":"فحلمنا حلما في ليلة واحدة انا وهو. حلمنا كل واحد بحسب تعبير حلمه.","41:12":"وكان هناك معنا غلام عبراني عبد لرئيس الشرط فقصصنا عليه فعبر لنا حلمينا. عبر لكل واحد بحسب حلمه.","41:13":"وكما عبر لنا هكذا حدث. ردني انا الى مقامي واما هو فعلقه».","41:14":"فارسل فرعون ودعا يوسف فاسرعوا به من السجن. فحلق وابدل ثيابه ودخل على فرعون.","41:15":"فقال فرعون ليوسف: «حلمت حلما وليس من يعبره. وانا سمعت عنك قولا انك تسمع احلاما لتعبرها».","41:16":"فاجاب يوسف فرعون: «ليس لي. الله يجيب بسلامة فرعون».","41:17":"فقال فرعون ليوسف: «اني كنت في حلمي واقفا على شاطئ النهر","41:18":"وهوذا سبع بقرات طالعة من النهر سمينة اللحم وحسنة الصورة. فارتعت في روضة.","41:19":"ثم هوذا سبع بقرات اخرى طالعة وراءها مهزولة وقبيحة الصورة جدا ورقيقة اللحم. لم انظر في كل ارض مصر مثلها في القباحة.","41:20":"فاكلت البقرات الرقيقة والقبيحة البقرات السبع الاولى السمينة.","41:21":"فدخلت اجوافها. ولم يعلم انها دخلت في اجوافها. فكان منظرها قبيحا كما في الاول. واستيقظت.","41:22":"ثم رايت في حلمي وهوذا سبع سنابل طالعة في ساق واحد ممتلئة وحسنة.","41:23":"ثم هوذا سبع سنابل يابسة رقيقة ملفوحة بالريح الشرقية نابتة وراءها.","41:24":"فابتلعت السنابل الرقيقة السنابل السبع الحسنة. فقلت للسحرة ولم يكن من يخبرني».","41:25":"فقال يوسف لفرعون: «حلم فرعون واحد. قد اخبر الله فرعون بما هو صانع.","41:26":"البقرات السبع الحسنة هي سبع سنين. والسنابل السبع الحسنة هي سبع سنين. هو حلم واحد.","41:27":"والبقرات السبع الرقيقة القبيحة التي طلعت وراءها هي سبع سنين. والسنابل السبع الفارغة الملفوحة بالريح الشرقية تكون سبع سنين جوعا.","41:28":"هو الامر الذي كلمت به فرعون. قد اظهر الله لفرعون ما هو صانع.","41:29":"هوذا سبع سنين قادمة شبعا عظيما في كل ارض مصر.","41:30":"ثم تقوم بعدها سبع سنين جوعا فينسى كل الشبع في ارض مصر ويتلف الجوع الارض.","41:31":"ولا يعرف الشبع في الارض من اجل ذلك الجوع بعده لانه يكون شديدا جدا.","41:32":"واما عن تكرار الحلم على فرعون مرتين فلان الامر مقرر من قبل الله والله مسرع ليصنعه.","41:33":"«فالان لينظر فرعون رجلا بصيرا وحكيما ويجعله على ارض مصر.","41:34":"يفعل فرعون فيوكل نظارا على الارض وياخذ خمس غلة ارض مصر في سبع سني الشبع","41:35":"فيجمعون جميع طعام هذه السنين الجيدة القادمة ويخزنون قمحا تحت يد فرعون طعاما. في المدن ويحفظونه.","41:36":"فيكون الطعام ذخيرة للارض لسبع سني الجوع التي تكون في ارض مصر. فلا تنقرض الارض بالجوع».","41:37":"فحسن الكلام في عيني فرعون وفي عيون جميع عبيده.","41:38":"فقال فرعون لعبيده: «هل نجد مثل هذا رجلا فيه روح الله؟»","41:39":"ثم قال فرعون ليوسف: «بعد ما اعلمك الله كل هذا ليس بصير وحكيم مثلك.","41:40":"انت تكون على بيتي وعلى فمك يقبل جميع شعبي. الا ان الكرسي اكون فيه اعظم منك».","41:41":"ثم قال فرعون ليوسف: «انظر. قد جعلتك على كل ارض مصر».","41:42":"وخلع فرعون خاتمه من يده وجعله في يد يوسف والبسه ثياب بوص ووضع طوق ذهب في عنقه","41:43":"واركبه في مركبته الثانية ونادوا امامه «اركعوا». وجعله على كل ارض مصر.","41:44":"وقال فرعون ليوسف: «انا فرعون. فبدونك لا يرفع انسان يده ولا رجله في كل ارض مصر».","41:45":"ودعا فرعون اسم يوسف «صفنات فعنيح». واعطاه اسنات بنت فوطي فارع كاهن اون زوجة. فخرج يوسف على ارض مصر.","41:46":"وكان يوسف ابن ثلاثين سنة لما وقف قدام فرعون ملك مصر. فخرج يوسف من لدن فرعون واجتاز في كل ارض مصر.","41:47":"واثمرت الارض في سبع سني الشبع بحزم.","41:48":"فجمع كل طعام السبع سنين التي كانت في ارض مصر وجعل طعاما في المدن. طعام حقل المدينة الذي حواليها جعله فيها.","41:49":"وخزن يوسف قمحا كرمل البحر كثيرا جدا حتى ترك العدد اذ لم يكن له عدد.","41:50":"وولد ليوسف ابنان قبل ان تاتي سنة الجوع ولدتهما له اسنات بنت فوطي فارع كاهن اون.","41:51":"ودعا يوسف اسم البكر منسى قائلا: «لان الله انساني كل تعبي وكل بيت ابي».","41:52":"ودعا اسم الثاني افرايم قائلا: «لان الله جعلني مثمرا في ارض مذلتي».","41:53":"ثم كملت سبع سني الشبع الذي كان في ارض مصر.","41:54":"وابتدات سبع سني الجوع تاتي كما قال يوسف فكان جوع في جميع البلدان. واما جميع ارض مصر فكان فيها خبز.","41:55":"ولما جاعت جميع ارض مصر وصرخ الشعب الى فرعون لاجل الخبز قال فرعون لكل المصريين: «اذهبوا الى يوسف والذي يقول لكم افعلوا».","41:56":"وكان الجوع على كل وجه الارض. وفتح يوسف جميع ما فيه طعام وباع للمصريين. واشتد الجوع في ارض مصر.","41:57":"وجاءت كل الارض الى مصر الى يوسف لتشتري قمحا لان الجوع كان شديدا في كل الارض.","42:1":"فلما راى يعقوب انه يوجد قمح في مصر قال يعقوب لبنيه: «لماذا تنظرون بعضكم الى بعض؟","42:2":"اني قد سمعت انه يوجد قمح في مصر. انزلوا الى هناك واشتروا لنا من هناك لنحيا ولا نموت».","42:3":"فنزل عشرة من اخوة يوسف ليشتروا قمحا من مصر.","42:4":"واما بنيامين اخو يوسف فلم يرسله يعقوب مع اخوته لانه قال: «لعله تصيبه اذية».","42:5":"فاتى بنو اسرائيل ليشتروا بين الذين اتوا لان الجوع كان في ارض كنعان.","42:6":"وكان يوسف هو المسلط على الارض وهو البائع لكل شعب الارض. فاتى اخوة يوسف وسجدوا له بوجوههم الى الارض.","42:7":"ولما نظر يوسف اخوته عرفهم فتنكر لهم وتكلم معهم بجفاء وقال لهم: «من اين جئتم؟» فقالوا: «من ارض كنعان لنشتري طعاما».","42:8":"وعرف يوسف اخوته واما هم فلم يعرفوه.","42:9":"فتذكر يوسف الاحلام التي حلم عنهم وقال لهم: «جواسيس انتم! لتروا عورة الارض جئتم!»","42:10":"فقالوا له: «لا يا سيدي. بل عبيدك جاءوا ليشتروا طعاما.","42:11":"نحن جميعنا بنو رجل واحد. نحن امناء. ليس عبيدك جواسيس».","42:12":"فقال لهم: «كلا! بل لتروا عورة الارض جئتم».","42:13":"فقالوا: «عبيدك اثنا عشر اخا. نحن بنو رجل واحد في ارض كنعان. وهوذا الصغير عند ابينا اليوم والواحد مفقود».","42:14":"فقال لهم يوسف: «ذلك ما كلمتكم به قائلا: جواسيس انتم.","42:15":"بهذا تمتحنون. وحياة فرعون لا تخرجون من هنا الا بمجيء اخيكم الصغير الى هنا.","42:16":"ارسلوا منكم واحدا ليجيء باخيكم وانتم تحبسون فيمتحن كلامكم هل عندكم صدق. والا فوحياة فرعون انكم لجواسيس!»","42:17":"فجمعهم الى حبس ثلاثة ايام.","42:18":"ثم قال لهم يوسف في اليوم الثالث: «افعلوا هذا واحيوا. انا خائف الله.","42:19":"ان كنتم امناء فليحبس اخ واحد منكم في بيت حبسكم وانطلقوا انتم وخذوا قمحا لمجاعة بيوتكم.","42:20":"واحضروا اخاكم الصغير الي فيتحقق كلامكم ولا تموتوا». ففعلوا هكذا.","42:21":"وقالوا بعضهم لبعض: «حقا اننا مذنبون الى اخينا الذي راينا ضيقة نفسه لما استرحمنا ولم نسمع. لذلك جاءت علينا هذه الضيقة».","42:22":"فاجابهم راوبين: «الم اكلمكم قائلا: لا تاثموا بالولد وانتم لم تسمعوا؟ فهوذا دمه يطلب».","42:23":"وهم لم يعلموا ان يوسف فاهم؛ لان الترجمان كان بينهم.","42:24":"فتحول عنهم وبكى. ثم رجع اليهم وكلمهم واخذ منهم شمعون وقيده امام عيونهم.","42:25":"ثم امر يوسف ان تملا اوعيتهم قمحا وترد فضة كل واحد الى عدله وان يعطوا زادا للطريق. ففعل لهم هكذا.","42:26":"فحملوا قمحهم على حميرهم ومضوا من هناك.","42:27":"فلما فتح احدهم عدله ليعطي عليقا لحماره في المنزل راى فضته واذا هي في فم عدله.","42:28":"فقال لاخوته: «ردت فضتي وها هي في عدلي». فطارت قلوبهم وارتعدوا بعضهم في بعض قائلين: «ما هذا الذي صنعه الله بنا؟».","42:29":"فجاءوا الى يعقوب ابيهم الى ارض كنعان واخبروه بكل ما اصابهم قائلين:","42:30":"«تكلم معنا الرجل سيد الارض بجفاء وحسبنا جواسيس الارض.","42:31":"فقلنا له: نحن امناء. لسنا جواسيس.","42:32":"نحن اثنا عشر اخا بنو ابينا. الواحد مفقود والصغير اليوم عند ابينا في ارض كنعان.","42:33":"فقال لنا الرجل سيد الارض: بهذا اعرف انكم امناء. دعوا اخا واحدا منكم عندي وخذوا لمجاعة بيوتكم وانطلقوا.","42:34":"واحضروا اخاكم الصغير الي فاعرف انكم لستم جواسيس بل انكم امناء فاعطيكم اخاكم وتتجرون في الارض».","42:35":"واذ كانوا يفرغون عدالهم اذا صرة فضة كل واحد في عدله. فلما راوا صرر فضتهم هم وابوهم خافوا.","42:36":"فقال لهم يعقوب: «اعدمتموني الاولاد! يوسف مفقود وشمعون مفقود وبنيامين تاخذونه! صار كل هذا علي!»","42:37":"وقال راوبين لابيه: «اقتل ابني ان لم اجئ به اليك. سلمه بيدي وانا ارده اليك».","42:38":"فقال: «لا ينزل ابني معكم لان اخاه قد مات وهو وحده باق. فان اصابته اذية في الطريق التي تذهبون فيها تنزلون شيبتي بحزن الى الهاوية».","43:1":"وكان الجوع شديدا في الارض.","43:2":"وحدث لما فرغوا من اكل القمح الذي جاءوا به من مصر ان اباهم قال لهم: «ارجعوا اشتروا لنا قليلا من الطعام».","43:3":"فقال له يهوذا: «ان الرجل قد اشهد علينا قائلا: لا ترون وجهي بدون ان يكون اخوكم معكم.","43:4":"ان كنت ترسل اخانا معنا ننزل ونشتري لك طعاما.","43:5":"ولكن ان كنت لا ترسله لا ننزل. لان الرجل قال لنا: لا ترون وجهي بدون ان يكون اخوكم معكم».","43:6":"فقال اسرائيل: «لماذا اساتم الي حتى اخبرتم الرجل ان لكم اخا ايضا؟»","43:7":"فقالوا: «ان الرجل قد سال عنا وعن عشيرتنا قائلا: هل ابوكم حي بعد؟ هل لكم اخ؟ فاخبرناه بحسب هذا الكلام. هل كنا نعلم انه يقول انزلوا باخيكم؟».","43:8":"وقال يهوذا لاسرائيل ابيه: «ارسل الغلام معي لنقوم ونذهب ونحيا ولا نموت نحن وانت واولادنا جميعا.","43:9":"انا اضمنه. من يدي تطلبه. ان لم اجئ به اليك واوقفه قدامك اصر مذنبا اليك كل الايام.","43:10":"لاننا لو لم نتوان لكنا قد رجعنا الان مرتين».","43:11":"فقال لهم اسرائيل ابوهم: «ان كان هكذا فافعلوا هذا: خذوا من افخر جنى الارض في اوعيتكم وانزلوا للرجل هدية. قليلا من البلسان وقليلا من العسل وكثيراء ولاذنا وفستقا ولوزا.","43:12":"وخذوا فضة اخرى في اياديكم. والفضة المردودة في افواه عدالكم ردوها في اياديكم. لعله كان سهوا.","43:13":"وخذوا اخاكم وقوموا ارجعوا الى الرجل.","43:14":"والله القدير يعطيكم رحمة امام الرجل حتى يطلق لكم اخاكم الاخر وبنيامين. وانا اذا عدمت الاولاد عدمتهم».","43:15":"فاخذ الرجال هذه الهدية واخذوا ضعف الفضة في اياديهم وبنيامين وقاموا ونزلوا الى مصر ووقفوا امام يوسف.","43:16":"فلما راى يوسف بنيامين معهم قال للذي على بيته: «ادخل الرجال الى البيت واذبح ذبيحة وهيئ لان الرجال ياكلون معي عند الظهر».","43:17":"ففعل الرجل كما قال يوسف. وادخل الرجل الرجال الى بيت يوسف.","43:18":"فخاف الرجال اذ ادخلوا الى بيت يوسف وقالوا: «لسبب الفضة التي رجعت اولا في عدالنا نحن قد ادخلنا ليهجم علينا ويقع بنا وياخذنا عبيدا وحميرنا».","43:19":"فتقدموا الى الرجل الذي على بيت يوسف وكلموه في باب البيت.","43:20":"وقالوا: «استمع يا سيدي. اننا قد نزلنا اولا لنشتري طعاما.","43:21":"وكان لما اتينا الى المنزل اننا فتحنا عدالنا واذا فضة كل واحد في فم عدله. فضتنا بوزنها. فقد رددناها في ايادينا.","43:22":"وانزلنا فضة اخرى في ايادينا لنشتري طعاما. لا نعلم من وضع فضتنا في عدالنا».","43:23":"فقال: «سلام لكم. لا تخافوا. الهكم واله ابيكم اعطاكم كنزا في عدالكم. فضتكم وصلت الي». ثم اخرج اليهم شمعون.","43:24":"وادخل الرجل الرجال الى بيت يوسف واعطاهم ماء ليغسلوا ارجلهم واعطى عليقا لحميرهم.","43:25":"وهياوا الهدية الى ان يجيء يوسف عند الظهر. لانهم سمعوا انهم هناك ياكلون طعاما.","43:26":"فلما جاء يوسف الى البيت احضروا اليه الهدية التي في اياديهم الى البيت وسجدوا له الى الارض.","43:27":"فسال عن سلامتهم وقال: «اسالم ابوكم الشيخ الذي قلتم عنه؟ احي هو بعد؟»","43:28":"فقالوا: «عبدك ابونا سالم. هو حي بعد». وخروا وسجدوا.","43:29":"فرفع عينيه ونظر بنيامين اخاه ابن امه وقال: «اهذا اخوكم الصغير الذي قلتم لي عنه؟» ثم قال: «الله ينعم عليك يا ابني».","43:30":"واستعجل يوسف لان احشاءه حنت الى اخيه وطلب مكانا ليبكي. فدخل المخدع وبكى هناك.","43:31":"ثم غسل وجهه وخرج وتجلد وقال: «قدموا طعاما».","43:32":"فقدموا له وحده ولهم وحدهم وللمصريين الاكلين عنده وحدهم لان المصريين لا يقدرون ان ياكلوا طعاما مع العبرانيين لانه رجس عند المصريين.","43:33":"فجلسوا قدامه: البكر بحسب بكوريته والصغير بحسب صغره. فبهت الرجال بعضهم الى بعض.","43:34":"ورفع حصصا من قدامه اليهم. فكانت حصة بنيامين اكثر من حصص جميعهم خمسة اضعاف. وشربوا ورووا معه.","44:1":"ثم امر الذي على بيته قائلا: «املا عدال الرجال طعاما حسب ما يطيقون حمله وضع فضة كل واحد في فم عدله.","44:2":"وطاسي طاس الفضة تضع في فم عدل الصغير وثمن قمحه». ففعل بحسب كلام يوسف الذي تكلم به.","44:3":"فلما اضاء الصبح انصرف الرجال هم وحميرهم.","44:4":"ولما كانوا قد خرجوا من المدينة ولم يبتعدوا قال يوسف للذي على بيته: «قم اسع وراء الرجال ومتى ادركتهم فقل لهم: لماذا جازيتم شرا عوضا عن خير؟","44:5":"اليس هذا هو الذي يشرب سيدي فيه؟ وهو يتفاءل به. اساتم في ما صنعتم».","44:6":"فادركهم وقال لهم هذا الكلام.","44:7":"فقالوا له: «لماذا يتكلم سيدي مثل هذا الكلام؟ حاشا لعبيدك ان يفعلوا مثل هذا الامر!","44:8":"هوذا الفضة التي وجدنا في افواه عدالنا رددناها اليك من ارض كنعان. فكيف نسرق من بيت سيدك فضة او ذهبا؟","44:9":"الذي يوجد معه من عبيدك يموت ونحن ايضا نكون عبيدا لسيدي».","44:10":"فقال: «نعم الان بحسب كلامكم هكذا يكون. الذي يوجد معه يكون لي عبدا واما انتم فتكونون ابرياء».","44:11":"فاستعجلوا وانزلوا كل واحد عدله الى الارض وفتحوا كل واحد عدله.","44:12":"ففتش مبتدئا من الكبير حتى انتهى الى الصغير. فوجد الطاس في عدل بنيامين.","44:13":"فمزقوا ثيابهم وحمل كل واحد على حماره ورجعوا الى المدينة.","44:14":"فدخل يهوذا واخوته الى بيت يوسف وهو بعد هناك ووقعوا امامه على الارض.","44:15":"فقال لهم يوسف: «ما هذا الفعل الذي فعلتم؟ الم تعلموا ان رجلا مثلي يتفاءل؟»","44:16":"فقال يهوذا: «ماذا نقول لسيدي؟ ماذا نتكلم وبماذا نتبرر؟ الله قد وجد اثم عبيدك. ها نحن عبيد لسيدي نحن والذي وجد الطاس في يده جميعا».","44:17":"فقال: «حاشا لي ان افعل هذا! الرجل الذي وجد الطاس في يده هو يكون لي عبدا واما انتم فاصعدوا بسلام الى ابيكم».","44:18":"ثم تقدم اليه يهوذا وقال: «استمع يا سيدي. ليتكلم عبدك كلمة في اذني سيدي ولا يحم غضبك على عبدك لانك مثل فرعون.","44:19":"سيدي سال عبيده: هل لكم اب او اخ؟","44:20":"فقلنا لسيدي: لنا اب شيخ وابن شيخوخة صغير مات اخوه وبقي هو وحده لامه وابوه يحبه.","44:21":"فقلت لعبيدك: انزلوا به الي فاجعل نظري عليه.","44:22":"فقلنا لسيدي: لا يقدر الغلام ان يترك اباه. وان ترك اباه يموت.","44:23":"فقلت لعبيدك: ان لم ينزل اخوكم الصغير معكم لا تعودوا تنظرون وجهي.","44:24":"فكان لما صعدنا الى عبدك ابي اننا اخبرناه بكلام سيدي.","44:25":"ثم قال ابونا: ارجعوا اشتروا لنا قليلا من الطعام.","44:26":"فقلنا: لا نقدر ان ننزل. وانما اذا كان اخونا الصغير معنا ننزل لاننا لا نقدر ان ننظر وجه الرجل واخونا الصغير ليس معنا.","44:27":"فقال لنا عبدك ابي: انتم تعلمون ان امراتي ولدت لي اثنين","44:28":"فخرج الواحد من عندي وقلت: انما هو قد افترس افتراسا. ولم انظره الى الان.","44:29":"فاذا اخذتم هذا ايضا من امام وجهي واصابته اذية تنزلون شيبتي بشر الى الهاوية.","44:30":"فالان متى جئت الى عبدك ابي والغلام ليس معنا ونفسه مرتبطة بنفسه","44:31":"يكون متى راى ان الغلام مفقود انه يموت فينزل عبيدك شيبة عبدك ابينا بحزن الى الهاوية","44:32":"لان عبدك ضمن الغلام لابي قائلا: ان لم اجئ به اليك اصر مذنبا الى ابي كل الايام.","44:33":"فالان ليمكث عبدك عوضا عن الغلام عبدا لسيدي ويصعد الغلام مع اخوته.","44:34":"لاني كيف اصعد الى ابي والغلام ليس معي؟ لئلا انظر الشر الذي يصيب ابي!».","45:1":"فلم يستطع يوسف ان يضبط نفسه لدى جميع الواقفين عنده فصرخ: «اخرجوا كل انسان عني!» فلم يقف احد عنده حين عرف يوسف اخوته بنفسه.","45:2":"فاطلق صوته بالبكاء. فسمع المصريون وسمع بيت فرعون.","45:3":"وقال يوسف لاخوته: «انا يوسف. احي ابي بعد؟» فلم يستطع اخوته ان يجيبوه لانهم ارتاعوا منه.","45:4":"فقال يوسف لاخوته: «تقدموا الي». فتقدموا. فقال: «انا يوسف اخوكم الذي بعتموه الى مصر.","45:5":"والان لا تتاسفوا ولا تغتاظوا لانكم بعتموني الى هنا لانه لاستبقاء حياة ارسلني الله قدامكم.","45:6":"لان للجوع في الارض الان سنتين. وخمس سنين ايضا لا تكون فيها فلاحة ولا حصاد.","45:7":"فقد ارسلني الله قدامكم ليجعل لكم بقية في الارض وليستبقي لكم نجاة عظيمة.","45:8":"فالان ليس انتم ارسلتموني الى هنا بل الله. وهو قد جعلني ابا لفرعون وسيدا لكل بيته ومتسلطا على كل ارض مصر.","45:9":"اسرعوا واصعدوا الى ابي وقولوا له: هكذا يقول ابنك يوسف: قد جعلني الله سيدا لكل مصر. انزل الي. لا تقف.","45:10":"فتسكن في ارض جاسان وتكون قريبا مني انت وبنوك وبنو بنيك وغنمك وبقرك وكل ما لك.","45:11":"واعولك هناك لانه يكون ايضا خمس سنين جوعا. لئلا تفتقر انت وبيتك وكل ما لك.","45:12":"وهوذا عيونكم ترى وعينا اخي بنيامين ان فمي هو الذي يكلمكم.","45:13":"وتخبرون ابي بكل مجدي في مصر وبكل ما رايتم وتستعجلون وتنزلون بابي الى هنا».","45:14":"ثم وقع على عنق بنيامين اخيه وبكى. وبكى بنيامين على عنقه.","45:15":"وقبل جميع اخوته وبكى عليهم. وبعد ذلك تكلم اخوته معه.","45:16":"وسمع الخبر في بيت فرعون وقيل: «جاء اخوة يوسف». فحسن في عيني فرعون وفي عيون عبيده.","45:17":"فقال فرعون ليوسف: «قل لاخوتك: افعلوا هذا. حملوا دوابكم وانطلقوا اذهبوا الى ارض كنعان.","45:18":"وخذوا اباكم وبيوتكم وتعالوا الي. فاعطيكم خيرات ارض مصر وتاكلوا دسم الارض.","45:19":"فانت قد امرت. افعلوا هذا. خذوا لكم من ارض مصر عجلات لاولادكم ونسائكم واحملوا اباكم وتعالوا.","45:20":"ولا تحزن عيونكم على اثاثكم لان خيرات جميع ارض مصر لكم».","45:21":"ففعل بنو اسرائيل هكذا. واعطاهم يوسف عجلات بحسب امر فرعون. واعطاهم زادا للطريق.","45:22":"واعطى كل واحد منهم حلل ثياب. واما بنيامين فاعطاه ثلاث مئة من الفضة وخمس حلل ثياب.","45:23":"وارسل لابيه عشرة حمير حاملة من خيرات مصر وعشر اتن حاملة حنطة وخبزا وطعاما لابيه لاجل الطريق.","45:24":"ثم صرف اخوته فانطلقوا وقال لهم: «لا تتغاضبوا في الطريق».","45:25":"فصعدوا من مصر وجاءوا الى ارض كنعان الى يعقوب ابيهم","45:26":"واخبروه قائلين: «يوسف حي بعد وهو متسلط على كل ارض مصر!» فجمد قلبه لانه لم يصدقهم.","45:27":"ثم كلموه بكل كلام يوسف الذي كلمهم به وابصر العجلات التي ارسلها يوسف لتحمله. فعاشت روح يعقوب ابيهم.","45:28":"فقال اسرائيل: «كفى! يوسف ابني حي بعد. اذهب واراه قبل ان اموت».","46:1":"فارتحل اسرائيل وكل ما كان له واتى الى بئر سبع وذبح ذبائح لاله ابيه اسحاق.","46:2":"فكلم الله اسرائيل في رؤى الليل وقال: «يعقوب يعقوب». فقال: «هئنذا».","46:3":"فقال: «انا الله اله ابيك. لا تخف من النزول الى مصر لاني اجعلك امة عظيمة هناك.","46:4":"انا انزل معك الى مصر وانا اصعدك ايضا. ويضع يوسف يده على عينيك».","46:5":"فقام يعقوب من بئر سبع. وحمل بنو اسرائيل يعقوب اباهم واولادهم ونساءهم في العجلات التي ارسل فرعون لحمله.","46:6":"واخذوا مواشيهم ومقتناهم الذي اقتنوا في ارض كنعان وجاءوا الى مصر. يعقوب وكل نسله معه.","46:7":"بنوه وبنو بنيه معه وبناته وبنات بنيه وكل نسله جاء بهم معه الى مصر.","46:8":"وهذه اسماء بني اسرائيل الذين جاءوا الى مصر: يعقوب وبنوه. بكر يعقوب راوبين.","46:9":"وبنو راوبين: حنوك وفلو وحصرون وكرمي.","46:10":"وبنو شمعون: يموئيل ويامين واوهد وياكين وصوحر وشاول ابن الكنعانية.","46:11":"وبنو لاوي: جرشون وقهات ومراري.","46:12":"وبنو يهوذا عير واونان وشيلة وفارص وزارح. واما عير واونان فماتا في ارض كنعان. وكان ابنا فارص حصرون وحامول.","46:13":"وبنو يساكر: تولاع وفوة ويوب وشمرون.","46:14":"وبنو زبولون: سارد وايلون وياحلئيل.","46:15":"هؤلاء بنو ليئة الذين ولدتهم ليعقوب في فدان ارام مع دينة ابنته. جميع نفوس بنيه وبناته ثلاث وثلاثون.","46:16":"وبنو جاد: صفيون وحجي وشوني واصبون وعيري وارودي وارئيلي.","46:17":"وبنو اشير: يمنة ويشوة ويشوي وبريعة وسارح هي اختهم. وابنا بريعة حابر وملكيئيل.","46:18":"هؤلاء بنو زلفة التي اعطاها لابان لليئة ابنته فولدت هؤلاء ليعقوب ست عشرة نفسا.","46:19":"ابنا راحيل امراة يعقوب: يوسف وبنيامين.","46:20":"وولد ليوسف في ارض مصر: منسى وافرايم اللذان ولدتهما له اسنات بنت فوطي فارع كاهن اون.","46:21":"وبنو بنيامين: بالع وباكر واشبيل وجيرا ونعمان وايحي وروش ومفيم وحفيم وارد.","46:22":"هؤلاء بنو راحيل الذين ولدوا ليعقوب. جميع النفوس اربع عشرة.","46:23":"وابن دان حوشيم.","46:24":"وبنو نفتالي: ياحصئيل وجوني ويصر وشليم.","46:25":"هؤلاء بنو بلهة التي اعطاها لابان لراحيل ابنته. فولدت هؤلاء ليعقوب. جميع الانفس سبع.","46:26":"جميع النفوس ليعقوب التي اتت الى مصر الخارجة من صلبه ما عدا نساء بني يعقوب جميع النفوس ست وستون نفسا.","46:27":"وابنا يوسف اللذان ولدا له في مصر نفسان. جميع نفوس بيت يعقوب التي جاءت الى مصر سبعون.","46:28":"فارسل يهوذا امامه الى يوسف ليري الطريق امامه الى جاسان ثم جاءوا الى ارض جاسان.","46:29":"فشد يوسف مركبته وصعد لاستقبال اسرائيل ابيه الى جاسان. ولما ظهر له وقع على عنقه وبكى على عنقه زمانا.","46:30":"فقال اسرائيل ليوسف: «اموت الان بعد ما رايت وجهك انك حي بعد».","46:31":"ثم قال يوسف لاخوته ولبيت ابيه: «اصعد واخبر فرعون واقول له: اخوتي وبيت ابي الذين في ارض كنعان جاءوا الي","46:32":"والرجال رعاة غنم فانهم كانوا اهل مواش وقد جاءوا بغنمهم وبقرهم وكل ما لهم.","46:33":"فيكون اذا دعاكم فرعون وقال: ما صناعتكم؟","46:34":"ان تقولوا: عبيدك اهل مواش منذ صبانا الى الان نحن واباؤنا جميعا. لكي تسكنوا في ارض جاسان. لان كل راعي غنم رجس للمصريين».","47:1":"فاتى يوسف وقال لفرعون: «ابي واخوتي وغنمهم وبقرهم وكل ما لهم جاءوا من ارض كنعان. وهوذا هم في ارض جاسان».","47:2":"واخذ من جملة اخوته خمسة رجال واوقفهم امام فرعون.","47:3":"فقال فرعون لاخوته: «ما صناعتكم؟» فقالوا لفرعون: «عبيدك رعاة غنم نحن واباؤنا جميعا».","47:4":"وقالوا لفرعون: «جئنا لنتغرب في الارض اذ ليس لغنم عبيدك مرعى لان الجوع شديد في ارض كنعان. فالان ليسكن عبيدك في ارض جاسان».","47:5":"فقال فرعون ليوسف: «ابوك واخوتك جاءوا اليك.","47:6":"ارض مصر قدامك. في افضل الارض اسكن اباك واخوتك. ليسكنوا في ارض جاسان. وان علمت انه يوجد بينهم ذوو قدرة فاجعلهم رؤساء مواش على التي لي»","47:7":"ثم ادخل يوسف يعقوب اباه واوقفه امام فرعون. وبارك يعقوب فرعون.","47:8":"فقال فرعون ليعقوب: «كم هي ايام سني حياتك؟»","47:9":"فقال يعقوب لفرعون: «ايام سني غربتي مئة وثلاثون سنة. قليلة وردية كانت ايام سني حياتي ولم تبلغ الى ايام سني حياة ابائي في ايام غربتهم».","47:10":"وبارك يعقوب فرعون وخرج من لدن فرعون.","47:11":"فاسكن يوسف اباه واخوته واعطاهم ملكا في ارض مصر في افضل الارض في ارض رعمسيس كما امر فرعون.","47:12":"وعال يوسف اباه واخوته وكل بيت ابيه بطعام على حسب الاولاد.","47:13":"ولم يكن خبز في كل الارض لان الجوع كان شديدا جدا. فخورت ارض مصر وارض كنعان من اجل الجوع.","47:14":"فجمع يوسف كل الفضة الموجودة في ارض مصر وفي ارض كنعان بالقمح الذي اشتروا. وجاء يوسف بالفضة الى بيت فرعون.","47:15":"فلما فرغت الفضة من ارض مصر ومن ارض كنعان اتى جميع المصريين الى يوسف قائلين: «اعطنا خبزا فلماذا نموت قدامك؟ لان ليس فضة ايضا».","47:16":"فقال يوسف: «هاتوا مواشيكم فاعطيكم بمواشيكم ان لم يكن فضة ايضا».","47:17":"فجاءوا بمواشيهم الى يوسف فاعطاهم يوسف خبزا بالخيل وبمواشي الغنم والبقر وبالحمير. فقاتهم بالخبز تلك السنة بدل جميع مواشيهم.","47:18":"ولما تمت تلك السنة اتوا اليه في السنة الثانية وقالوا له: «لا نخفي عن سيدي انه اذ قد فرغت الفضة ومواشي البهائم عند سيدي لم يبق قدام سيدي الا اجسادنا وارضنا.","47:19":"لماذا نموت امام عينيك نحن وارضنا جميعا؟ اشترنا وارضنا بالخبز فنصير نحن وارضنا عبيدا لفرعون. واعط بذارا لنحيا ولا نموت ولا تصير ارضنا قفرا».","47:20":"فاشترى يوسف كل ارض مصر لفرعون اذ باع المصريون كل واحد حقله لان الجوع اشتد عليهم. فصارت الارض لفرعون.","47:21":"واما الشعب فنقلهم الى المدن من اقصى حد مصر الى اقصاه.","47:22":"الا ان ارض الكهنة لم يشترها اذ كانت للكهنة فريضة من قبل فرعون. فاكلوا فريضتهم التي اعطاهم فرعون. لذلك لم يبيعوا ارضهم.","47:23":"فقال يوسف للشعب: «اني قد اشتريتكم اليوم وارضكم لفرعون. هوذا لكم بذار فتزرعون الارض.","47:24":"ويكون عند الغلة انكم تعطون خمسا لفرعون والاربعة الاجزاء تكون لكم بذارا للحقل وطعاما لكم ولمن في بيوتكم وطعاما لاولادكم».","47:25":"فقالوا: «احييتنا. ليتنا نجد نعمة في عيني سيدي فنكون عبيدا لفرعون».","47:26":"فجعلها يوسف فرضا على ارض مصر الى هذا اليوم: لفرعون الخمس. الا ان ارض الكهنة وحدهم لم تصر لفرعون.","47:27":"وسكن اسرائيل في ارض مصر في ارض جاسان وتملكوا فيها واثمروا وكثروا جدا.","47:28":"وعاش يعقوب في ارض مصر سبع عشرة سنة. فكانت ايام يعقوب سنو حياته مئة وسبعا واربعين سنة.","47:29":"ولما قربت ايام اسرائيل ان يموت دعا ابنه يوسف وقال له: «ان كنت قد وجدت نعمة في عينيك فضع يدك تحت فخذي واصنع معي معروفا وامانة. لا تدفني في مصر.","47:30":"بل اضطجع مع ابائي. فتحملني من مصر وتدفنني في مقبرتهم». فقال: «انا افعل بحسب قولك».","47:31":"فقال: «احلف لي». فحلف له. فسجد اسرائيل على راس السرير.","48:1":"وحدث بعد هذه الامور انه قيل ليوسف: «هوذا ابوك مريض». فاخذ معه ابنيه منسى وافرايم.","48:2":"فاخبر يعقوب وقيل له: «هوذا ابنك يوسف قادم اليك». فتشدد اسرائيل وجلس على السرير.","48:3":"وقال يعقوب ليوسف: «الله القادر على كل شيء ظهر لي في لوز في ارض كنعان وباركني.","48:4":"وقال لي: ها انا اجعلك مثمرا واكثرك واجعلك جمهورا من الامم واعطي نسلك هذه الارض من بعدك ملكا ابديا.","48:5":"والان ابناك المولودان لك في ارض مصر قبلما اتيت اليك الى مصر هما لي. افرايم ومنسى كراوبين وشمعون يكونان لي.","48:6":"واما اولادك الذين تلد بعدهما فيكونون لك. على اسم اخويهم يسمون في نصيبهم.","48:7":"وانا حين جئت من فدان ماتت عندي راحيل في ارض كنعان في الطريق اذ بقيت مسافة من الارض حتى اتي الى افراتة. فدفنتها هناك في طريق افراتة (التي هي بيت لحم)».","48:8":"وراى اسرائيل ابني يوسف فقال: «من هذان؟».","48:9":"فقال يوسف لابيه: «هما ابناي اللذان اعطاني الله ههنا». فقال: «قدمهما الي لاباركهما».","48:10":"واما عينا اسرائيل فكانتا قد ثقلتا من الشيخوخة لا يقدر ان يبصر فقربهما اليه فقبلهما واحتضنهما.","48:11":"وقال اسرائيل ليوسف: «لم اكن اظن اني ارى وجهك وهوذا الله قد اراني نسلك ايضا».","48:12":"ثم اخرجهما يوسف من بين ركبتيه وسجد امام وجهه الى الارض.","48:13":"واخذ يوسف الاثنين افرايم بيمينه عن يسار اسرائيل ومنسى بيساره عن يمين اسرائيل وقربهما اليه.","48:14":"فمد اسرائيل يمينه ووضعها على راس افرايم وهو الصغير ويساره على راس منسى. وضع يديه بفطنة فان منسى كان البكر.","48:15":"وبارك يوسف وقال: «الله الذي سار امامه ابواي ابراهيم واسحاق - الله الذي رعاني منذ وجودي الى هذا اليوم -","48:16":"الملاك الذي خلصني من كل شر يبارك الغلامين. وليدع عليهما اسمي واسم ابوي ابراهيم واسحاق. وليكثرا كثيرا في الارض».","48:17":"فلما راى يوسف ان اباه وضع يده اليمنى على راس افرايم ساء ذلك في عينيه فامسك بيد ابيه لينقلها عن راس افرايم الى راس منسى.","48:18":"وقال يوسف لابيه: «ليس هكذا يا ابي لان هذا هو البكر. ضع يمينك على راسه».","48:19":"فابى ابوه وقال: «علمت يا ابني علمت! هو ايضا يكون شعبا وهو ايضا يصير كبيرا. ولكن اخاه الصغير يكون اكبر منه ونسله يكون جمهورا من الامم».","48:20":"وباركهما في ذلك اليوم قائلا: «بك يبارك اسرائيل قائلا: يجعلك الله كافرايم وكمنسى». فقدم افرايم على منسى.","48:21":"وقال اسرائيل ليوسف: «ها انا اموت ولكن الله سيكون معكم ويردكم الى ارض ابائكم.","48:22":"وانا قد وهبت لك سهما واحدا فوق اخوتك اخذته من يد الاموريين بسيفي وقوسي».","49:1":"ودعا يعقوب بنيه وقال: «اجتمعوا لانبئكم بما يصيبكم في اخر الايام.","49:2":"اجتمعوا واسمعوا يا بني يعقوب واصغوا الى اسرائيل ابيكم.","49:3":"راوبين انت بكري قوتي واول قدرتي فضل الرفعة وفضل العز.","49:4":"فائرا كالماء لا تتفضل لانك صعدت على مضجع ابيك. حينئذ دنسته. على فراشي صعد.","49:5":"شمعون ولاوي اخوان. الات ظلم سيوفهما.","49:6":"في مجلسهما لا تدخل نفسي. بمجمعهما لا تتحد كرامتي. لانهما في غضبهما قتلا انسانا وفي رضاهما عرقبا ثورا.","49:7":"ملعون غضبهما فانه شديد وسخطهما فانه قاس. اقسمهما في يعقوب وافرقهما في اسرائيل.","49:8":"يهوذا اياك يحمد اخوتك. يدك على قفا اعدائك. يسجد لك بنو ابيك.","49:9":"يهوذا جرو اسد. من فريسة صعدت يا ابني. جثا وربض كاسد وكلبوة. من ينهضه؟","49:10":"لا يزول قضيب من يهوذا ومشترع من بين رجليه حتى ياتي شيلون وله يكون خضوع شعوب.","49:11":"رابطا بالكرمة جحشه وبالجفنة ابن اتانه. غسل بالخمر لباسه وبدم العنب ثوبه.","49:12":"مسود العينين من الخمر ومبيض الاسنان من اللبن.","49:13":"زبولون عند ساحل البحر يسكن وهو عند ساحل السفن وجانبه عند صيدون.","49:14":"يساكر حمار جسيم رابض بين الحظائر.","49:15":"فراى المحل انه حسن والارض انها نزهة فاحنى كتفه للحمل وصار للجزية عبدا.","49:16":"دان يدين شعبه كاحد اسباط اسرائيل.","49:17":"يكون دان حية على الطريق افعوانا على السبيل يلسع عقبي الفرس فيسقط راكبه الى الوراء.","49:18":"لخلاصك انتظرت يا رب.","49:19":"جاد يزحمه جيش ولكنه يزحم مؤخره.","49:20":"اشير خبزه سمين وهو يعطي لذات ملوك.","49:21":"نفتالي ايلة مسيبة يعطي اقوالا حسنة.","49:22":"يوسف غصن شجرة مثمرة غصن شجرة مثمرة على عين. اغصان قد ارتفعت فوق حائط.","49:23":"فمررته ورمته واضطهدته ارباب السهام.","49:24":"ولكن ثبتت بمتانة قوسه وتشددت سواعد يديه. من يدي عزيز يعقوب من هناك من الراعي صخر اسرائيل","49:25":"من اله ابيك الذي يعينك ومن القادر على كل شيء الذي يباركك تاتي بركات السماء من فوق وبركات الغمر الرابض تحت. بركات الثديين والرحم.","49:26":"بركات ابيك فاقت على بركات ابوي. الى منية الاكام الدهرية تكون على راس يوسف وعلى قمة نذير اخوته.","49:27":"بنيامين ذئب يفترس. في الصباح ياكل غنيمة وعند المساء يقسم نهبا».","49:28":"جميع هؤلاء هم اسباط اسرائيل الاثنا عشر. وهذا ما كلمهم به ابوهم وباركهم. كل واحد بحسب بركته باركهم.","49:29":"واوصاهم وقال لهم: «انا انضم الى قومي. ادفنوني عند ابائي في المغارة التي في حقل عفرون الحثي.","49:30":"في المغارة التي في حقل المكفيلة التي امام ممرا في ارض كنعان التي اشتراها ابراهيم مع الحقل من عفرون الحثي ملك قبر.","49:31":"هناك دفنوا ابراهيم وسارة امراته. هناك دفنوا اسحاق ورفقة امراته. وهناك دفنت ليئة.","49:32":"شراء الحقل والمغارة التي فيه كان من بني حث».","49:33":"ولما فرغ يعقوب من توصية بنيه ضم رجليه الى السرير واسلم الروح وانضم الى قومه.","50:1":"فوقع يوسف على وجه ابيه وبكى عليه وقبله.","50:2":"وامر يوسف عبيده الاطباء ان يحنطوا اباه. فحنط الاطباء اسرائيل.","50:3":"وكمل له اربعون يوما لانه هكذا تكمل ايام المحنطين. وبكى عليه المصريون سبعين يوما.","50:4":"وبعد ما مضت ايام بكائه قال يوسف لبيت فرعون: «ان كنت قد وجدت نعمة في عيونكم فتكلموا في مسامع فرعون قائلين:","50:5":"ابي استحلفني قائلا: ها انا اموت. في قبري الذي حفرت لنفسي في ارض كنعان هناك تدفنني. فالان اصعد لادفن ابي وارجع».","50:6":"فقال فرعون: «اصعد وادفن اباك كما استحلفك».","50:7":"فصعد يوسف ليدفن اباه وصعد معه جميع عبيد فرعون شيوخ بيته وجميع شيوخ ارض مصر","50:8":"وكل بيت يوسف واخوته وبيت ابيه. غير انهم تركوا اولادهم وغنمهم وبقرهم في ارض جاسان.","50:9":"وصعد معه مركبات وفرسان. فكان الجيش كثيرا جدا.","50:10":"فاتوا الى بيدر اطاد الذي في عبر الاردن وناحوا هناك نوحا عظيما وشديدا جدا. وصنع لابيه مناحة سبعة ايام.","50:11":"فلما راى اهل البلاد الكنعانيون المناحة في بيدر اطاد قالوا: «هذه مناحة ثقيلة للمصريين». لذلك دعي اسمه «ابل مصرايم». الذي في عبر الاردن.","50:12":"وفعل له بنوه كذا كما اوصاهم:","50:13":"حمله بنوه الى ارض كنعان ودفنوه في مغارة حقل المكفيلة التي اشتراها ابراهيم مع الحقل ملك قبر من عفرون الحثي امام ممرا.","50:14":"ثم رجع يوسف الى مصر هو واخوته وجميع الذين صعدوا معه لدفن ابيه بعد ما دفن اباه.","50:15":"ولما راى اخوة يوسف ان اباهم قد مات قالوا: «لعل يوسف يضطهدنا ويرد علينا جميع الشر الذي صنعنا به».","50:16":"فاوصوا الى يوسف قائلين: «ابوك اوصى قبل موته قائلا:","50:17":"هكذا تقولون ليوسف: اه! اصفح عن ذنب اخوتك وخطيتهم فانهم صنعوا بك شرا. فالان اصفح عن ذنب عبيد اله ابيك». فبكى يوسف حين كلموه.","50:18":"واتى اخوته ايضا ووقعوا امامه وقالوا: «ها نحن عبيدك».","50:19":"فقال لهم يوسف: «لا تخافوا. لانه هل انا مكان الله؟","50:20":"انتم قصدتم لي شرا اما الله فقصد به خيرا لكي يفعل كما اليوم ليحيي شعبا كثيرا.","50:21":"فالان لا تخافوا. انا اعولكم واولادكم». فعزاهم وطيب قلوبهم.","50:22":"وسكن يوسف في مصر هو وبيت ابيه. وعاش يوسف مئة وعشر سنين.","50:23":"وراى يوسف لافرايم اولاد الجيل الثالث. واولاد ماكير بن منسى ايضا ولدوا على ركبتي يوسف.","50:24":"وقال يوسف لاخوته: «انا اموت ولكن الله سيفتقدكم ويصعدكم من هذه الارض الى الارض التي حلف لابراهيم واسحاق ويعقوب».","50:25":"واستحلف يوسف بني اسرائيل قائلا: «الله سيفتقدكم فتصعدون عظامي من هنا».","50:26":"ثم مات يوسف وهو ابن مئة وعشر سنين فحنطوه ووضع في تابوت في مصر."};
